import{n as i}from"./shared-CAKwAg2C.js";const a={"LEARN HOW THE INTERNET WORKS":"SO FUNKTIONIERT DAS INTERNET","NOW LEARNING":"AKTUELLE LEKTION","OSI LAYER":"OSI-SCHICHT","LEARNING PROGRESS":"DEIN FORTSCHRITT",COMPLETE:"FERTIG","IN PROGRESS":"IN ARBEIT","{pct}% complete":"{pct} % abgeschlossen","DESIGNED BY":"GESTALTET VON","Dilum Sanjaya on X":"Dilum Sanjaya auf X","Layer {n}: {name}":"Schicht {n}: {name}",Physical:"Bitübertragung","Data Link":"Sicherung",Network:"Vermittlung",Transport:"Transport",Session:"Sitzung",Presentation:"Darstellung",Application:"Anwendung","OVERVIEW · {n} STEPS":"ÜBERSICHT · {n} SCHRITTE","STEP {n}/{total} · {title}":"SCHRITT {n}/{total} · {title}","LESSON COMPLETE":"LEKTION ABGESCHLOSSEN",PROTOCOLS:"PROTOKOLLE",Protocols:"Protokolle",Language:"Sprache",Theme:"Design","Light mode":"Heller Modus","Dark mode":"Dunkler Modus","INTERNET PROTOCOLS":"INTERNETPROTOKOLLE",More:"Mehr","Close the protocol list":"Protokollliste schließen","Close (Esc)":"Schließen (Esc)",ALL:"ALLE",CORE:"BASIS",APPLICATION:"ANWENDUNG",SECURITY:"SICHERHEIT",NETWORK:"NETZWERK",SEQUENCE:"SEQUENZ",View:"Ansicht","Switch view (V)":"Ansicht wechseln (V)","Network diagram":"Netzwerkdiagramm","Sequence diagram":"Sequenzdiagramm","STEP {n}":"SCHRITT {n}","PROTOCOL OVERVIEW":"ÜBERSICHT","STEP DETAILS":"SCHRITTDETAILS","LESSON SUMMARY":"ZUSAMMENFASSUNG",OVERVIEW:"START",ACTIVE:"AKTIV","STEP {n} OF {total}":"SCHRITT {n} VON {total}","PACKET {n} OF {total}":"PAKET {n} VON {total}","PACKETS {from}–{to} OF {total}":"PAKETE {from}–{to} VON {total}","{n} LOST":"{n} VERLOREN","1 LOST":"1 VERLOREN",ENCRYPTED:"VERSCHLÜSSELT","LOST ON THE WAY":"UNTERWEGS VERLOREN","PACKET FLOW":"PAKETFLUSS","Colour key":"Farblegende","Playback speed":"Wiedergabegeschwindigkeit","Previous step (←)":"Vorheriger Schritt (←)","Previous step":"Vorheriger Schritt","Play / pause (Space)":"Abspielen / Pause (Leertaste)",PLAY:"ABSPIELEN",PAUSE:"PAUSE",REPLAY:"NOCHMAL",STEP:"SCHRITT","One packet at a time":"Ein Paket nach dem anderen",RESET:"ZURÜCKSETZEN",Reset:"Zurücksetzen","Back to the overview (Esc)":"Zurück zur Übersicht (Esc)","NO.":"NR.",TIME:"ZEIT",SOURCE:"QUELLE",DESTINATION:"ZIEL",PROTOCOL:"PROTOKOLL",INFO:"INFO",SIZE:"GRÖSSE","No packets on the wire yet.":"Noch keine Pakete unterwegs.",LOST:"VERLOREN","Packet inspector":"Paketinspektor","Previous packet":"Vorheriges Paket","Previous packet (←)":"Vorheriges Paket (←)","Next packet":"Nächstes Paket","Next packet (→)":"Nächstes Paket (→)",Close:"Schließen","E.G.":"BSP.","an example value: it differs in every real capture":"ein Beispielwert: in jeder echten Aufzeichnung anders","bytes the lesson can’t show: encrypted, random, or a file’s contents":"Bytes, die die Lektion nicht zeigen kann: verschlüsselt, zufällig oder der Inhalt einer Datei",BYTES:"BYTES","{n} in this frame":"{n} in diesem Frame","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Diese Zeile steht für {n} TCP-Segmente mit einer Nachricht von {size} Bytes; gezeigt wird das erste Segment","This packet was lost on the way":"Dieses Paket ging unterwegs verloren",Padding:"Auffüllung","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · LEASE 24 H","2 SEGMENTS":"2 SEGMENTE","3 SEGMENTS":"3 SEGMENTE","3 DATAGRAMS":"3 DATAGRAMME","4 DATAGRAMS":"4 DATAGRAMME","203.0.113.10 IS NOT LOCAL":"203.0.113.10 IST NICHT LOKAL","250 QUEUED":"250 IN WARTESCHLANGE",ANSWER:"ANTWORT","APP COVERS THE 20 MS GAP":"APP ÜBERBRÜCKT DIE 20-MS-LÜCKE","APP DATA":"APP-DATEN","ARP REPLY":"ARP-ANTWORT","ARP REQUEST":"ARP-ANFRAGE","ARRIVED WITH TTL 116":"ANGEKOMMEN MIT TTL 116","AUTH FAILURE":"AUTH FEHLGESCHLAGEN","At QUIT":"Bei QUIT","CACHED · TTL 3600 S":"IM CACHE · TTL 3600 S","CERTIFICATE VALID":"ZERTIFIKAT GÜLTIG","CHAIN LEADS TO A TRUSTED ROOT":"KETTE FÜHRT ZU EINER VERTRAUTEN ROOT","CHANNEL OPEN":"KANAL ÖFFNEN",CONFIRMED:"BESTÄTIGT","DNS QUERY":"DNS-ANFRAGE","DNS REPLY":"DNS-ANTWORT","DUP ACK":"DOPPEL-ACK","EACH KEY IS ITS OWN PACKET":"JEDE TASTE EIN EIGENES PAKET",ECHO:"ECHO","ECHO REPLY":"ECHO-ANTWORT","ECHO REQUEST":"ECHO-ANFRAGE",ENTER:"EINGABE","FRAME 7 LOST · NOT RESENT":"FRAME 7 VERLOREN · NICHT ERNEUT GESENDET","HOP 2 · 198.51.100.1":"HOP 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"HOST-SCHLÜSSEL PASST ZU KNOWN_HOSTS","IN BOB’S MAILBOX":"IN BOBS POSTFACH","IP PACKET":"IP-PAKET",MESSAGE:"NACHRICHT","MESSAGE 1 DELETED":"NACHRICHT 1 GELÖSCHT","NEW MAIL ARRIVED":"NEUE MAIL EINGETROFFEN","NO IP ADDRESS YET":"NOCH KEINE IP-ADRESSE","NOT IN CACHE":"NICHT IM CACHE","OFFER KEY":"SCHLÜSSEL ANBIETEN",OUTPUT:"AUSGABE","PASSWORD IN PLAIN TEXT":"PASSWORT IM KLARTEXT",REFERRAL:"VERWEIS",REPLY:"ANTWORT",RESEND:"ERNEUT SENDEN","SEGMENT 1 LOST":"SEGMENT 1 VERLOREN","SFTP or FTPS":"SFTP oder FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP oder FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"GEMEINSAMES GEHEIMNIS BERECHNET",SIGNED:"SIGNIERT","STILL ON SERVER · \\SEEN":"NOCH AUF DEM SERVER · \\SEEN",SUCCESS:"ERFOLG","TIME EXCEEDED":"ZEIT ÜBERSCHRITTEN","TIME=34MS TTL=52":"ZEIT=34MS TTL=52",UNREACHABLE:"UNERREICHBAR",VERSION:"VERSION","VOICE 1":"STIMME 1","+OK or -ERR":"+OK oder -ERR",".com Server":".com-Server",Authoritative:"Autoritativ","Log In":"Anmelden",Key:"Schlüssel",Why:"Warum",End:"Ende","MACs, in":"MACs, eingehend",Internet:"Internet",Router:"Router","Router 192.168.1.1":"Router 192.168.1.1","Router: 192.168.1.1":"Router: 192.168.1.1",Routers:"Router",Hardware:"Hardware",Audio:"Audio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic Cookie",Visible:"Sichtbar",Tickets:"Tickets","4, 20 bytes":"4, 20 Bytes","20–60 bytes":"20–60 Bytes","20–60 bytes (IPv4)":"20–60 Bytes (IPv4)","8 bytes (TCP: 20+)":"8 Bytes (TCP: 20+)","32 bytes (Windows)":"32 Bytes (Windows)","1,460 bytes (MSS)":"1,460 Bytes (MSS)","78 bytes (seq 1–78)":"78 Bytes (seq 1–78)","bytes 1461–2920":"Bytes 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 Bytes)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 Bytes)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 Bytes), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 Bytes)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 Bytes)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 Bytes)',"32 bits (IPv4), 128 (IPv6)":"32 Bit (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 Router)","52 (64 − 12 routers)":"52 (64 − 12 Router)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 Bytes","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 Bytes (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + Audio","One packet at a time (S)":"Ein Paket nach dem anderen (S)","KEYBOARD SHORTCUTS":"TASTENKÜRZEL","Press {key} any time to see these again.":"Mit {key} kannst du sie jederzeit wieder ansehen.","Search protocols":"Protokolle suchen","Search protocols and steps":"Protokolle und Schritte suchen","Nothing matches.":"Keine Treffer.","to move":"zum Bewegen","to open":"zum Öffnen","Protocol list":"Protokollliste","Diagram only":"Nur Diagramm",Fullscreen:"Vollbild","Keyboard shortcuts":"Tastenkürzel",Playback:"Wiedergabe","Hide the protocol list (L)":"Protokollliste ausblenden (L)","Diagram only (D)":"Nur Diagramm (D)","Fullscreen (F)":"Vollbild (F)","Keyboard shortcuts (?)":"Tastenkürzel (?)","Show the protocol list (L)":"Protokollliste einblenden (L)","Show all panels (D)":"Alle Bereiche zeigen (D)","Exit fullscreen (F)":"Vollbild beenden (F)","Play or pause":"Abspielen oder pausieren","Next step":"Nächster Schritt","Go to step 1 to 9":"Zu Schritt 1 bis 9","Slower, faster":"Langsamer, schneller","Back to the overview":"Zurück zur Übersicht","Network or sequence view":"Netzwerk- oder Sequenzansicht","Show or hide the protocol list":"Protokollliste ein- oder ausblenden","Light or dark theme":"Helles oder dunkles Design",Find:"Suchen","Next or previous protocol":"Nächstes oder vorheriges Protokoll","These shortcuts":"Diese Tastenkürzel","Previous or next packet":"Vorheriges oder nächstes Paket","Close it":"Schließen"},o={"Hypertext Transfer Protocol":"Hypertext-Übertragung","HTTP Secure":"Sicheres HTTP","Transmission Control Protocol":"Übertragungssteuerung","User Datagram Protocol":"Benutzer-Datagramme","Internet Protocol":"Internetprotokoll","Domain Name System":"Domain-Namenssystem","Dynamic Host Configuration":"Dynamische Host-Konfiguration","Internet Control Message":"Internet-Steuernachrichten","Simple Mail Transfer Protocol":"Einfacher Mailtransfer","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Internet-Nachrichtenzugriff","File Transfer Protocol":"Dateiübertragung","Secure Shell":"Sichere Shell","Transport Layer Security":"Transportschicht-Sicherheit",Internet:"Internet",Client:"Client",Router:"Router","DNS Resolver":"DNS-Resolver","Web Server":"Webserver","Root Server":"Root-Server",".com TLD Server":".com-TLD-Server","Authoritative Server":"Autoritativer Server","Mail Server":"Mailserver","Web Communication":"Webkommunikation",Request:"Anfrage",Response:"Antwort","Data ACKs not shown":"Daten-ACKs nicht gezeigt","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP ist das Protokoll des Webs: Ein Client fragt eine Ressource an, etwa eine HTML-Seite, und der Server antwortet mit einem Statuscode, Headern und meist einem Body. Jeder Austausch besteht aus einer Anfrage und einer Antwort, in HTTP/1.1 als lesbarer Text geschrieben.",Layer:"Schicht","Application (Layer 7)":"Anwendung (Schicht 7)","Default Port":"Standardport",Transport:"Transport","Data Format":"Datenformat","Text (headers + optional body)":"Text (Header + optionaler Body)","Common Methods":"Häufige Methoden","Defined In":"Definiert in","Page delivered":"Seite ausgeliefert","One request, one response":"Eine Anfrage, eine Antwort","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"In weniger als einer Zehntelsekunde hat der Laptop eine Adresse nachgeschlagen, eine TCP-Verbindung geöffnet und eine HTTP-Anfrage und -Antwort ausgetauscht, alles für jeden auf dem Weg lesbar. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Round trips":"Round Trips","Total time":"Gesamtzeit","Page size":"Seitengröße","Sent as 9 TCP segments":"In 9 TCP-Segmenten gesendet","Client Request":"Anfrage des Clients","Browser prepares the request":"Der Browser bereitet die Anfrage vor","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Du öffnest http://www.example.com. Der Browser wird eine GET-Anfrage senden, aber Pakete reisen zu IP-Adressen, nicht zu Namen, also braucht er zuerst die Adresse des Servers. (Browser versuchen heute zuerst https://; dies ist die unverschlüsselte Variante.)",Method:"Methode","Next hop":"Nächster Hop","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"DNS-Auflösung","Finds the server’s IP address":"Findet die IP-Adresse des Servers","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Der Laptop fragt den DNS-Server, den er per DHCP bekommen hat, 8.8.8.8, nach der Adresse von www.example.com. Die Anfrage läuft über UDP-Port 53, und die Antwort ist ein A-Record mit der IPv4-Adresse. (In einem Netz mit IPv6 würde er auch nach einem AAAA-Record fragen.)",Resolver:"Resolver","8.8.8.8 (had it cached)":"8.8.8.8 (hatte sie im Cache)","UDP, port 53":"UDP, Port 53",Answer:"Antwort","TCP Connection":"TCP-Verbindung","Establishes a reliable link":"Baut eine zuverlässige Verbindung auf","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP läuft über TCP. Bevor irgendwelche Seitendaten fließen, öffnen Laptop und Server mit einem Drei-Wege-Handshake eine Verbindung zu Port 80: SYN, SYN-ACK, ACK.","Server port":"Server-Port","Client port":"Client-Port",Handshake:"Handshake","HTTP Exchange":"HTTP-Austausch","Request and response messages":"Anfrage- und Antwortnachrichten","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Der Browser sendet eine GET-Anfrage mit einem Host-Header. Der Server antwortet mit 200 OK und dem HTML im Body: 12.2 KB, zu groß für ein Paket, also teilt TCP es in 9 Segmente von bis zu 1460 Bytes auf (hier als eines gezeichnet).",Status:"Status",Body:"Body","Sent as":"Gesendet als","12.2 KB in 9 segments":"12.2 KB in 9 Segmenten","Page Rendering":"Seitendarstellung","Browser displays the content":"Der Browser zeigt den Inhalt an","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Der Browser parst das HTML und zeichnet die Seite. Verlinktes CSS, Bilder und Skripte würden jeweils weitere Anfragen wie diese starten und dabei, wo möglich, die offene Verbindung wiederverwenden.",Document:"Dokument",Connection:"Verbindung","Kept open for reuse":"Für Wiederverwendung offen gehalten","Seen on the laptop’s home network":"Gesehen im Heimnetz des Laptops",Destination:"Ziel","The router: anything beyond the home network goes to it first.":"Der Router: Alles außerhalb des Heimnetzes geht zuerst an ihn.",Source:"Quelle","The laptop’s network card.":"Die Netzwerkkarte des Laptops.",Type:"Typ","What the frame carries.":"Was der Frame transportiert.","Version, header length":"Version, Headerlänge","IPv4, with no options.":"IPv4, ohne Optionen.","Priority and congestion marks; 0 means ordinary traffic.":"Prioritäts- und Staumarkierungen; 0 heißt normaler Verkehr.","Total length":"Gesamtlänge","This header and everything inside it.":"Dieser Header und alles darin.",Identification:"Identifikation","Lets the receiver reassemble the pieces if the packet gets split.":"Lässt den Empfänger die Teile wieder zusammensetzen, falls das Paket aufgeteilt wird.",Flags:"Flags",none:"keine","Routers may split it if a link is too small.":"Router dürfen es aufteilen, wenn eine Strecke zu klein ist.","Time to live":"Time to Live","Windows starts at 128.":"Windows beginnt bei 128.",Protocol:"Protokoll","Header checksum":"Header-Prüfsumme","Covers this header only; every router recomputes it after lowering the TTL.":"Deckt nur diesen Header ab; jeder Router berechnet sie neu, nachdem er die TTL gesenkt hat.","Source port":"Quellport","Destination port":"Zielport",Length:"Länge","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"UDP-Header und Daten. Das ist ganz UDP: keine Nummerierung, keine Bestätigungen.",Checksum:"Prüfsumme","Covers the header, the data and the IP addresses.":"Deckt Header, Daten und die IP-Adressen ab.","Transaction ID":"Transaktions-ID","Picked at random; the answer must carry the same one.":"Zufällig gewählt; die Antwort muss dieselbe tragen.","0x0100: query, RD (recursion desired)":"0x0100: Anfrage, RD (Rekursion gewünscht)",Questions:"Fragen",Answers:"Antworten","Authority records":"Autoritätseinträge","Additional records":"Zusätzliche Einträge",Question:"Frage","www.example.com, type A, class IN":"www.example.com, Typ A, Klasse IN","The laptop.":"Der Laptop.","The router’s side facing the home network.":"Die dem Heimnetz zugewandte Seite des Routers.","Started at 128; 10 routers on the way each took 1.":"Begann bei 128; jeder der 10 Router auf dem Weg zog 1 ab.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: Antwort, RD (Rekursion gewünscht), RA (Rekursion verfügbar)","DF (don’t fragment)":"DF (nicht fragmentieren)","Routers must not split it; if it’s too big they report back instead.":"Router dürfen es nicht aufteilen; ist es zu groß, melden sie das zurück.","Picked by the laptop’s system for this connection.":"Vom System des Laptops für diese Verbindung gewählt.","Sequence number":"Sequenznummer","This side’s starting number. Shown as 0; the real one is random.":"Die Startnummer dieser Seite. Als 0 angezeigt; die echte ist zufällig.","Real sequence number":"Echte Sequenznummer",Acknowledgment:"Bestätigung","0 (not used yet)":"0 (noch nicht verwendet)","A first SYN has nothing to acknowledge.":"Ein erstes SYN hat nichts zu bestätigen.","Header length":"Headerlänge","20 bytes, plus 12 of options.":"20 Bytes plus 12 Bytes Optionen.",Window:"Fenster","How much more data this side can take right now.":"Wie viele Daten diese Seite gerade noch aufnehmen kann.","Covers the header, the data and the IP addresses, so damage is caught.":"Deckt Header, Daten und die IP-Adressen ab, damit Schäden auffallen.","Urgent pointer":"Urgent-Zeiger",Options:"Optionen","Maximum segment size":"Maximale Segmentgröße","The most data this side wants in one segment.":"Die meisten Daten, die diese Seite in einem Segment haben will.","Spacing, so the next option lines up.":"Füller, damit die nächste Option ausgerichtet ist.","Window scale":"Fensterskalierung","Window values are multiplied by this, so windows can be larger than 64 KB.":"Fensterwerte werden damit multipliziert, sodass Fenster größer als 64 KB sein können.","SACK permitted":"SACK erlaubt",yes:"ja","This side understands selective acknowledgements.":"Diese Seite versteht selektive Bestätigungen.","Started at 64; 12 routers on the way each took 1.":"Begann bei 64; jeder der 12 Router auf dem Weg zog 1 ab.","The next byte this side expects: everything before it has arrived.":"Das nächste Byte, das diese Seite erwartet: Alles davor ist angekommen.","Position of this segment’s first byte, counted from this side’s SYN.":"Position des ersten Bytes dieses Segments, gezählt ab dem SYN dieser Seite.",Padding:"Auffüllung","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Ethernet-Frames sind mindestens 60 Bytes lang (64 mit der Prüfsumme, die die Karte anhängt), daher werden kurze aufgefüllt.",Text:"Text","covers bytes not shown here":"deckt Bytes ab, die hier nicht gezeigt werden","12,500 bytes: the HTML page":"12,500 Bytes: die HTML-Seite","The page itself; its contents are not part of the lesson.":"Die Seite selbst; ihr Inhalt ist nicht Teil der Lektion.","Secure Web":"Sicheres Web","TLS handshake":"TLS-Handshake","HTTP request":"HTTP-Anfrage","HTTP response":"HTTP-Antwort","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS ist HTTP, gesendet über eine verschlüsselte TLS-Verbindung. TLS beweist mit einem Zertifikat, dass der Server der ist, für den er sich ausgibt, vereinbart frische Schlüssel und schützt dann jede Anfrage und Antwort davor, unterwegs gelesen oder verändert zu werden.","Application (HTTP over TLS)":"Anwendung (HTTP über TLS)",Security:"Sicherheit","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 noch verbreitet)",Proves:"Beweist","Server identity (certificate)":"Serveridentität (Zertifikat)","Secure page delivered":"Sichere Seite ausgeliefert","Encrypted, except the lookup":"Verschlüsselt, bis auf die DNS-Abfrage","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Der Browser hat die Adresse per unverschlüsseltem DNS nachgeschlagen, eine TCP-Verbindung geöffnet, das Zertifikat des Servers geprüft und in einem einzigen Round Trip Schlüssel vereinbart. Jedes HTTP-Byte danach reiste verschlüsselt. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Cipher:"Cipher","Still visible":"Noch sichtbar","IPs, server name, sizes":"IPs, Servername, Größen","Secure Request":"Sichere Anfrage","Browser asks for https://":"Der Browser fragt nach https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Du tippst https://www.example.com. Das „s“ sagt dem Browser, die Verbindung mit TLS zu schützen, standardmäßig auf Port 443. Bevor er sich überhaupt verbinden kann, muss er noch die IP-Adresse des Servers finden.",Port:"Port","DNS Lookup":"DNS-Abfrage","Same lookup as HTTP, not encrypted":"Dieselbe Abfrage wie bei HTTP, unverschlüsselt","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Die Abfrage ist genau dieselbe wie bei einfachem HTTP: eine Anfrage an 8.8.8.8 über UDP-Port 53. Sie ist nicht verschlüsselt, also kann jeder auf dem Weg sehen, nach welchem Namen du gefragt hast, es sei denn, der Browser nutzt DNS over HTTPS.",Encrypted:"Verschlüsselt","No (plain DNS)":"Nein (normales DNS)","TCP Handshake":"TCP-Handshake","Opens a connection to port 443":"Öffnet eine Verbindung zu Port 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS läuft auf TCP, also kommt zuerst derselbe Drei-Wege-Handshake, diesmal zu Port 443. Noch ist nichts verschlüsselt.","TLS Handshake":"TLS-Handshake","Agrees on keys, checks the certificate":"Vereinbart Schlüssel, prüft das Zertifikat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Der Browser bietet Cipher und Key Shares an, darunter einen Post-Quanten-Hybrid. Der Server wählt ihn und schickt seinen eigenen Share, dann sein Zertifikat, bereits verschlüsselt. Der Browser prüft es gegen Zertifizierungsstellen, denen er vertraut.",Version:"Version","Key exchange":"Schlüsselaustausch","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (Hybrid)","Server name":"Servername","Sent in clear (SNI)":"Im Klartext gesendet (SNI)","key shares: hybrid + x25519":"Key Shares: Hybrid + x25519","cipher: AES_128_GCM_SHA256":"Cipher: AES_128_GCM_SHA256","then encrypted: cert, Finished":"dann verschlüsselt: Zert., Finished","handshake complete (encrypted)":"Handshake fertig (verschlüsselt)","Encrypted Exchange":"Verschlüsselter Austausch","HTTP inside TLS records":"HTTP in TLS-Records","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET und 200 OK sind dieselben HTTP-Nachrichten wie zuvor, versiegelt in TLS-Records, die auf der Leitung wie zufällige „Anwendungsdaten“ aussehen. Der Server übergibt außerdem zwei Session-Tickets, damit ein späterer Besuch einen Teil des Handshakes überspringen kann.",Inside:"Darin","GET / and 200 OK":"GET / und 200 OK",Tickets:"Tickets","2, for faster reconnects":"2, für schnellere Neuverbindungen","inside: GET / HTTP/1.1":"innen: GET / HTTP/1.1","outside: encrypted bytes":"außen: verschlüsselte Bytes","inside: HTTP/1.1 200 OK":"innen: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"außen: 12.9 KB, 9 Segmente","Browser shows the padlock":"Der Browser zeigt das Schloss","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Der Browser entschlüsselt die Antwort, zeichnet die Seite und zeigt ein Schloss: Die Verbindung ist privat, und der Server hat seine Identität bewiesen. Der Header Strict-Transport-Security sagt ihm, für diese Seite ab jetzt HTTPS zu verwenden.",Remembers:"Merkt sich","HTTPS only (HSTS), 1 year":"Nur HTTPS (HSTS), 1 Jahr","Server Hello + encrypted handshake, 3 segments":"Server Hello + verschlüsselter Handshake, 3 Segmente","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (verschlüsselt)","Application Data (HTTP request)":"Application Data (HTTP-Anfrage)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (verschlüsselt)","Application Data (HTTP response), 9 segments":"Application Data (HTTP-Antwort), 9 Segmente",Record:"Record","Content type":"Inhaltstyp","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Der Record eines Client Hello gibt TLS 1.0 an, damit alte Middleboxes ihn durchlassen; die echten Versionen werden darin angeboten.","Handshake type":"Handshake-Typ",Contents:"Inhalt","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Alles, was der Browser unterstützt. Browser variieren einige Details von Verbindung zu Verbindung.","Server name (SNI)":"Servername (SNI)","Versions offered":"Angebotene Versionen","Key shares":"Key Shares","App protocols (ALPN)":"Anwendungsprotokolle (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"TLS-1.3-Records geben außen 1.2 an, aus Kompatibilitätsgründen.","The server’s choices and its half of the hybrid key exchange.":"Die Auswahl des Servers und seine Hälfte des hybriden Schlüsselaustauschs.","Cipher suite":"Cipher-Suite","Key share":"Key Share","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Hat in TLS 1.3 keine Aufgabe; wird gesendet, damit Middleboxes einen vertrauten Handshake sehen.","Every encrypted record says Application Data on the outside; the real type is inside.":"Jeder verschlüsselte Record gibt außen Application Data an; der echte Typ steckt darin.","Encrypted data":"Verschlüsselte Daten","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Chiffretext, endend mit einem 16-Byte-Tag, das jede Änderung verrät. Nur die beiden Enden können ihn lesen.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (die Kette), Certificate Verify (die Signatur), Finished","Finished: a check value over the whole handshake":"Finished: ein Prüfwert über den ganzen Handshake","The HTTP request":"Die HTTP-Anfrage","New Session Ticket: lets a later visit resume":"New Session Ticket: lässt einen späteren Besuch die Sitzung fortsetzen","The HTTP response, then the 12,500-byte page":"Die HTTP-Antwort, dann die 12,500 Bytes große Seite","Reliable Delivery":"Zuverlässig zustellen","Handshake and ACKs":"Handshake und ACKs","Data from laptop":"Daten vom Laptop","Data from server":"Daten vom Server","Closing (FIN)":"Abbau (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP macht aus der Best-Effort-Paketzustellung des Internets einen zuverlässigen, geordneten Bytestrom. Es nummeriert jedes Byte, bestätigt, was ankommt, sendet erneut, was fehlt, und bremst den Sender, damit weder die Gegenseite noch das Netz überlastet wird.","Transport (Layer 4)":"Transport (Schicht 4)","Three-way handshake":"Drei-Wege-Handshake",Reliability:"Zuverlässigkeit","Sequence numbers + ACKs":"Sequenznummern + ACKs",Recovery:"Wiederherstellung",Retransmission:"Neuübertragung",Header:"Header","Connection closed":"Verbindung geschlossen","Every byte accounted for":"Jedes Byte erfasst","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP hat eine Verbindung geöffnet, jedes Byte nummeriert und bestätigt, eine Lücke bemerkt und nur das fehlende Segment erneut gesendet und dann beide Richtungen sauber geschlossen. curl hat jedes Byte in der richtigen Reihenfolge erhalten und den Verlust nie bemerkt. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Segments:"Segmente","14 (1 lost, 1 resent)":"14 (1 verloren, 1 erneut gesendet)","Bytes delivered":"Zugestellte Bytes","78 up, 2,920 down":"78 hoch, 2,920 runter","Loss found by":"Verlust erkannt durch","Duplicate ACK + SACK":"Doppeltes ACK + SACK","Open Connection":"Verbindung öffnen","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl kennt die Adresse des Servers bereits. Bevor Daten fließen, wählen beide Seiten eine Startsequenznummer und bestätigen sie: SYN, SYN-ACK, ACK. Die Nummern hier sind relativ; echte beginnen bei einem Zufallswert.",Server:"Server","203.0.113.10, port 80":"203.0.113.10, Port 80","Send Data":"Daten senden","Every byte is numbered":"Jedes Byte ist nummeriert","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl sendet seine 78 Bytes lange HTTP-Anfrage: Bytes 1 bis 78. Die ACK-Nummer des Servers, 79, ist das nächste Byte, das er erwartet, also ist alles davor angekommen.",Sent:"Gesendet","79 = next byte expected":"79 = nächstes erwartetes Byte","Two Segments Back":"Zwei Segmente zurück","One of them is lost":"Eines davon geht verloren","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Der Server antwortet mit 2,920 Bytes: zwei volle Segmente zu je 1,460 Bytes, das Maximum, das hier in ein Paket passt, direkt hintereinander gesendet. Das erste geht irgendwo im Internet verloren; das zweite kommt durch.","Segment 1":"Segment 1","bytes 1–1460 (lost)":"Bytes 1–1460 (verloren)","Segment 2":"Segment 2","Segment size":"Segmentgröße","seq=1 and seq=1461":"seq=1 und seq=1461","the first is lost":"das erste geht verloren","A Gap Is Noticed":"Eine Lücke fällt auf","Duplicate ACK with SACK":"Doppeltes ACK mit SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Die Bytes 1461–2920 kommen an, 1–1460 aber nie. Ein ACK kann nur in Reihenfolge empfangene Bytes zählen, also wiederholt der Laptop sofort ACK 1 und fügt einen SACK-Block hinzu, der sagt, dass er 1461–2920 schon hat.","1 (still waiting for byte 1)":"1 (wartet noch auf Byte 1)","holds bytes 1461–2920":"hat Bytes 1461–2920","At once, not delayed":"Sofort, nicht verzögert","sack: has 1461–2920":"sack: hat 1461–2920","Resend the Gap":"Die Lücke erneut senden","Only the missing bytes":"Nur die fehlenden Bytes","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"Der SACK sagt dem Server genau, was fehlt, also sendet er nur Segment 1 erneut, und der Laptop bestätigt alles. Wäre gar kein ACK zurückgekommen, hätten Timer übernommen: zuerst eine Probe nach etwa zwei Umläufen, dann das Neuübertragungs-Timeout (unter Linux mindestens 200 ms).",Resent:"Erneut gesendet","bytes 1–1460 only":"nur Bytes 1–1460","Next ACK":"Nächstes ACK","2921 (everything)":"2921 (alles)","curl saw":"curl sah","Every byte, in order":"Jedes Byte, in Reihenfolge","just the missing segment":"nur das fehlende Segment","Close Connection":"Verbindung schließen","Each side says goodbye":"Jede Seite verabschiedet sich","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl ist fertig und schließt deshalb. Jede Richtung schließt für sich: Der Laptop sendet FIN und der Server bestätigt es, dann sendet der Server sein eigenes FIN und der Laptop bestätigt das. Der Laptop behält die Verbindungsdaten noch eine Weile (TIME-WAIT).","Closed by":"Geschlossen durch","A FIN from each side":"Ein FIN von jeder Seite",Order:"Reihenfolge",Then:"Danach","Laptop waits (TIME-WAIT)":"Laptop wartet (TIME-WAIT)",Data:"Daten","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 Bytes: die HTTP-Antwort, Bytes 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 Bytes: die HTTP-Antwort, Bytes 1461–2920","has 1461–2920":"hat 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Bytes, die nach der Lücke ankamen, sodass nur die Lücke erneut gesendet werden muss.","Fast Datagrams":"Schnelle Datagramme","Your voice":"Deine Stimme","Their voice":"Die andere Stimme","Media Server":"Medienserver","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP schickt Daten in unabhängigen Paketen, den Datagrammen: ohne Verbindung, ohne Bestätigungen und ohne erneutes Senden. Das hält es schnell und schlank: richtig für Sprache, Video, Spiele und DNS, wo eine verspätete Antwort schlimmer ist als eine fehlende.",None:"Keine","None (no ACKs, no resends)":"Keine (keine ACKs, kein erneutes Senden)",Ordering:"Reihenfolge","Not guaranteed":"Nicht garantiert","Call keeps flowing":"Das Gespräch läuft weiter","Fast, simple, no guarantees":"Schnell, einfach, ohne Garantien","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Der Ton begann schon mit dem allerersten Paket, jedes Datagramm reiste für sich, und das verlorene war einfach weg: UDP hat es nie bemerkt. Die App hat die Lücke überbrückt, und das Gespräch lief weiter. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Datagrams:"Datagramme","11 (1 lost, never resent)":"11 (1 verloren, nie erneut gesendet)","Setup time":"Aufbauzeit","0 ms (no handshake)":"0 ms (kein Handshake)",Shown:"Gezeigt","The first 0.2 s of a call":"Die ersten 0.2 s eines Anrufs","Send Right Away":"Sofort senden","No handshake, data goes first":"Kein Handshake, die Daten gehen zuerst","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Eine Anruf-App kennt Adresse und Port des Medienservers schon von der Anmeldung. Sie baut keine Verbindung auf: Schon das allererste Datagramm trägt 20 ms deiner Stimme, hinter einem 8 Byte langen UDP-Header.",Setup:"Aufbau",Ports:"Ports","92 B of audio, no setup":"92 B Ton, kein Aufbau","A Stream of Datagrams":"Ein Strom von Datagrammen","One every 20 ms, each on its own":"Eins alle 20 ms, jedes für sich","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Die App schickt weiter alle 20 ms ein Datagramm. Jedes steht für sich, mit eigenem Header und ohne Bezug zu den anderen. UDP nummeriert sie nicht, und nichts kommt zurück, um ihre Ankunft zu bestätigen.",Rate:"Takt","1 datagram / 20 ms":"1 Datagramm / 20 ms",Numbering:"Nummerierung","None in UDP itself":"Keine in UDP selbst",Confirmation:"Bestätigung","None (no ACKs)":"Keine (keine ACKs)","voice frames 2–5":"Sprachrahmen 2–5","each with its own 8-byte header":"jeder mit eigenem 8-Byte-Header","Lost on the Way":"Unterwegs verloren","Nobody resends it":"Niemand sendet ihn erneut","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Rahmen 7 geht irgendwo im Internet verloren. Der Medienserver fordert ihn nie an, und UDP sagt dem Laptop nie Bescheid: Es gibt keine Bestätigungen, deren Fehlen auffallen könnte. Die Datagramme danach kommen ganz normal an.",Lost:"Verloren","Voice frame 7":"Sprachrahmen 7","Never (no ACKs)":"Nie (keine ACKs)",Missing:"Fehlt","20 ms of audio":"20 ms Ton","voice frames 6–8":"Sprachrahmen 6–8","frame 7 is lost":"Rahmen 7 geht verloren","Replies Come Back":"Antworten kommen zurück","The other voice comes back":"Die andere Stimme kommt zurück","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Die Stimme der anderen Person kommt genauso an, als einzelne Datagramme an Port 50000. Sie kommen herein, weil sich dein Router den ausgehenden Port gemerkt hat, als er deine Adresse übersetzt hat (NAT).",Direction:"Richtung","Independent of ours":"Unabhängig von unserer","Through NAT":"Durch NAT","Router remembers the port":"Der Router merkt sich den Port","the other person’s voice":"die Stimme der anderen Person","sent to port 50000":"an Port 50000 gesendet","The App Decides":"Die App entscheidet","Reliability is up to the app":"Zuverlässigkeit ist Sache der App","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Die Anruf-App nummeriert ihre Rahmen selbst (das macht RTP), sieht also, dass Rahmen 7 fehlt, und glättet die 20-ms-Lücke, statt zu warten. Auf ein erneutes Senden zu warten, würde das ganze Gespräch verzögern.","App’s job (e.g. RTP)":"Aufgabe der App (z. B. RTP)",Loss:"Verlust","Hidden by the app":"Von der App verdeckt","Also on UDP":"Ebenfalls über UDP","DNS, games, QUIC":"DNS, Spiele, QUIC","Version etc.":"Version usw.","2, no padding, no extension, no CSRCs":"2, kein Padding, keine Erweiterung, keine CSRCs","Marker, payload type":"Marker, Nutzdatentyp","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, beim Aufbau des Anrufs vereinbart)","Counts up by one per packet, so the app can spot a missing or late one.":"Zählt pro Paket um eins hoch, damit die App ein fehlendes oder verspätetes erkennt.",Timestamp:"Zeitstempel","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Audiotakt mit 48,000 pro Sekunde: +960 pro 20-ms-Rahmen.","Identifies this audio stream.":"Kennzeichnet diesen Audiostrom.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 Byte Opus-Audio (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, beim Aufbau des Anrufs vereinbart)","Addressing & Routing":"Adressen und Routing","Outgoing packet":"Ausgehendes Paket",Reply:"Antwort","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP gibt jedem Gerät eine Adresse und bringt Pakete von Netz zu Netz. Jeder Router schaut nur auf die Zieladresse, um den nächsten Hop zu wählen. IP arbeitet nach dem Best-Effort-Prinzip: Es verspricht weder Zustellung noch Reihenfolge. Das fügt TCP obendrauf hinzu.","Network (Layer 3)":"Vermittlung (Schicht 3)",Address:"Adresse","Lowered by 1 at each router":"An jedem Router um 1 gesenkt",Delivery:"Zustellung","Best effort":"Best Effort","There and back":"Hin und zurück","Twelve routers each way":"Zwölf Router in jede Richtung","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Der Laptop schickte das Paket an seinen Router, der seine öffentliche Adresse einsetzte. Insgesamt zwölf Router reichten es allein anhand der Zieladresse weiter, und die Antwort fand auf dieselbe Weise zurück. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Routers:"Router","12 each way (1 home + 11)":"12 pro Richtung (1 daheim + 11)","TTL at server":"TTL am Server","116 (sent with 128)":"116 (mit 128 gesendet)","Rewritten by NAT":"Von NAT umgeschrieben","Source out, destination back":"Quelle hin, Ziel zurück","IPv4 (IPv6 works alike)":"IPv4 (IPv6 funktioniert genauso)","Local or Not?":"Lokal oder nicht?","Compare the address with the subnet":"Adresse mit dem Subnetz vergleichen","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Der Laptop hat 192.168.1.10 mit einer /24-Maske, sein eigenes Netz reicht also von 192.168.1.0 bis 192.168.1.255. Der Server, 203.0.113.10, liegt außerhalb dieses Bereichs, also muss das Paket zum Standardgateway: dem Router zu Hause.",Laptop:"Laptop","Local range":"Lokaler Bereich",Gateway:"Gateway","Find the Router":"Den Router finden","ARP turns an IP into a MAC":"ARP macht aus einer IP eine MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Im lokalen Netz werden Frames per MAC-Adresse zugestellt. Steht die MAC des Routers nicht im ARP-Cache des Laptops, fragt er per Broadcast „Wer hat 192.168.1.1?“, und der Router antwortet mit seiner MAC-Adresse.",Asks:"Fragt","Who has 192.168.1.1?":"Wer hat 192.168.1.1?","Sent to":"Gesendet an","Everyone (broadcast)":"Alle (Broadcast)",Learns:"Erfährt","Router’s MAC address":"MAC-Adresse des Routers","who has 192.168.1.1?":"wer hat 192.168.1.1?","tell 192.168.1.10":"an 192.168.1.10 melden","Send the Packet":"Das Paket senden","Addresses, TTL and protocol":"Adressen, TTL und Protokoll","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Der IP-Header enthält Quell- und Zieladresse, eine TTL und das enthaltene Protokoll. Hier steckt ein TCP-SYN an Port 443 darin. Windows beginnt die TTL bei 128 (Linux und macOS nehmen 64).","From → to":"Von → an","TTL 128 · protocol TCP":"TTL 128 · Protokoll TCP","NAT, Then Hop by Hop":"NAT, dann Hop für Hop","The router rewrites and forwards":"Der Router schreibt um und leitet weiter","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Der Router ersetzt die private Quelle durch seine öffentliche Adresse 198.51.100.7 (und hier Port 52344 durch 40112), notiert die Zuordnung und senkt die TTL auf 127. Dann wählen 11 Router im Internet jeweils anhand des Ziels den nächsten Hop und senken die TTL weiter.","New source":"Neue Quelle","Leaves home":"Verlässt das Zuhause","At the server":"Am Server","TTL 116 (11 more hops)":"TTL 116 (11 Hops mehr)","TTL 127 · after NAT":"TTL 127 · nach NAT","The Reply Comes Back":"Die Antwort kommt zurück","NAT translates it for the laptop":"NAT übersetzt sie für den Laptop","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Der Server antwortet an die Adresse, die er gesehen hat, 198.51.100.7:40112. Der Router schlägt sie in seiner NAT-Tabelle nach, schreibt das Ziel zurück auf 192.168.1.10:52344 und gibt sie weiter. Die Antwort startete mit TTL 64 und kommt mit 52 an.","Delivered to":"Zugestellt an","TTL 52 · after NAT":"TTL 52 · nach NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (nach NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (nach NAT)","ARP request · 28 bytes":"ARP-Anfrage · 28 Byte","Broadcast: every device on the network receives it.":"Broadcast: Jedes Gerät im Netz empfängt sie.","The sender’s network card.":"Die Netzwerkkarte des Absenders.","Hardware type":"Hardwaretyp","Protocol type":"Protokolltyp","Address sizes":"Adresslängen",Operation:"Operation","1 (request: who has …?)":"1 (Anfrage: Wer hat …?)","Sender MAC":"Absender-MAC","Sender IP":"Absender-IP","Target MAC":"Ziel-MAC","All zeros: this is what the request wants to find out.":"Nur Nullen: Genau das will die Anfrage herausfinden.","Target IP":"Ziel-IP","ARP reply · 28 bytes":"ARP-Antwort · 28 Byte","Straight back to the device that asked.":"Direkt zurück an das Gerät, das gefragt hat.","2 (reply: … is at …)":"2 (Antwort: … ist bei …)","Seen as it leaves the router’s internet side":"Gesehen beim Verlassen der Internetseite des Routers","The internet provider’s router, the next hop.":"Der Router des Internetanbieters, der nächste Hop.","The router’s internet-facing port.":"Der zum Internet zeigende Anschluss des Routers.","As sent: this system starts at 64.":"Wie gesendet: Dieses System beginnt bei 64.","The router’s NAT swapped in its own port for the laptop’s.":"Das NAT des Routers hat den Port des Laptops durch seinen eigenen ersetzt.","The sender’s next router; each hop puts the packet in a new frame.":"Der nächste Router des Absenders; bei jedem Hop kommt das Paket in einen neuen Frame.","Name Resolution":"Namensauflösung",Query:"Anfrage",Referral:"Verweis","DNSSEC not requested here":"DNSSEC hier nicht angefordert","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS macht aus Namen wie www.example.com die IP-Adressen, über die sich Computer erreichen. Kein einzelner Server kennt alle Namen: Das System ist eine Hierarchie von Servern, und Antworten werden unterwegs zwischengespeichert, sodass die meisten Abfragen nie weit gehen müssen.","53, UDP (TCP if large)":"53, UDP (TCP, wenn groß)",Turns:"Macht aus","Names into IP addresses":"Namen IP-Adressen",Hierarchy:"Hierarchie","Root → TLD → authoritative":"Root → TLD → autoritativ",Caching:"Caching","For each record’s TTL":"Für die TTL jedes Eintrags","Name resolved":"Name aufgelöst","And remembered for an hour":"Und eine Stunde lang gemerkt","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Mit leerem Cache ging der Resolver von der Root über .com zum eigenen Server von example.com und antwortete dann dem Laptop. Bis die TTL abläuft, wird die nächste Abfrage dieses Namens direkt aus einem Cache beantwortet. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Queries:"Anfragen","4 (laptop 1, resolver 3)":"4 (Laptop 1, Resolver 3)","Cached for":"Zwischengespeichert für","Ask the Resolver":"Den Resolver fragen","The laptop hands the question off":"Der Laptop gibt die Frage ab","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Der Browser braucht die IP-Adresse von www.example.com, und weder er noch Windows hat sie im Cache. Der Laptop schickt eine einzige Frage an den ihm zugewiesenen rekursiven Resolver, 8.8.8.8, und bittet ihn, die ganze Abfrage zu erledigen (Rekursion gewünscht).","www.example.com, type A":"www.example.com, Typ A",Asked:"Gefragt","8.8.8.8 (recursive)":"8.8.8.8 (rekursiv)","RD (recursion desired)":"RD (Rekursion gewünscht)","flags: RD":"Flags: RD","Points the way to .com":"Weist den Weg zu .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Der Cache des Resolvers ist leer (er ist gerade gestartet), also fängt er ganz oben an. Ein Root-Server kennt die Adresse nicht, weiß aber, welche Server für .com zuständig sind, und antwortet mit einem Verweis. Viele Resolver schicken ihm nur „com“, nicht den ganzen Namen.","Root servers":"Root-Server","13 names, 1,000+ anycast sites":"13 Namen, über 1,000 Anycast-Standorte","Referral (13 .com servers)":"Verweis (13 .com-Server)","no answer: ask .com":"keine Antwort: frag .com","Points the way to example.com":"Weist den Weg zu example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Der Resolver fragt einen der .com-Server. Auch sie speichern nicht die Adressen aller Websites, wissen aber, welche Nameserver jede .com-Domain nutzt. Diese Antwort ist also ein weiterer Verweis, mit den Adressen dieser Server (Glue) dabei.",Knows:"Kennt","Name servers of .com domains":"Nameserver der .com-Domains","Referral + glue addresses":"Verweis + Glue-Adressen","no answer: ask example.com":"keine Antwort: frag example.com","Gives the actual answer":"Gibt die eigentliche Antwort","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Schließlich fragt der Resolver den eigenen Nameserver von example.com, der die Einträge der Domain hat. Er antwortet mit dem A-Eintrag und kennzeichnet die Antwort als autoritativ. Wie lange sie zwischengespeichert werden darf, legt der Domaininhaber fest: hier 3600 Sekunden.","AA (authoritative), TTL 3600":"AA (autoritativ), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · Flag AA","Answer & Cache":"Antwort und Cache","The laptop gets its address":"Der Laptop bekommt seine Adresse","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Der Resolver schickt die Antwort an den Laptop zurück und behält eine Kopie. In der nächsten Stunde kann er diesen Namen sofort beantworten, deshalb dauerte die Abfrage in der HTTP-Lektion nur 24 ms. Auch der Laptop speichert sie zwischen.","RD, RA (recursion available)":"RD, RA (Rekursion verfügbar)","Cached by":"Zwischengespeichert von","Resolver and laptop":"Resolver und Laptop","flags: RD RA":"Flags: RD RA","Referral: com. NS ×13 (with glue)":"Verweis: com. NS ×13 (mit Glue)","Referral: example.com. NS ×2 (with glue)":"Verweis: example.com. NS ×2 (mit Glue)","Response A 203.0.113.10 (authoritative)":"Antwort A 203.0.113.10 (autoritativ)","As sent: this system starts at 128.":"Wie gesendet: Dieses System beginnt bei 128.","0x0000: query":"0x0000: Anfrage","UDP size 1232, DNSSEC OK = 0":"UDP-Größe 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Gibt an, wie groß eine UDP-Antwort sein darf. DNSSEC-Signaturen werden hier nicht angefordert, damit die Lektion kurz bleibt; ein validierender Resolver wie 8.8.8.8 fordert sie an.","0x8000: response":"0x8000: Antwort",Authority:"Autorität",Additional:"Zusätzlich","0x8400: response, AA (authoritative)":"0x8400: Antwort, AA (autoritativ)","Getting an Address":"Eine Adresse bekommen","From the laptop":"Vom Laptop","From the DHCP server":"Vom DHCP-Server","Dynamic Host Configuration Protocol":"Protokoll zur dynamischen Host-Konfiguration","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP gibt einem Gerät alles, was es braucht, um ein Netz zu nutzen: eine IP-Adresse, die Subnetzmaske, den Router, über den der Verkehr läuft, und die DNS-Server, die es fragen soll. Adressen werden für eine feste Zeit verliehen (Lease) und verlängert, solange das Gerät im Netz bleibt.","UDP 67 (server), 68 (client)":"UDP 67 (Server), 68 (Client)","Hands out":"Vergibt","IP, mask, gateway, DNS":"IP, Maske, Gateway, DNS",Exchange:"Austausch",Lease:"Lease","Renewed at half its time":"Zur Hälfte der Zeit verlängert","On the network":"Im Netz","Leased, and kept up to date":"Geleast und aktuell gehalten","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Vier Nachrichten brachten den Laptop von keiner Adresse zu einer funktionierenden Konfiguration, und nach der Hälfte der 24-Stunden-Lease verlängerte er sie mit einer direkten Anfrage an den Router. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Messages:"Nachrichten","4 to join, 2 per renewal":"4 zum Beitreten, 2 pro Verlängerung","24 h, renewed at 12 h":"24 h, verlängert nach 12 h","No Address Yet":"Noch keine Adresse","The laptop joins the network":"Der Laptop tritt dem Netz bei","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Der Laptop hat sich gerade verbunden. Er hat eine fest eingebaute MAC-Adresse, aber keine IP-Adresse, kein Gateway und keinen DNS-Server, kann also noch mit nichts außerhalb seines eigenen Netzes reden. Das alles fragt er per DHCP an.","IP address":"IP-Adresse","None (uses 0.0.0.0)":"Keine (nutzt 0.0.0.0)","MAC address":"MAC-Adresse",Needs:"Braucht",Discover:"Suche","Shout to the whole network":"Ruf ins ganze Netz","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Ohne eigene Adresse sendet der Laptop von 0.0.0.0 an die Broadcast-Adresse 255.255.255.255, sodass jedes Gerät im lokalen Netz die Nachricht empfängt. Nur DHCP-Server antworten.",From:"Von","0.0.0.0, UDP port 68":"0.0.0.0, UDP-Port 68","255.255.255.255, port 67":"255.255.255.255, Port 67",Carries:"Enthält","MAC, transaction ID":"MAC, Transaktions-ID","any DHCP server out there?":"ist da draußen ein DHCP-Server?",Offer:"Angebot","The router proposes an address":"Der Router schlägt eine Adresse vor","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Der DHCP-Server des Routers wählt eine freie Adresse und bietet sie mit den übrigen Einstellungen an. Der Laptop kann noch keine IP-Adresse nutzen, also geht das Angebot direkt an seine MAC-Adresse (manche Clients bitten stattdessen um einen Broadcast).",Offered:"Angeboten","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"Angebot: 192.168.1.10/24","gateway, DNS, lease 24 h":"Gateway, DNS, Lease 24 h","Accept, out loud":"Annehmen, laut","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Der Laptop fordert die angebotene Adresse an und nennt dabei den Server, den er gewählt hat. Er sendet weiter per Broadcast, damit jeder andere DHCP-Server, der ein Angebot gemacht hat, erfährt, dass er nicht gewählt wurde, und seine Adresse freigeben kann.",Requests:"Fordert an","Chosen server":"Gewählter Server","I’ll take 192.168.1.10":"Ich nehme 192.168.1.10","from server 192.168.1.1":"von Server 192.168.1.1",Acknowledge:"Bestätigung","The address is the laptop’s":"Die Adresse gehört dem Laptop","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Der Server bestätigt, und der Laptop richtet Adresse, Maske, Gateway und DNS-Server ein. Viele Systeme prüfen vorher per ARP, ob nicht schon ein anderes Gerät die Adresse nutzt.","DNS server":"DNS-Server","192.168.1.10 is yours":"192.168.1.10 gehört dir","for 24 hours":"für 24 Stunden",Renew:"Verlängern","Halfway through the lease":"Zur Hälfte der Lease","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Zwölf Stunden später ist die Hälfte der Lease vorbei. Der Laptop hat jetzt eine Adresse, also bittet er den Router direkt, die Lease zu verlängern, und der Router setzt sie wieder auf 24 Stunden. Würde der Router nicht antworten, würde er bei 87.5 % einen Broadcast senden.",When:"Wann","50% of lease (T1 = 12 h)":"50 % der Lease (T1 = 12 h)","The router (unicast)":"Der Router (Unicast)","If unanswered":"Ohne Antwort","Broadcast at 87.5% (T2)":"Broadcast bei 87.5 % (T2)","renew 192.168.1.10":"192.168.1.10 verlängern","sent straight to 192.168.1.1":"direkt an 192.168.1.1 gesendet","lease renewed":"Lease verlängert","another 24 hours":"weitere 24 Stunden",Message:"Nachricht","1 (request, from a client)":"1 (Anfrage, von einem Client)",Hardware:"Hardware","Ethernet, 6-byte addresses":"Ethernet, 6-Byte-Adressen",Hops:"Hops","Chosen by the client; every reply repeats it.":"Vom Client gewählt; jede Antwort wiederholt sie.",Seconds:"Sekunden","0x0000 (unicast replies are fine)":"0x0000 (Unicast-Antworten sind in Ordnung)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Broadcast-Flag aus: Der Server darf direkt an die MAC-Adresse des Clients senden.","Client address":"Client-Adresse","Filled in only when the client already has an address (renewing).":"Nur ausgefüllt, wenn der Client schon eine Adresse hat (Verlängerung).","Your address":"Deine Adresse","The address the server is giving out.":"Die Adresse, die der Server vergibt.","Next server":"Nächster Server","Relay agent":"Relay-Agent","Client MAC":"Client-MAC","Server name, boot file":"Servername, Bootdatei",empty:"leer","Magic cookie":"Magic Cookie","Marks the options that follow as DHCP.":"Kennzeichnet die folgenden Optionen als DHCP.","Message type: 1 (Discover)":"Nachrichtentyp: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Client-Kennung: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Hostname: alice-laptop","Vendor class: MSFT 5.0":"Herstellerklasse: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Gewünschte Parameter: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (Antwort, von einem Server)","Message type: 2 (Offer)":"Nachrichtentyp: 2 (Offer)","Server identifier: 192.168.1.1":"Server-Kennung: 192.168.1.1","Lease time: 86,400 s (24 h)":"Lease-Dauer: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Verlängerungszeit (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Neubindungszeit (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Subnetzmaske: 255.255.255.0","Broadcast address: 192.168.1.255":"Broadcast-Adresse: 192.168.1.255","DNS server: 8.8.8.8":"DNS-Server: 8.8.8.8","Message type: 3 (Request)":"Nachrichtentyp: 3 (Request)","Requested address: 192.168.1.10":"Angeforderte Adresse: 192.168.1.10","Client FQDN: alice-laptop":"Client-FQDN: alice-laptop","Message type: 5 (ACK)":"Nachrichtentyp: 5 (ACK)","Network Diagnostics":"Netzwerkdiagnose","Ping / probe":"Ping / Test","Echo reply":"Echo-Antwort","Error report":"Fehlermeldung","Internet Control Message Protocol":"Internet-Steuernachrichtenprotokoll","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"Über ICMP meldet sich das Netz zurück: Ein Router meldet, dass die Zeit eines Pakets abgelaufen ist, ein Server meldet, dass an einem Port nichts lauscht. Werkzeuge wie ping und traceroute bestehen aus diesen Nachrichten. ICMP reist in IP, trägt aber keine Anwendungsdaten.","Carried in":"Steckt in","IP (protocol 1)":"IP (Protokoll 1)","A type and a code":"Ein Typ und ein Code",Tools:"Werkzeuge",Often:"Oft","Filtered by firewalls":"Von Firewalls gefiltert","The network answered":"Das Netz hat geantwortet","Replies, expiries and errors":"Antworten, Abläufe und Fehler","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Eine Echo-Anfrage hat die Umlaufzeit gemessen, Pakete mit kleiner TTL brachten jeden Router auf dem Weg dazu, sich zu melden, und ein geschlossener Port wurde sofort zurückgemeldet. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Round trip":"Umlaufzeit",Path:"Weg","12 routers, server at hop 13":"12 Router, Server bei Hop 13","Types used":"Genutzte Typen","8, 0, 11 and 3":"8, 0, 11 und 3","Reply TTL":"TTL der Antwort",Ping:"Ping","Echo request":"Echo-Anfrage","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"„ping -n 1 203.0.113.10“ sendet eine ICMP-Echo-Anfrage (einfaches ping sendet vier, im Abstand von einer Sekunde): Typ 8, Code 0, mit einer Kennung, einer Sequenznummer und 32 Byte Füllung. Das System des Servers antwortet von selbst, ganz ohne Anwendung.","Type, code":"Typ, Code","8, 0 (echo request)":"8, 0 (Echo-Anfrage)","type 8 · seq 1":"Typ 8 · Seq 1","32 bytes of data":"32 Byte Daten","Echo Reply":"Echo-Antwort","Round-trip time":"Umlaufzeit","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Der Server schickt eine Echo-Antwort zurück, Typ 0, mit derselben Kennung, Sequenznummer und denselben Daten. Ping zeigt die Dauer an und die TTL, mit der die Antwort ankam: „Bytes=32 Zeit=34ms TTL=52“.","0, 0 (echo reply)":"0, 0 (Echo-Antwort)","TTL on arrival":"TTL bei Ankunft","type 0 · seq 1":"Typ 0 · Seq 1","same 32 bytes back":"dieselben 32 Byte zurück","The first router answers":"Der erste Router antwortet","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"„ping -n 1 -i 1“ sendet dieselbe Anfrage mit einer TTL von 1. Der Router zu Hause senkt sie auf 0, muss das Paket also verwerfen, und schickt von seiner eigenen Adresse eine Time-Exceeded-Nachricht (Zeit überschritten) zurück: „Antwort von 192.168.1.1: TTL beim Transport abgelaufen.“","Sent with":"Gesendet mit","Dropped by":"Verworfen von","11, 0 (time exceeded)":"11, 0 (Zeit überschritten)","echo request":"Echo-Anfrage","expires at the first router":"läuft am ersten Router ab","type 11 · from 192.168.1.1":"Typ 11 · von 192.168.1.1","quotes the dropped header":"zitiert den verworfenen Header","The next router answers":"Der nächste Router antwortet","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Mit „-i 2“ senkt der Router zu Hause die TTL auf 1 und leitet weiter. Der erste Router beim Internetanbieter senkt sie auf 0 und meldet sich von 198.51.100.1 zurück. Der Router zu Hause übersetzt die Meldung wie jede Antwort zurück an den Laptop.","ISP router 198.51.100.1":"Provider-Router 198.51.100.1","expires at the second router":"läuft am zweiten Router ab","type 11 · from 198.51.100.1":"Typ 11 · von 198.51.100.1","That’s Traceroute":"Das ist Traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … bis zur Ankunft","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert automatisiert das: Es erhöht die TTL jedes Mal um eins, sendet drei Tests pro Hop und listet auf, wer sich meldet. Die Hops 3 bis 12 funktionieren genauso, und mit TTL 13 erreicht die Anfrage endlich den Server, der normal antwortet.","12 routers, then the server":"12 Router, dann der Server","Per hop":"Pro Hop","3 probes":"3 Tests","On Linux":"Unter Linux","traceroute sends UDP":"traceroute sendet UDP","enough hops to arrive":"genug Hops zum Ankommen","the server itself answers":"der Server selbst antwortet","end of the route":"Ende der Route",Unreachable:"Unerreichbar","Nothing listening on that port":"An diesem Port lauscht nichts","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Eine App schickt ein UDP-Datagramm an Port 9999, an dem nichts lauscht. Der Server kann es nicht zustellen, also antwortet er mit „Ziel unerreichbar“, Code 3 (Port unerreichbar), und zitiert den Anfang des Datagramms. Viele Firewalls verwerfen solche Pakete stattdessen stillschweigend.","3, 3 (port unreachable)":"3, 3 (Port unerreichbar)","Other codes":"Andere Codes","0 net, 1 host, 4 too big":"0 Netz, 1 Host, 4 zu groß",Firewalls:"Firewalls","Often silent instead":"Oft stattdessen still","to port 9999":"an Port 9999","nothing listening there":"dort lauscht nichts","type 3 · code 3":"Typ 3 · Code 3","port unreachable":"Port unerreichbar","ICMP · Echo request":"ICMP · Echo-Anfrage",Code:"Code","Covers the whole ICMP message.":"Deckt die ganze ICMP-Nachricht ab.",Identifier:"Kennung","Matches replies to this ping program.":"Ordnet Antworten diesem Ping-Programm zu.","Windows counts up across every ping it sends.":"Windows zählt über alle gesendeten Pings hinweg hoch.","Windows ping’s filler: the alphabet, a to w, then again.":"Die Füllung von Windows-ping: das Alphabet von a bis w, dann wieder von vorn.","ICMP · Echo reply":"ICMP · Echo-Antwort","Sent back exactly as it came.":"Genau so zurückgeschickt, wie es kam.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Zeit überschritten (TTL hat 0 erreicht)","Time exceeded (TTL reached 0)":"Zeit überschritten (TTL hat 0 erreicht)",Unused:"Ungenutzt","Original packet":"Ursprüngliches Paket","Its source, destination":"Seine Quelle, sein Ziel","its IP header and first 8 bytes (28 bytes)":"sein IP-Header und die ersten 8 Byte (28 Byte)","App data":"App-Daten","What the app sent; nothing on the server is listening for it.":"Was die App gesendet hat; auf dem Server wartet nichts darauf.","ICMP · Destination unreachable (port unreachable)":"ICMP · Ziel unerreichbar (Port unerreichbar)","Destination unreachable (port unreachable)":"Ziel unerreichbar (Port unerreichbar)","Sending Email":"E-Mail senden","SMTP command":"SMTP-Befehl","SMTP reply":"SMTP-Antwort","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP befördert E-Mails: von deiner Mail-App zum Server deines Anbieters und von diesem Server zu dem des Empfängers. Es ist ein Gespräch aus kurzen Textbefehlen, die jeweils mit einem dreistelligen Antwortcode beantwortet werden. Mails lesen ist eine andere Aufgabe, erledigt mit IMAP oder POP3.","465/587 submit, 25 relay":"465/587 Einlieferung, 25 Weiterleitung","TCP, usually with TLS":"TCP, meist mit TLS",Commands:"Befehle",Replies:"Antworten","2xx ok, 3xx go on, 4/5xx error":"2xx ok, 3xx weiter, 4/5xx Fehler","Mail delivered":"Mail zugestellt","Two hops, one message":"Zwei Etappen, eine Nachricht","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Alices App hat die Nachricht über eine verschlüsselte, angemeldete Verbindung an ihren Anbieter übergeben. Der Anbieter fand Bobs Mailserver im DNS und leitete sie dorthin weiter, wobei er diese Verbindung auf TLS umstellte. Jetzt wartet sie in Bobs Postfach, bis er sie mit IMAP oder POP3 liest.","Laptop → provider → Bob’s":"Laptop → Anbieter → Bob",Submission:"Einlieferung","Port 465, TLS, login":"Port 465, TLS, Anmeldung",Relay:"Weiterleitung","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Prüfungen bei Bob","Connect Securely":"Sicher verbinden","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice klickt auf Senden. Ihre Mail-App verbindet sich mit dem Einlieferungsserver ihres Anbieters, smtp.example.com, auf Port 465. Auf diesem Port startet TLS sofort, also ist das ganze SMTP-Gespräch verschlüsselt, auch ihr Passwort.","TLS from the start":"TLS von Anfang an","SMTP inside TLS":"SMTP in TLS","Greeting & Login":"Begrüßung und Anmeldung","EHLO, then AUTH":"EHLO, dann AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Der Server grüßt mit Code 220. Die App sagt EHLO, und der Server listet auf, was er unterstützt, darunter AUTH. Die App meldet sich mit AUTH PLAIN an (Benutzername und Passwort, base64-codiert) und bekommt 235: angemeldet.",Greeting:"Begrüßung",Capabilities:"Fähigkeiten","Login result":"Anmeldeergebnis","user and password, base64":"Benutzer und Passwort, base64","Send the Message":"Die Nachricht senden","Envelope, then content":"Erst der Umschlag, dann der Inhalt","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM und RCPT TO sind der Umschlag: Absender und Empfänger. Mit PIPELINING teilen sich alle drei Befehle ein Paket. Nach 354 kommt die Nachricht, beendet durch eine Zeile, die nur einen Punkt enthält.",Envelope:"Umschlag","Content ends":"Inhalt endet","A line with only “.”":"Eine Zeile nur mit „.“",Result:"Ergebnis","… message …":"… Nachricht …","Find Bob’s Server":"Bobs Server finden","An MX lookup in DNS":"Eine MX-Abfrage im DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Alices Anbieter muss jetzt an example.org zustellen. Er fragt das DNS nach dem MX-Eintrag dieser Domain, der den Server nennt, der ihre Mails annimmt, und schlägt dann die Adresse dieses Servers nach.","MX record":"MX-Eintrag","Asked by":"Gefragt von","Alice’s provider":"Alices Anbieter","Server to Server":"Von Server zu Server","Port 25, upgraded with STARTTLS":"Port 25, mit STARTTLS abgesichert","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Der Anbieter verbindet sich mit mx.example.org auf Port 25. Dieses Gespräch beginnt im Klartext: Die Begrüßung und die EHLO-Antwort bieten STARTTLS an, der Anbieter fordert es an, bekommt 220, und beide Seiten wechseln zu TLS.","Starts as":"Beginnt als","Plain text":"Klartext",Upgrade:"Umstellung",Deliver:"Zustellen","The same transaction again":"Dieselbe Transaktion noch einmal","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Mit TLS wiederholt der Anbieter EHLO, dann den Umschlag und die Nachricht, jetzt mit einer DKIM-Signatur und einem zusätzlichen Received-Header. Bobs Server prüft SPF, DKIM und DMARC und nimmt sie an.","Login needed":"Anmeldung nötig","No (server to server)":"Nein (Server zu Server)","1,316 bytes (signed)":"1,316 Byte (signiert)","Server Hello + encrypted handshake, 2 segments":"Server Hello + verschlüsselter Handshake, 2 Segmente","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 Fähigkeiten (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (Zugangsdaten)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (per Pipelining)","Message (316 bytes), then “.”":"Nachricht (316 Byte), dann „.“","250 capabilities (PIPELINING, STARTTLS …)":"250 Fähigkeiten (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 Fähigkeiten (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Nachricht (1,316 Byte), dann „.“","What this client supports. Its exact contents vary from client to client; this is an example.":"Was dieser Client unterstützt. Der genaue Inhalt unterscheidet sich von Client zu Client; dies ist ein Beispiel.","up to 512 bytes":"bis zu 512 Byte","The server’s choices and its key share.":"Die Auswahl des Servers und sein Schlüsselanteil.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (die Kette), Certificate Verify (die Signatur), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Alices Nachricht (316 Byte), dann eine Zeile, die nur „.“ enthält","example.org, type MX, class IN":"example.org, Typ MX, Klasse IN","mx.example.org, type A, class IN":"mx.example.org, Typ A, Klasse IN",Timestamps:"Zeitstempel","Used to measure round trips; both sides offered them.":"Dienen zum Messen der Umlaufzeiten; beide Seiten haben sie angeboten.","The signed message (1,316 bytes), then a line holding only “.”":"Die signierte Nachricht (1,316 Byte), dann eine Zeile, die nur „.“ enthält","Downloading Email":"E-Mails abholen","POP3 command":"POP3-Befehl","POP3 reply":"POP3-Antwort","Post Office Protocol, version 3":"Post Office Protocol, Version 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"Mit POP3 lädt eine Mail-App Nachrichten aus einem Postfach auf einem Server herunter. Es wurde für ein einzelnes Gerät entworfen, das Mails abholt und sie dann vom Server löscht. Befehle sind kurze Wörter, und jede Antwort beginnt mit +OK oder -ERR.",Model:"Modell","Download, then delete":"Herunterladen, dann löschen","Mail downloaded":"Mail heruntergeladen","And gone from the server":"Und vom Server verschwunden","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Bobs App meldete sich an, sah zwei Nachrichten, lud die erste herunter und löschte sie, was der Server bei QUIT ausführte. Diese Nachricht gibt es jetzt nur noch auf diesem Laptop, deshalb passt POP3 zu einem Gerät und IMAP zu mehreren.","2 waiting, 1 downloaded":"2 wartend, 1 heruntergeladen",Deleted:"Gelöscht","At QUIT (UPDATE state)":"Bei QUIT (Zustand UPDATE)","Best for":"Am besten für","A single device":"Ein einzelnes Gerät","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Bobs Mail-App verbindet sich mit pop.example.org auf Port 995, wo TLS sofort startet. Darin grüßt der Server mit +OK. (Auf Port 110 beginnt die Sitzung im Klartext und wird mit dem Befehl STLS umgestellt.)","USER, then PASS":"USER, dann PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Die App sendet den Benutzernamen mit USER und das Passwort mit PASS. Jeder Befehl bekommt sein eigenes +OK. Weil die Sitzung in TLS läuft, ist das Passwort unterwegs nicht lesbar.","Protected by":"Geschützt durch","Check the Mailbox":"Das Postfach prüfen","STAT and LIST":"STAT und LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT liefert die Anzahl der Nachrichten und ihre Gesamtgröße: 2 Nachrichten, 5120 Byte. LIST nennt Nummer und Größe jeder Nachricht und endet mit einer Zeile, die nur einen Punkt enthält.","Message 1":"Nachricht 1","Message 2":"Nachricht 2",Download:"Herunterladen","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 fordert die erste Nachricht an. Der Server antwortet mit +OK und ihrer Größe, dann folgen die Nachricht und ein abschließender Punkt: 1904 Byte plus die Antwortzeile, zwei TCP-Segmente.",Command:"Befehl","Delete & Quit":"Löschen und beenden","Deleted only at QUIT":"Erst bei QUIT gelöscht","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 markiert die Nachricht nur. Der Server entfernt sie, wenn die App QUIT sagt: Bräche die Verbindung vorher ab, würde nichts gelöscht. Viele Apps bieten „Kopie auf dem Server lassen“ an, das überspringt DELE.","Marks message 1":"Markiert Nachricht 1",Removed:"Entfernt",Option:"Option","Leave a copy on server":"Kopie auf dem Server lassen","PASS (password)":"PASS (Passwort)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, Nachricht, „.“ (2 Segmente)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, die 1,904 Byte lange Nachricht, dann eine Zeile, die nur „.“ enthält","IMAP command":"IMAP-Befehl","IMAP response":"IMAP-Antwort","Internet Message Access Protocol":"Protokoll für den Internet-Nachrichtenzugriff","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"Mit IMAP arbeiten Mail-Apps mit einem Postfach, das auf dem Server bleibt. Ordner, Gelesen- und Markiert-Kennzeichen und Löschungen werden dort gespeichert, sodass Handy, Laptop und Webmail dasselbe Postfach sehen. Der Server kann eine App außerdem über neue Mails informieren, sobald sie eintreffen.","Mail stays on the server":"Mails bleiben auf dem Server",Syncs:"Synchronisiert","Folders and flags":"Ordner und Flags","Mailbox in sync":"Postfach synchron","Read once, read everywhere":"Einmal gelesen, überall gelesen","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Bobs App öffnete seinen Posteingang und las eine Nachricht, was sie auf dem Server für alle seine Geräte als \\Seen markierte, und wartete dann mit IDLE, bis der Server neue Mail meldete. Nichts wurde gelöscht: Der Server hat noch alles.","2, then 3 (new mail)":"2, dann 3 (neue Mail)","Read mark":"Gelesen-Markierung","\\Seen, stored on server":"\\Seen, auf dem Server gespeichert","New mail":"Neue Mail","Pushed during IDLE":"Während IDLE zugestellt","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Bobs App verbindet sich mit imap.example.org auf Port 993, wo TLS sofort startet. Der Server grüßt mit einer ungetaggten „* OK“-Zeile, die auch seine Fähigkeiten auflistet, etwa IDLE.","Commands carry tags":"Befehle tragen Tags","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Jeder Befehl beginnt mit einem Tag, den die App wählt, etwa a1, und der Server beendet seine Antwort mit demselben Tag. So können mehrere Befehle gleichzeitig unterwegs sein, und jede Antwort wird richtig zugeordnet. Zeilen, die mit * beginnen, sind ungetaggte Daten.",Tags:"Tags","Match replies to commands":"Ordnen Antworten Befehlen zu","Open the Inbox":"Den Posteingang öffnen","SELECT a folder":"Einen Ordner mit SELECT öffnen","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX öffnet den Ordner. Der Server meldet die Anzahl der Nachrichten, die unterstützten Flags und die erste ungelesene Nachricht und bestätigt dann, dass der Ordner mit Lese- und Schreibzugriff geöffnet ist.","First unread":"Erste ungelesene",Access:"Zugriff","Read a Message":"Eine Nachricht lesen","FETCH, and the \\Seen flag":"FETCH und das \\Seen-Flag","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] lädt Nachricht 2 herunter (drei TCP-Segmente). Das setzt ihr \\Seen-Flag auf dem Server, sodass sie auch auf Bobs Handy als gelesen erscheint, und die Nachricht bleibt dort.","Flag set":"Flag gesetzt","\\Seen (on the server)":"\\Seen (auf dem Server)","Wait for New Mail":"Auf neue Mail warten","IDLE: the server pushes":"IDLE: Der Server meldet sich","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE sagt dem Server: „Sag Bescheid, wenn sich etwas ändert.“ Etwa 42 Sekunden später trifft Alices Nachricht ein, und der Server schickt sofort „* 3 EXISTS“. Die App beendet IDLE mit DONE und kann die neue Mail abrufen.","Server says":"Server meldet","* 3 EXISTS (new mail)":"* 3 EXISTS (neue Mail)","Ended by":"Beendet durch","a1 LOGIN (user and password)":"a1 LOGIN (Benutzer und Passwort)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, die 3,216 Byte lange Nachricht, dann a3 OK FETCH completed","Transferring Files":"Dateien übertragen","FTP command":"FTP-Befehl","FTP reply":"FTP-Antwort","File data":"Dateidaten","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP überträgt Dateien zwischen einem Client und einem Server. Ungewöhnlich ist, dass es zwei TCP-Verbindungen nutzt: eine für Befehle und Antworten und für jede Datei oder Auflistung eine neue. Es stammt aus den frühen 1970ern und sendet alles im Klartext, auch Passwörter.","21 control, data varies":"21 Steuerung, Daten variabel",Connections:"Verbindungen","Control + one per transfer":"Steuerung + eine pro Übertragung",Encryption:"Verschlüsselung","None (plain text)":"Keine (Klartext)","Safer options":"Sicherere Alternativen","File downloaded":"Datei heruntergeladen","Two connections, no encryption":"Zwei Verbindungen, keine Verschlüsselung","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Die Befehle liefen über die Steuerverbindung, die Datei über ihre eigene Datenverbindung, und das Schließen dieser Verbindung markierte das Dateiende. Jeder auf dem Weg hätte Passwort und Datei lesen können, deshalb nutzt man heute SFTP oder FTPS.","2 (control + data)":"2 (Steuerung + Daten)",File:"Datei","4,000 bytes, 3 segments":"4,000 Byte, 3 Segmente",Password:"Passwort","Sent in plain text":"Im Klartext gesendet","Use instead":"Stattdessen nutzen","Control Connection":"Steuerverbindung","Port 21, plain text":"Port 21, Klartext","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"Die FTP-App öffnet eine TCP-Verbindung zu ftp.example.com auf Port 21. Diese Steuerverbindung trägt Befehle und Antworten der ganzen Sitzung. Der Server grüßt mit 220. Wie bei SMTP beginnt jede Antwort mit einem dreistelligen Code.","USER and PASS, readable by anyone":"USER und PASS, für jeden lesbar","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Die App sendet USER, der Server fragt mit 331 nach dem Passwort, und PASS sendet es. Nichts ist verschlüsselt, also überqueren Benutzername und Passwort jedes Netz auf dem Weg als lesbarer Text.","Visible to":"Sichtbar für","Anyone on the path":"Jeden auf dem Weg","Passive Mode":"Passiver Modus","The server names a data port":"Der Server nennt einen Datenport","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I fordert eine bytegenaue Binärkopie an. PASV bittet den Server, einen Port für die Datenverbindung zu öffnen. Die Antwort codiert Adresse und Port als sechs Zahlen: 195 × 256 + 149 = Port 50069. Der Laptop verbindet sich nach außen, was durch NAT hindurch funktioniert.","Data port":"Datenport","Active mode":"Aktiver Modus","Server dials in: NAT blocks":"Server wählt sich ein: NAT blockiert","Data Connection":"Datenverbindung","A second TCP connection":"Eine zweite TCP-Verbindung","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Die App öffnet eine zweite TCP-Verbindung, zu Port 50069, und fordert die Datei auf der Steuerverbindung mit RETR an. Der Server antwortet dort mit 150 und beginnt, die Datei über die neue Verbindung zu senden.","Data to":"Daten an","The File Arrives":"Die Datei kommt an","Closing the connection ends it":"Das Schließen der Verbindung beendet sie","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Die 4,000 Byte kommen in 3 TCP-Segmenten an. FTP sendet in den Daten selbst keine Längenangabe: Der Server schließt die Datenverbindung, um das Dateiende zu markieren. Sobald der Laptop alles bestätigt hat, bestätigt der Server mit 226 auf der Steuerverbindung.","End of file":"Dateiende","Data connection closed":"Datenverbindung geschlossen","4,000 bytes, readable by anyone":"4,000 Byte, für jeden lesbar","end of file:":"Dateiende:","data connection closed":"Datenverbindung geschlossen",Quit:"Beenden","Close the control connection":"Die Steuerverbindung schließen","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT beendet die Sitzung, und der Server verabschiedet sich mit 221. Für alles Vertrauliche erledigen SFTP (ein anderes Protokoll, das über SSH läuft) oder FTPS (FTP in TLS) dieselbe Aufgabe mit Verschlüsselung.","Encrypted cousins":"Verschlüsselte Verwandte","FTP data":"FTP-Daten","The file itself, unencrypted: anyone on the path could read it.":"Die Datei selbst, unverschlüsselt: Jeder auf dem Weg könnte sie lesen.","Secure Remote Login":"Sichere Fernanmeldung","Plain setup":"Aufbau im Klartext","From laptop":"Vom Laptop","From server":"Vom Server","Some packets not shown":"Einige Pakete nicht gezeigt","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH gibt dir eine verschlüsselte, authentifizierte Verbindung zu einem anderen Computer, um dort Befehle auszuführen, Dateien zu kopieren (SFTP, scp) oder andere Verbindungen zu tragen. Der Server beweist mit einem Host-Schlüssel, wer er ist; du beweist es mit einem Schlüsselpaar oder einem Passwort.","Server proves":"Server beweist","Host key (known_hosts)":"Host-Schlüssel (known_hosts)","You prove":"Du beweist","Key pair or password":"Schlüsselpaar oder Passwort","Logged in securely":"Sicher angemeldet","Encrypted from the key exchange on":"Verschlüsselt ab dem Schlüsselaustausch","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Beide Seiten einigten sich auf Algorithmen, erzeugten gemeinsame Schlüssel mit einem hybriden Post-Quanten-Austausch, und der Server bewies seine Identität mit seinem Host-Schlüssel. Alice bewies ihre, indem sie mit einem privaten Schlüssel signierte, der den Laptop nie verließ, und tippte dann einen Befehl, ein Paket pro Taste.",Login:"Anmeldung","Ed25519 key, no password":"Ed25519-Schlüssel, kein Passwort","Say Hello":"Hallo sagen","Versions, in plain text":"Versionen, im Klartext","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice führt „ssh alice@server.example.com“ aus. Nach dem TCP-Handshake auf Port 22 schickt jede Seite eine Zeile Klartext mit der Version des SSH-Protokolls (2.0) und ihrer Software. Alles andere in SSH ist binär.","Agree on Algorithms":"Algorithmen vereinbaren","KEXINIT lists, first match wins":"KEXINIT-Listen, der erste Treffer gewinnt","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Jede Seite schickt ein KEXINIT mit allen Algorithmen, die sie unterstützt, nach Vorliebe geordnet: für Schlüsselaustausch, Host-Schlüssel, Verschlüsselung, Integrität und Kompression. In jeder Kategorie wird der erste Algorithmus auf der Liste des Laptops gewählt, den auch der Server unterstützt.","Host key":"Host-Schlüssel","server’s algorithm lists":"Algorithmuslisten des Servers","in order of preference":"nach Vorliebe geordnet","laptop’s algorithm lists":"Algorithmuslisten des Laptops","Key Exchange":"Schlüsselaustausch","Shared keys, and a host key check":"Gemeinsame Schlüssel und eine Prüfung des Host-Schlüssels","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Der Laptop schickt seine Hälfte eines hybriden Austauschs: einen Streamlined-NTRU-Prime-Schlüssel, gewählt, um künftigen Quantencomputern standzuhalten, dazu einen X25519-Schlüssel. Der Server antwortet mit seiner Hälfte, seinem Host-Schlüssel und einer Signatur über den Austausch. NEWKEYS schaltet die Verschlüsselung ein.",Hybrid:"Hybrid","Matches known_hosts":"Stimmt mit known_hosts überein","First visit":"Erster Besuch","ssh asks you to confirm":"ssh bittet dich um Bestätigung","public keys":"öffentliche Schlüssel","its half, its host key":"seine Hälfte, sein Host-Schlüssel","and a signature":"und eine Signatur","Log In with a Key":"Per Schlüssel anmelden","Sign, don’t send a secret":"Signieren statt ein Geheimnis senden","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Der Server listet die Anmeldemethoden auf, die er akzeptiert. Der Laptop bietet Alices öffentlichen Schlüssel an, und der Server sagt, dass er ihn akzeptieren würde. Dann signiert der Laptop diese Sitzung mit dem privaten Schlüssel, der den Laptop nie verlässt. Der Server prüft die Signatur anhand von authorized_keys.",Methods:"Methoden","Ed25519, private stays here":"Ed25519, der private bleibt hier","Checked with":"Geprüft mit","alice’s public key":"Alices öffentlicher Schlüssel","would you accept it?":"würdest du ihn akzeptieren?","yes, that key":"ja, dieser Schlüssel","is in authorized_keys":"steht in authorized_keys","same key, plus a signature":"derselbe Schlüssel, plus Signatur","made with the private key":"mit dem privaten Schlüssel erstellt","logged in":"angemeldet","Open a Session":"Eine Sitzung öffnen","Channels inside one connection":"Kanäle in einer Verbindung","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Eine SSH-Verbindung kann viele Kanäle tragen: eine Shell, Dateiübertragungen, weitergeleitete Ports. Der Laptop öffnet einen Sitzungskanal, bittet dann um ein Terminal und eine Shell (nicht gezeigt), und der Server schickt seinen Begrüßungstext und einen Prompt.",Channel:"Kanal",session:"Sitzung","Then asks for":"Fordert dann an","A terminal and a shell":"Ein Terminal und eine Shell","Also possible":"Ebenfalls möglich","SFTP, port forwarding":"SFTP, Portweiterleitung","open a channel:":"Kanal öffnen:","channel open":"Kanal offen","Type a Command":"Einen Befehl tippen","Every key is a packet":"Jede Taste ist ein Paket","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice tippt pwd. Jede Taste geht sofort in einem eigenen verschlüsselten Paket hinaus, und der Server schickt das Zeichen zur Anzeige zurück (das Echo). Seit Version 9.5 sendet OpenSSH Tasten in einem 20-ms-Takt und fügt Täuschpakete hinzu, damit sich der Tipprhythmus schwerer aus dem Timing ablesen lässt.","Per key":"Pro Taste","1 packet, 90 bytes":"1 Paket, 90 Byte",Echo:"Echo","Sent back by the server":"Vom Server zurückgeschickt",Timing:"Timing","20 ms beat plus decoys":"20-ms-Takt plus Täuschpakete","Enter key":"Eingabetaste","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (öffentliche Schlüssel sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (Host-Schlüssel, seine Hälfte, Signatur)","Encrypted (len=44): service request, ssh-userauth":"Verschlüsselt (len=44): Dienstanfrage, ssh-userauth","Encrypted (len=44): service accept":"Verschlüsselt (len=44): Dienst angenommen","Encrypted (len=68): login with method none":"Verschlüsselt (len=68): Anmeldung mit Methode none","Encrypted (len=52): try publickey,password":"Verschlüsselt (len=52): versuche publickey,password","Encrypted (len=140): offer public key":"Verschlüsselt (len=140): bietet öffentlichen Schlüssel an","Encrypted (len=100): public key OK":"Verschlüsselt (len=100): öffentlicher Schlüssel OK","Encrypted (len=308): public key + signature":"Verschlüsselt (len=308): öffentlicher Schlüssel + Signatur","Encrypted (len=28): login success":"Verschlüsselt (len=28): Anmeldung erfolgreich","Encrypted (len=52): channel open: session":"Verschlüsselt (len=52): Kanal öffnen: session","Encrypted (len=44): channel open confirmed":"Verschlüsselt (len=44): Kanalöffnung bestätigt","Encrypted (len=36): keystroke":"Verschlüsselt (len=36): Tastendruck","Encrypted (len=36): echo":"Verschlüsselt (len=36): Echo","Encrypted (len=36): keystroke (Enter)":"Verschlüsselt (len=36): Tastendruck (Enter)","Encrypted (len=132): output and a new prompt":"Verschlüsselt (len=132): Ausgabe und ein neuer Prompt","Packet length":"Paketlänge","Bytes after this field.":"Bytes nach diesem Feld.","Padding length":"Padding-Länge","Random padding brings the packet to a multiple of 8 bytes.":"Zufälliges Padding bringt das Paket auf ein Vielfaches von 8 Byte.",Cookie:"Cookie","Host keys":"Host-Schlüssel","Ciphers, out":"Chiffren, ausgehend","Ciphers, in":"Chiffren, eingehend","MACs, out":"MACs, ausgehend","Compression, out":"Kompression, ausgehend","Compression, in":"Kompression, eingehend","Languages, out":"Sprachen, ausgehend","Languages, in":"Sprachen, eingehend","First packet follows":"Erstes Paket folgt",Reserved:"Reserviert","Public keys":"Öffentliche Schlüssel","51 bytes: ssh-ed25519 public key":"51 Byte: öffentlicher ssh-ed25519-Schlüssel","Server’s half":"Hälfte des Servers","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 Byte (sntrup761-Chiffretext 1,039 + X25519 32)",Signature:"Signatur","83 bytes: ssh-ed25519 signature over the exchange":"83 Byte: ssh-ed25519-Signatur über den Austausch","From the next packet on, this side encrypts.":"Ab dem nächsten Paket verschlüsselt diese Seite.","SSH · encrypted packet":"SSH · verschlüsseltes Paket","Encrypted packet":"Verschlüsseltes Paket","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Mit chacha20-poly1305 ist sogar die Länge verschlüsselt; ein 16 Byte langes Tag am Ende zeigt jede Änderung.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): Benutzer „alice“, Dienst „ssh-connection“, Methode „none“","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): Methoden, mit denen es weitergeht: „publickey,password“","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): Methode „publickey“, ohne Signatur, der öffentliche ssh-ed25519-Schlüssel","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): derselbe ssh-ed25519-Schlüssel","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): Methode „publickey-hostbound-v00@openssh.com“, der Schlüssel, der Host-Schlüssel des Servers und eine Signatur","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): „session“, Kanal 0, Fenster 2 MB, Pakete bis 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): Kanal 0 ist offen","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „p“","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „p“, zur Anzeige zurückgeschickt","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „w“","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „w“, zur Anzeige zurückgeschickt","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „d“","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, „d“, zur Anzeige zurückgeschickt","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 1 Byte, ein Wagenrücklauf (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), Kanal 0: 94 Byte: ein Zeilenumbruch, die Terminalcodes der Shell, „/home/alice“ und der farbige Prompt","From browser":"Vom Browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS legt einen sicheren Kanal über TCP. Es beweist die Identität des Servers mit einem Zertifikat, vereinbart frische Schlüssel und verschlüsselt und authentifiziert dann alles Gesendete. HTTPS, sichere E-Mail und viele andere Protokolle laufen darin. SSL hieß sein Vorgänger.",Sits:"Liegt","Between TCP and the app":"Zwischen TCP und der App","OSI layer":"OSI-Schicht","Often placed at 6":"Oft bei 6 eingeordnet",Current:"Aktuell",Retired:"Ausgemustert","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 und 3, TLS 1.0 und 1.1","The app’s own (443, 993 …)":"Der der App (443, 993 …)","Secure from start to finish":"Von Anfang bis Ende sicher","One round trip to set up":"Ein Umlauf für den Aufbau","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Ein einziger Umlauf genügte, um Version, Chiffre und einen hybriden Post-Quanten-Schlüssel zu vereinbaren. Die Zertifikatskette bewies, wer der Server war, und jedes Byte nach dem Server Hello war verschlüsselt und authentifiziert, bis zum close_notify. Drücke NOCHMAL, um es dir noch einmal anzusehen.","1 round trip":"1 Umlauf","Everything the browser supports":"Alles, was der Browser unterstützt","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Nach dem TCP-Handshake listet der Browser auf, was er kann: TLS-Versionen, Cipher Suites und Schlüsselanteile für die Gruppen, die er erwartet, darunter das hybride Post-Quanten-Verfahren X25519MLKEM768. Außerdem nennt er die Website (SNI) und die Protokolle, die er spricht (ALPN).",Versions:"Versionen","versions, ciphers, key shares":"Versionen, Chiffren, Schlüsselanteile","Choices made, keys computed":"Auswahl getroffen, Schlüssel berechnet","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Der Server wählt TLS 1.3, die Cipher Suite und die hybride Gruppe und schickt seinen eigenen Schlüsselanteil. Aus den beiden Anteilen berechnen beide Seiten dasselbe Geheimnis, ohne dass es je das Netz überquert. Alles nach dieser Nachricht ist verschlüsselt.",Group:"Gruppe","From here on":"Ab hier","its key share":"sein Schlüsselanteil",Certificate:"Zertifikat","Who the server is, proven":"Wer der Server ist, bewiesen","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Jetzt verschlüsselt geht es weiter: das gewählte Protokoll (http/1.1), die Zertifikatskette, eine mit dem privaten Schlüssel des Zertifikats erstellte Signatur und Finished.",Chain:"Kette","Site → intermediate → root":"Website → Zwischenzertifikat → Root","Proves the private key":"Beweist den privaten Schlüssel",Checked:"Geprüft","Name, dates, trusted root":"Name, Daten, vertrauenswürdige Root","encrypted: http/1.1, certificates,":"verschlüsselt: http/1.1, Zertifikate,","signature, Finished":"Signatur, Finished","One round trip, then data":"Ein Umlauf, dann Daten","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Der Browser schickt sein eigenes Finished: einen Prüfwert über alles, was beide Seiten gesagt haben, berechnet mit dem neuen Geheimnis, sodass jede Manipulation an den Hellos auffallen würde. TLS 1.3 braucht einen Umlauf, bevor Daten fließen; TLS 1.2 brauchte zwei.",Covers:"Deckt ab","The whole handshake":"Den ganzen Handshake","For old middleboxes":"Für alte Middleboxes","check value over":"Prüfwert über","the whole handshake":"den ganzen Handshake","Encrypted Data":"Verschlüsselte Daten","Records, tags and tickets":"Records, Tags und Tickets","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP reist jetzt in verschlüsselten Records, jeder mit einem 16 Byte langen Tag, das jede Änderung aufdeckt. Der Server schickt außerdem zwei Sitzungstickets: Beim nächsten Mal kann der Browser mit einem davon fortsetzen und das Zertifikat überspringen.","Per record":"Pro Record","22 bytes of overhead":"22 Byte Overhead","2, for resuming later":"2, zum späteren Fortsetzen",Visible:"Sichtbar","IPs, SNI, sizes, timing":"IPs, SNI, Größen, Timing","2 session tickets":"2 Sitzungstickets","for resuming later":"zum späteren Fortsetzen",Closing:"Schließen","close_notify, then TCP":"close_notify, dann TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Nach 75 Sekunden ohne Aktivität schließt der Server die Verbindung. Zuerst schickt er eine close_notify-Warnung, verschlüsselt wie alles andere, damit der Browser weiß, dass die Daten absichtlich endeten und nicht von einem Angreifer abgeschnitten wurden. Dann schließt TCP wie gewohnt.",Alert:"Warnung","Shows nothing was cut off":"Zeigt, dass nichts abgeschnitten wurde","TCP FIN from both sides":"TCP-FIN von beiden Seiten","alert: close_notify":"Warnung: close_notify",encrypted:"verschlüsselt","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ verschlüsselt)","Encrypted handshake (continued)":"Verschlüsselter Handshake (Fortsetzung)","Encrypted handshake (certificate, verify, Finished)":"Verschlüsselter Handshake (Zertifikat, Verify, Finished)","Application Data (inside: close_notify alert)":"Application Data (darin: close_notify-Warnung)","Alert: close_notify (the data ends here, on purpose)":"Warnung: close_notify (die Daten enden hier, absichtlich)","No IP address":"Keine IP-Adresse","192.168.1.1 · DHCP server":"192.168.1.1 · DHCP-Server"},d={"Two-way web messaging":"Webnachrichten in beide Richtungen","Browser video calls":"Videoanrufe im Browser","HTTP/3 over UDP":"HTTP/3 über UDP","Routing between networks":"Routing zwischen Netzen","Address setup, neighbour discovery":"Adresseinrichtung, Nachbarerkennung","Private DNS lookups":"Private DNS-Abfragen","Signed DNS answers":"Signierte DNS-Antworten","Network Time Protocol":"Netzwerk-Zeitprotokoll","Joining a network (WPA2)":"Einem Netz beitreten (WPA2)","Wi-Fi Protected Access 3":"Wi-Fi Protected Access 3","802.1X Enterprise Wi-Fi":"802.1X-Firmen-WLAN","Hotel and café Wi-Fi logins":"WLAN-Anmeldung in Hotels und Cafés","Windows file sharing":"Windows-Dateifreigabe","Forward proxy and CONNECT":"Forward-Proxy und CONNECT","Socket Secure proxy":"Socket-Secure-Proxy","TLS offloading":"TLS-Offloading","A modern VPN":"Ein modernes VPN","IKEv2 and ESP":"IKEv2 und ESP","Industrial control (OT)":"Industriesteuerung (OT)",Proxy:"Proxy","App Server":"App-Server","File Server":"Dateiserver","ISP Router":"ISP-Router","Transit Router":"Transit-Router","Hosting Router":"Hosting-Router","Their Router":"Router der Gegenseite","Their Laptop":"Laptop der Gegenseite",Transit:"Transit",Hosting:"Hosting","The router itself.":"Der Router selbst.","Mail in Sync":"Mail im Abgleich","Live Updates":"Live-Updates","From the browser":"Vom Browser","From the server":"Vom Server","The WebSocket Protocol":"Das WebSocket-Protokoll","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"Ein WebSocket hält eine Verbindung zwischen einer Webseite und einem Server offen, sodass jede Seite jederzeit eine Nachricht schicken kann: Chat, Live-Ergebnisse, Spiele, gemeinsame Dokumente. Er beginnt als gewöhnliche HTTP-Anfrage, die um ein Upgrade bittet; danach reisen Nachrichten in kleinen Frames mit einem Header von nur wenigen Bytes.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Eine HTTP-Anfrage (Upgrade)","Frames both ways, any time":"Frames in beide Richtungen, jederzeit","Frame header":"Frame-Header","2–14 bytes":"2–14 Bytes","One request, then messages":"Eine Anfrage, dann Nachrichten","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Eine HTTP-Anfrage hat eine gewöhnliche TCP-Verbindung in einen Kanal für beide Richtungen verwandelt. Danach kostete jede Nachricht ein paar Bytes Header, und der Server konnte senden, wann immer er etwas zu sagen hatte. Drücke NOCHMAL, um es dir noch einmal anzusehen.","GET with Upgrade, then 101":"GET mit Upgrade, dann 101","Smallest frame":"Kleinster Frame","2 bytes (a ping)":"2 Bytes (ein Ping)","Server push":"Server-Push","Any time, unasked":"Jederzeit, ungefragt","Real sites":"Echte Websites","wss:// (inside TLS)":"wss:// (in TLS)","TCP to the server, as for HTTP":"TCP zum Server, wie bei HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'Die Chatseite ist schon offen, geladen von www.example.com. Ihr Skript ruft new WebSocket("ws://www.example.com/chat") auf, und der Browser beginnt mit einer gewöhnlichen TCP-Verbindung zu Port 80. (Echte Websites nutzen wss://, dasselbe in TLS; einfaches ws:// lässt dich jedes Byte lesen.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Um Upgrade bitten","An HTTP request with Upgrade: websocket":"Eine HTTP-Anfrage mit Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"Der Browser schickt ein HTTP-GET mit Upgrade: websocket und Connection: Upgrade. Sec-WebSocket-Key sind 16 zufällige Bytes in Base64, auf die der Server richtig antworten muss. Der Browser bietet außerdem an, Nachrichten zu komprimieren (permessage-deflate).","Asks for":"Bittet um","16 random bytes, base64":"16 zufällige Bytes, Base64",UPGRADE:"UPGRADE","Switch Protocols":"Protokollwechsel","101: from now on, WebSocket":"101: ab jetzt WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"Der Server antwortet 101 Switching Protocols. Sein Sec-WebSocket-Accept ist der Schlüssel mit einer festen Zeichenfolge dahinter, mit SHA-1 gehasht und in Base64 geschrieben: der Beweis, dass er die Anfrage verstanden hat. Die Kompression hat er nicht angenommen, also gehen Nachrichten als Klartext. HTTP ist auf dieser Verbindung vorbei; ab jetzt schicken beide Seiten WebSocket-Frames.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 des Schlüssels + feste Zeichenfolge",Compression:"Kompression","Offered, not taken":"Angeboten, nicht angenommen","NOW A WEBSOCKET":"JETZT EIN WEBSOCKET","Small frames, from either side":"Kleine Frames, von jeder Seite",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Du schickst "Hello": einen 2-Byte-Header, einen 4-Byte-Maskierungsschlüssel und die 5 maskierten Bytes, 11 Bytes insgesamt statt einer ganzen HTTP-Anfrage. Sekunden später schiebt der Server Bobs Nachricht ungefragt nach: Die Verbindung ist noch offen, also kann er das. Frames vom Browser sind immer maskiert, Frames vom Server nie.',"You send":"Du schickst","Server pushes":"Server schiebt",'"bob: hi there"':'"bob: hi there"',Masked:"Maskiert","From the browser only":"Nur vom Browser",TEXT:"TEXT",masked:"maskiert",unasked:"ungefragt","Keeping It Alive":"Am Leben halten","Ping and pong":"Ping und Pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Nach einer halben Minute ohne Nachricht schickt der Server einen Ping, damit Router und Firewalls unterwegs die stille Verbindung nicht vergessen. Der Browser antwortet von selbst mit einem Pong; das Skript der Seite sieht keins von beiden.","Opcode 9, from either side":"Opcode 9, von jeder Seite",Pong:"Pong","Opcode 10, by itself":"Opcode 10, von selbst","How often":"Wie oft","Up to the server (30 s)":"Entscheidet der Server (30 s)","A close frame each way":"Ein Close-Frame in jede Richtung","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Wenn du den Chat verlässt, schließt das Skript der Seite den WebSocket mit Status 1000 (normales Schließen): Der Browser schickt einen Close-Frame, und der Server antwortet mit seinem eigenen. Dann schließt der Server die TCP-Verbindung. (Einfach den Tab zu schließen würde 1001 senden, going away.)",Opcode:"Opcode","8 (close)":"8 (Close)","1000 (normal closure)":"1000 (normales Schließen)","TCP closes":"TCP schließt",CLOSE:"CLOSE","1000 normal closure":"1000 normales Schließen","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: Dieser Frame ist eine ganze Nachricht. Der Opcode sagt, was er trägt.","Mask, length":"Maske, Länge","Everything a browser sends is masked.":"Alles, was ein Browser schickt, ist maskiert.","Masking key":"Maskierungsschlüssel","Chosen at random for every frame.":"Für jeden Frame zufällig gewählt.",Payload:"Nutzdaten","Each byte XORed with the masking key in turn; the server XORs it back.":"Jedes Byte der Reihe nach mit dem Maskierungsschlüssel XOR-verknüpft; der Server macht das XOR rückgängig.","A server never masks what it sends.":"Ein Server maskiert nie, was er schickt.","Status code":"Statuscode","Joining a Network":"Einem Netz beitreten","From the access point":"Vom Access Point","4-way handshake":"4-Wege-Handshake","Access Point":"Access Point","Wi-Fi (802.11) with WPA2":"WLAN (802.11) mit WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"WLAN trägt ein Netzwerk über Funk. Bevor ein Gerät irgendetwas senden kann, muss es das Netz finden, ihm beitreten und beweisen, dass es das Passwort kennt. Bei WPA2-Personal ist dieser Beweis der 4-Wege-Handshake: vier kurze Nachrichten, die aus dem Passwort frische Schlüssel machen, ohne dass das Passwort je durch die Luft geht.","Data Link (Layer 2)":"Sicherung (Schicht 2)",Standard:"Standard",Joining:"Beitritt","Probe, authenticate, associate":"Suchen, authentifizieren, assoziieren","Keys from":"Schlüssel aus","The 4-way handshake":"Dem 4-Wege-Handshake",Connected:"Verbunden","Eleven frames to a secure link":"Elf Frames bis zur sicheren Verbindung","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"Der Laptop hat das Netz gefunden, ist ihm mit zwei Formalitäten beigetreten und hat in einem Handshake aus vier Nachrichten bewiesen, dass er das Passwort kennt, ohne es je zu senden. Alles danach war mit Schlüsseln verschlüsselt, die nur für diese Verbindung gemacht wurden. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Frames to join":"Frames zum Beitritt","Password sent":"Passwort gesendet",Never:"Nie","Session keys":"Sitzungsschlüssel","New every time":"Jedes Mal neu",Next:"Als Nächstes","DHCP, for an IP address":"DHCP, für eine IP-Adresse","Find the Network":"Das Netz finden","A beacon, then a probe":"Ein Beacon, dann eine Suche",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Etwa zehnmal pro Sekunde sendet das WLAN des Routers ein Beacon: Hier ist "HomeNet", mit WPA2 geschützt, auf Kanal 36. Der Laptop könnte einfach warten, bis er eins hört; um schneller zu sein, fragt er auch laut mit einem Probe Request, und der Access Point antwortet mit einer Probe Response.',"WPA2-Personal (password)":"WPA2-Personal (Passwort)",BEACON:"BEACON","WPA2 · channel 36":"WPA2 · Kanal 36",PROBE:"SUCHE","any networks here?":"Netze in der Nähe?","PROBE RESPONSE":"SUCHANTWORT","Join the Network":"Dem Netz beitreten","Two formalities: hello, then join":"Zwei Formalitäten: Hallo, dann beitreten","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"Die Open-System-Authentifizierung lässt jeden so weit kommen: noch kein Passwort. Dann bittet der Laptop um Assoziierung, wobei er die gewählte Sicherheit wiederholt (CCMP, mit Passwort), und der Access Point gibt ihm die Assoziierungs-ID 1. Der Laptop ist verbunden, darf aber nur den Handshake senden, der als Nächstes kommt.",Authentication:"Authentifizierung","Open System (no password)":"Open System (kein Passwort)","Association ID":"Assoziierungs-ID","Allowed so far":"Bisher erlaubt",success:"Erfolg",ASSOCIATE:"ASSOZIIEREN",'join "HomeNet"':'"HomeNet" beitreten',"CCMP, password":"CCMP, Passwort",ASSOCIATED:"ASSOZIIERT","association ID 1":"Assoziierungs-ID 1","Messages 1 and 2":"Nachrichten 1 und 2","The 4-way handshake: nonces":"Der 4-Wege-Handshake: Nonces","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Beide Seiten haben schon denselben Schlüssel, berechnet aus dem Passwort und dem Namen des Netzes (der PMK); er geht nie durch die Luft. Der Access Point schickt eine Zufallszahl, die ANonce. Der Laptop schickt seine eigene, die SNonce, mit einem Prüfwert (MIC). Aus der PMK, den beiden Nonces und beiden MAC-Adressen berechnet jede Seite jetzt dieselben Sitzungsschlüssel.","Shared key":"Gemeinsamer Schlüssel","PMK, from the password":"PMK, aus dem Passwort",Exchanged:"Ausgetauscht","Two random nonces":"Zwei zufällige Nonces","Worked out":"Berechnet","Session keys (PTK)":"Sitzungsschlüssel (PTK)","MESSAGE 1":"NACHRICHT 1","MESSAGE 2":"NACHRICHT 2","Messages 3 and 4":"Nachrichten 3 und 4","The 4-way handshake: keys":"Der 4-Wege-Handshake: Schlüssel","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Nachricht 3 zeigt, dass der Access Point dieselben Schlüssel hat (sein MIC stimmt), und bringt den Gruppenschlüssel (GTK) für Broadcasts, verschlüsselt. Nachricht 4 sagt, dass der Laptop bereit ist, und beide Enden beginnen zu verschlüsseln.","Group key":"Gruppenschlüssel","GTK, sent encrypted":"GTK, verschlüsselt gesendet",Install:"Installieren","Both ends at once":"Beide Enden gleichzeitig","MESSAGE 3":"NACHRICHT 3","group key, encrypted":"Gruppenschlüssel, verschlüsselt","MESSAGE 4":"NACHRICHT 4","keys installed":"Schlüssel installiert","Encrypted Now":"Jetzt verschlüsselt","And what a listener could still do":"Und was ein Lauscher noch tun könnte","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Jeder Datenframe ist jetzt verschlüsselt, wie dieser erste mit einem DHCP Discover: Wer in der Nähe ist, sieht nur die MAC-Adressen und die Größe. Wer aber die vier Handshake-Nachrichten aufgezeichnet hat, kann zu Hause Passwörter durchprobieren, so schnell sein Computer es erlaubt: Ein Versuch stimmt, wenn er denselben MIC ergibt. Ein langes, zufälliges Passwort macht das aussichtslos; WPA3 beseitigt die Schwäche.","Others see":"Andere sehen","MAC addresses, sizes, timing":"MAC-Adressen, Größen, Zeiten","Weak point":"Schwachstelle","Offline password guessing":"Passwortraten offline",Defence:"Abwehr","A long password, or WPA3":"Ein langes Passwort oder WPA3","DHCP Discover inside":"darin ein DHCP Discover","ENCRYPTED FROM HERE ON":"AB HIER VERSCHLÜSSELT","QoS Data (encrypted)":"QoS Data (verschlüsselt)","Seen over the air, on Wi-Fi channel 36":"In der Luft gesehen, auf WLAN-Kanal 36","Frame type":"Frame-Typ","Management, Beacon":"Management, Beacon",Duration:"Dauer","Nobody acknowledges a broadcast, so nothing is booked.":"Niemand bestätigt einen Broadcast, also wird nichts reserviert.",Receiver:"Empfänger","Broadcast: every device in range listens.":"Broadcast: Jedes Gerät in Reichweite hört zu.",Transmitter:"Sender","The access point.":"Der Access Point.","The access point’s own address: which network this is about.":"Die eigene Adresse des Access Points: um welches Netz es geht.","Lets the receiver spot a repeat when a frame is sent again.":"Lässt den Empfänger eine Wiederholung erkennen, wenn ein Frame erneut gesendet wird.","The access point’s clock; devices on the network keep theirs in step with it.":"Die Uhr des Access Points; die Geräte im Netz halten ihre damit im Takt.","Beacon interval":"Beacon-Intervall","A beacon goes out about ten times a second.":"Etwa zehnmal pro Sekunde geht ein Beacon hinaus.","0x0011: access point network, encrypted":"0x0011: Netz mit Access Point, verschlüsselt","Privacy bit set: joining takes a key.":"Privacy-Bit gesetzt: Zum Beitritt braucht es einen Schlüssel.","The network’s name.":"Der Name des Netzes.","Supported rates":"Unterstützte Raten","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Nur die ältesten, langsamsten Raten; die schnellen stehen in den folgenden Elementen.","DTIM count 0, period 1":"DTIM-Zähler 0, Periode 1","Tells sleeping devices whether frames are waiting for them.":"Sagt schlafenden Geräten, ob Frames auf sie warten.","Robust Security Network: how this network is protected.":"Robust Security Network: wie dieses Netz geschützt ist.","Element ID, length":"Element-ID, Länge","48, 20 bytes":"48, 20 Bytes","Group cipher":"Gruppenverschlüsselung","Encrypts broadcasts, which every device on the network can read.":"Verschlüsselt Broadcasts, die jedes Gerät im Netz lesen kann.","Pairwise cipher":"Paarweise Verschlüsselung","Encrypts each device’s own traffic, with keys only it and the access point have.":"Verschlüsselt den eigenen Verkehr jedes Geräts, mit Schlüsseln, die nur es und der Access Point haben.","Key management":"Schlüsselverwaltung","1: PSK (a shared password)":"1: PSK (ein gemeinsames Passwort)","More elements":"Weitere Elemente","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Fähigkeiten und Einstellungen für Wi-Fi 4, 5 und 6 (HT, VHT, HE: Kanal 36, 80 MHz breit) und Herstellerextras.","Management, Probe Request":"Management, Probe Request","The laptop’s Wi-Fi card.":"Die WLAN-Karte des Laptops.","empty (any network)":"leer (beliebiges Netz)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"Jeder Access Point darf antworten. (Früher fragten Geräte jedes Netz, dem sie je beigetreten waren, beim Namen ab und verrieten so jedem Lauscher, wo sie gewesen waren.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Was das Funkmodul des Laptops kann: Fähigkeiten für Wi-Fi 4, 5 und 6 und Herstellerextras.","Management, Probe Response":"Management, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Wie lange der Kanal für diesen Austausch reserviert bleibt; andere Geräte warten.","The radio this frame is for.":"Das Funkmodul, für das dieser Frame bestimmt ist.","Authentication · Open System":"Authentifizierung · Open System","Management, Authentication":"Management, Authentication",Algorithm:"Algorithmus","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Offen: Jeder darf so weit kommen. Das Passwort wird später geprüft, im 4-Wege-Handshake.",Transaction:"Transaktion","0 (success)":"0 (Erfolg)","Management, Association Request":"Management, Association Request","Listen interval":"Abhörintervall","10 beacons":"10 Beacons","How often the laptop wakes to check for waiting frames when saving power.":"Wie oft der Laptop im Stromsparmodus aufwacht, um nach wartenden Frames zu sehen.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Was das Funkmodul des Laptops kann (Wi-Fi 4, 5 und 6) und Herstellerextras.","Management, Association Response":"Management, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Die Nummer des Laptops an diesem Access Point (die beiden obersten Bits sind immer gesetzt).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"Die Einstellungen, die der Access Point nutzt (Wi-Fi 4, 5 und 6), und Herstellerextras.","Data, QoS Data":"Daten, QoS Data","0x02 (from the access point)":"0x02 (vom Access Point)","Sent by the access point itself.":"Vom Access Point selbst gesendet.","QoS control":"QoS-Steuerung","Priority 7, the highest: the handshake goes first.":"Priorität 7, die höchste: Der Handshake geht vor.",Organization:"Organisation","0x888e (802.1X authentication)":"0x888e (802.1X-Authentifizierung)","What follows: plays the part an Ethernet type field does on a cable.":"Was folgt: übernimmt die Rolle, die auf einem Kabel das Ethernet-Typfeld spielt.","Descriptor type":"Deskriptortyp","Key information":"Schlüsselinformation","0x008a: pairwise, ACK":"0x008a: paarweise, ACK","ACK: the laptop must answer.":"ACK: Der Laptop muss antworten.","Key length":"Schlüssellänge","The pairwise key is 16 bytes (AES-128).":"Der paarweise Schlüssel ist 16 Bytes lang (AES-128).","Replay counter":"Wiederholungszähler","Counts up with each message from the access point; an old one sent again is ignored.":"Zählt mit jeder Nachricht des Access Points hoch; eine alte, erneut gesendete wird ignoriert.","A random number from the access point.":"Eine Zufallszahl vom Access Point.","Key IV":"Schlüssel-IV",zeros:"Nullen","Key RSC":"Schlüssel-RSC","No keys yet, so nothing to check with.":"Noch keine Schlüssel, also nichts zum Prüfen.","Key data length":"Länge der Schlüsseldaten","0x01 (to the access point)":"0x01 (zum Access Point)","The access point itself.":"Der Access Point selbst.","0x010a: pairwise, MIC":"0x010a: paarweise, MIC","MIC: this message carries a check value.":"MIC: Diese Nachricht trägt einen Prüfwert.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Eine Zufallszahl vom Laptop. Aus beiden Zahlen, beiden MAC-Adressen und dem Schlüssel aus dem Passwort berechnet jede Seite dieselben Sitzungsschlüssel.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Mit den neuen Schlüsseln berechnet: beweist, dass der Absender das Passwort kennt und die Nachricht nicht verändert wurde.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: paarweise, installieren, ACK, MIC, sicher, Schlüsseldaten verschlüsselt","Install: start using the keys. The group key comes encrypted.":"Installieren: die Schlüssel verwenden. Der Gruppenschlüssel kommt verschlüsselt.","Where the group key’s packet numbers start.":"Wo die Paketnummern des Gruppenschlüssels beginnen.","Key data":"Schlüsseldaten","Encrypted with a key from the handshake.":"Mit einem Schlüssel aus dem Handshake verschlüsselt.","The access point’s RSN element":"Das RSN-Element des Access Points","GTK: the group key, for broadcasts":"GTK: der Gruppenschlüssel, für Broadcasts","0x030a: pairwise, MIC, secure":"0x030a: paarweise, MIC, sicher","Secure: the keys are in place.":"Sicher: Die Schlüssel sind eingerichtet.","CCMP · encrypted":"CCMP · verschlüsselt","0x41 (protected, to the access point)":"0x41 (geschützt, zum Access Point)","Protected: what follows the header is encrypted.":"Geschützt: Was auf den Header folgt, ist verschlüsselt.","Where the access point should pass it on to: everyone on the network.":"Wohin der Access Point es weitergeben soll: an alle im Netz.","CCMP header":"CCMP-Header","packet number 1, key 0":"Paketnummer 1, Schlüssel 0","Counts up with every frame; one seen before is thrown away.":"Zählt mit jedem Frame hoch; ein schon gesehener wird verworfen.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: ein IPv4-Paket","Shows any change to the frame.":"Zeigt jede Veränderung am Frame.","Safer Wi-Fi":"Sichereres WLAN","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 ist der aktuelle WLAN-Sicherheitsstandard. Sein Personal-Modus behält das einfache gemeinsame Passwort, ändert aber, wie es geprüft wird: SAE, ein Passwortaustausch, den keine Aufzeichnung offline angreifbar macht, gibt jeder Verbindung einen frischen Schlüssel. Außerdem macht er geschützte Management-Frames zur Pflicht.","Password check":"Passwortprüfung",Required:"Pflicht","Protected management frames":"Geschützte Management-Frames",Since:"Seit","Connected with WPA3":"Mit WPA3 verbunden","Same password, better protocol":"Gleiches Passwort, besseres Protokoll","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"Der Laptop und der Access Point haben einander bewiesen, dass sie das Passwort kennen, ohne irgendwem eine Möglichkeit zu geben, offline zu raten, und dann frische Schlüssel gemacht, genau wie bei WPA2. Drücke NOCHMAL, um es dir noch einmal anzusehen.","SAE frames":"SAE-Frames","4 (commit, confirm)":"4 (Commit, Confirm)","4 EAPOL-Key frames":"4 EAPOL-Key-Frames","Offline guessing":"Offline-Raten","Not possible":"Unmöglich","Forged disconnects":"Gefälschte Trennungen",Ignored:"Ignoriert","A WPA3 Network":"Ein WPA3-Netz","The beacon asks for SAE":"Das Beacon verlangt SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"Das Beacon sieht aus wie bei WPA2, mit zwei Änderungen im RSN-Element: Die Schlüsselverwaltung ist SAE statt PSK, und geschützte Management-Frames sind Pflicht. Alle nutzen weiterhin ein gemeinsames Passwort.","Management frames":"Management-Frames","Protected (required)":"Geschützt (Pflicht)","Still one for everyone":"Weiterhin eins für alle","SAE Commit":"SAE Commit","Each side commits to the password":"Jede Seite legt sich auf das Passwort fest","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"Statt der Open-System-Authentifizierung führen beide Seiten SAE aus, einen Passwortaustausch unter Gleichen. Jede wählt ein zufälliges Geheimnis und schickt einen Skalar und ein Element, berechnet aus diesem Geheimnis und dem Passwort. Das Passwort ist auf beiden Seiten gleich, die Geheimnisse nicht, also bekommt jede Verbindung einen neuen Schlüssel.","19 (256-bit curve)":"19 (256-Bit-Kurve)","Each sends":"Jede schickt","A scalar and an element":"Einen Skalar und ein Element",Replaces:"Ersetzt","Open System authentication":"Die Open-System-Authentifizierung",COMMIT:"COMMIT","scalar + element":"Skalar + Element","SAE Confirm":"SAE Confirm","Proof, without the password":"Beweis, ohne das Passwort","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Jede Seite berechnet jetzt den gemeinsamen Schlüssel und schickt ein Confirm, einen Wert, den nur jemand mit dem richtigen Passwort erzeugen kann. Wer alle vier SAE-Frames aufzeichnet, kann zu Hause trotzdem keine Passwörter raten: Jeder Versuch braucht einen echten Austausch mit dem Access Point, der ihn bremsen oder aussperren kann.","A new key (PMK) each time":"Jedes Mal ein neuer Schlüssel (PMK)",Guessing:"Raten","Live only, never offline":"Nur live, nie offline","Password leaks":"Passwort geleakt","Past traffic stays safe":"Früherer Verkehr bleibt sicher",CONFIRM:"CONFIRM","proof of the key":"Beweis für den Schlüssel","Join, Handshake":"Beitritt, Handshake","Then the 4-way handshake, as in WPA2":"Dann der 4-Wege-Handshake, wie bei WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"Die Assoziierung läuft wie zuvor und wiederholt die Wahl von SAE. Der folgende 4-Wege-Handshake ist der von WPA2, ausgehend vom Schlüssel, den SAE gerade gemacht hat, nur bringt Nachricht 3 zusätzlich den IGTK mit, einen Schlüssel, der Management-Frames im Broadcast signiert.","Message 3 adds":"Nachricht 3 bringt","Why It’s Safer":"Warum es sicherer ist","Forged disconnects stop working":"Gefälschte Trennungen wirken nicht mehr","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Bei WPA2 konnte jeder in Reichweite einen „Trennen“-Frame fälschen und ein Gerät aus dem Netz werfen, oft um seinen Handshake beim erneuten Beitritt aufzuzeichnen. WPA3 verlangt geschützte Management-Frames, also werden gefälschte Trennungen ignoriert. Viele Router bieten auch einen Übergangsmodus, der WPA2-Geräte mit hineinlässt; diese Geräte behalten die Schwächen von WPA2.",Protected:"Geschützt","Disconnects, other management":"Trennungen, weitere Management-Frames","WPA2/3 mode":"WPA2/3-Modus","WPA2 devices stay at risk":"WPA2-Geräte bleiben gefährdet","Stronger still":"Noch stärker","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 Bit)","MANAGEMENT FRAMES PROTECTED":"MANAGEMENT-FRAMES GESCHÜTZT","0x00c0: management frame protection required":"0x00c0: Schutz der Management-Frames Pflicht","Disconnect messages and other management frames are signed, so they can’t be forged.":"Trennungsnachrichten und andere Management-Frames sind signiert und lassen sich daher nicht fälschen.","Authentication · SAE Commit":"Authentifizierung · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: der Passwortaustausch von WPA3.","19 (256-bit elliptic curve)":"19 (elliptische 256-Bit-Kurve)",Scalar:"Skalar","Worked out from a random secret and the password.":"Berechnet aus einem zufälligen Geheimnis und dem Passwort.",Element:"Element","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Ein Punkt auf der Kurve, ebenfalls an das Passwort gebunden. Wer Skalar und Element aufzeichnet, kann später trotzdem keine Passwörter durchprobieren.","Authentication · SAE Confirm":"Authentifizierung · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Beweist, dass diese Seite denselben Schlüssel berechnet hat, ohne ihn zu verraten.","0x0088: pairwise, ACK":"0x0088: paarweise, ACK","0x0108: pairwise, MIC":"0x0108: paarweise, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: paarweise, installieren, ACK, MIC, sicher, Schlüsseldaten verschlüsselt","IGTK: the key that signs broadcast management frames":"IGTK: der Schlüssel, der Management-Frames im Broadcast signiert","0x0308: pairwise, MIC, secure":"0x0308: paarweise, MIC, sicher","Sign-In":"Anmeldung","From the router":"Vom Router","From the test server":"Vom Testserver","Hotel Router":"Hotelrouter","192.168.1.1 · captive portal":"192.168.1.1 · Captive Portal","Wi-Fi login pages":"WLAN-Anmeldeseiten","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Hotels, Cafés, Flughäfen und Züge stellen oft eine Anmeldeseite vor ihr WLAN. Bis du die Bedingungen akzeptierst (oder bezahlst), lässt der Router nichts ins Internet hinaus. Er fängt die erste unverschlüsselte HTTP-Anfrage deines Geräts ab und beantwortet sie mit einer Weiterleitung auf seine eigene Seite; dein Gerät merkt das, weil eine ihm bekannte Testseite falsch zurückkommt.",Where:"Wo","Hotels, cafés, airports":"Hotels, Cafés, Flughäfen",How:"Wie","Catches plain HTTP requests":"Fängt unverschlüsselte HTTP-Anfragen ab","Noticed by":"Bemerkt durch","Your system’s test page":"Die Testseite deines Systems","Logging in":"Bei der Anmeldung","Lets your MAC address through":"Lässt deine MAC-Adresse durch","Newer way":"Neuerer Weg","DHCP option 114 (RFC 8910)":"DHCP-Option 114 (RFC 8910)","Described In":"Beschrieben in",Online:"Online","Noticed, logged in, let through":"Bemerkt, angemeldet, durchgelassen","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows hat eine Testseite nach einer bekannten Antwort gefragt und stattdessen eine Weiterleitung bekommen; so wusste es, dass ein Portal im Weg war, und hat die Anmeldeseite geöffnet. Nachdem die Bedingungen akzeptiert waren, ließ der Router den Laptop durch, und dieselbe Prüfung ging gut. Drücke NOCHMAL, um es dir noch einmal anzusehen.","A plain HTTP test page":"Eine unverschlüsselte HTTP-Testseite","Faked by":"Gefälscht von","The router (TTL 64)":"Dem Router (TTL 64)","Let through":"Durchgelassen","The laptop’s MAC address":"Die MAC-Adresse des Laptops","Open Wi-Fi":"Offenes WLAN","Use HTTPS, or a VPN":"HTTPS nutzen, oder ein VPN","Joined, Offline":"Verbunden, offline","An address, but no way out":"Eine Adresse, aber kein Weg hinaus","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"Der Laptop ist dem WLAN des Hotels beigetreten, das kein Passwort hat, und hat per DHCP eine Adresse vom Router bekommen. Der Router antwortet dem Laptop selbst und reicht seine DNS-Abfragen weiter, verwirft aber alles andere, was ins Internet will, bis sich der Gast angemeldet hat. (Ein offenes Netz bedeutet auch, dass jeder in der Nähe lesen kann, was nicht durch HTTPS geschützt ist.)","192.168.1.10 (by DHCP)":"192.168.1.10 (per DHCP)","Wi-Fi password":"WLAN-Passwort","None (open network)":"Keins (offenes Netz)","Blocked until you log in":"Gesperrt bis zur Anmeldung","CONNECTED, NO INTERNET YET":"VERBUNDEN, NOCH KEIN INTERNET","Internet Check":"Internettest","Windows checks a test page":"Windows prüft eine Testseite",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Nach dem Beitritt zu einem Netz schlägt Windows www.msftconnecttest.com nach (der Router reicht die Abfrage weiter) und fragt dort per unverschlüsseltem HTTP nach /connecttest.txt; die richtige Antwort ist der Text "Microsoft Connect Test". Der Router fängt die Verbindung ab und beantwortet den Handshake selbst, im Namen des Testservers. Der Laptop kann das noch nicht erkennen.',"Test page":"Testseite","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Erwartet","Answered by":"Beantwortet von","The router, posing as the server":"Dem Router, der sich als Server ausgibt",'from "203.0.113.30"':'von "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Umgeleitet","The wrong answer gives it away":"Die falsche Antwort verrät es",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':'Statt des Testtexts antwortet der "Server" mit 302 Found und zeigt auf die Anmeldeseite des Routers. Seine TTL ist 64, überhaupt nicht verringert, weil die Antwort direkt vom Router kommt. Windows sieht die falsche Antwort, markiert das Netz als handlungsbedürftig und öffnet den Browser, dessen erste Anfrage der Router genauso auf seine Anmeldeseite umleitet. Das funktioniert nur mit unverschlüsseltem HTTP: Eine HTTPS-Seite kann der Router nicht ohne Zertifikatsfehler fälschen.',"302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Verräterisch","TTL 64, from one hop away":"TTL 64, nur einen Hop entfernt","Why HTTP":"Warum HTTP","HTTPS can’t be faked":"HTTPS lässt sich nicht fälschen","302 FOUND":"302 FOUND","ACTION NEEDED":"AKTION NÖTIG","The Login Page":"Die Anmeldeseite","Served by the router itself":"Vom Router selbst ausgeliefert","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"Der Browser öffnet http://192.168.1.1/login, eine Seite, die der Router selbst ausliefert: der Name des Hotels, die Nutzungsbedingungen und ein Akzeptieren-Knopf. Diese Verbindung geht wirklich zum Router.",Page:"Seite","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Ausgeliefert von","The router":"Dem Router",Size:"Größe","2,400 bytes of HTML":"2,400 Bytes HTML","/login":"/login","the login page":"die Anmeldeseite","Accept the Terms":"Bedingungen akzeptieren","The router lets the laptop out":"Der Router lässt den Laptop hinaus","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Ein Klick auf Akzeptieren schickt ein kleines Formular an den Router. Er setzt die MAC-Adresse des Laptops auf die Liste der Geräte, die hinausdürfen, oft für die Dauer des Aufenthalts, und leitet den Browser weiter.",Form:"Formular","terms=accepted":"terms=accepted","Router allows":"Router erlaubt","302 to where you were going":"302 dorthin, wo du hinwolltest","you’re online":"du bist online","MAC ADDRESS ALLOWED":"MAC-ADRESSE ERLAUBT","The same check, now real":"Dieselbe Prüfung, jetzt echt","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows prüft erneut. Diesmal lässt der Router die Verbindung zum echten Testserver durch, zwölf Router entfernt (seine Antworten kommen mit TTL 52 an), und die Antwort ist der erwartete Text. Das Netz wird als mit dem Internet verbunden markiert.","Connected to the internet":"Mit dem Internet verbunden",ONLINE:"ONLINE","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, Typ A, Klasse IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Mit 64 gesendet und überhaupt nicht verringert: Sie kam vom Router nebenan, nicht von einem Server 12 Router entfernt.","2,400 bytes: the login page":"2,400 Bytes: die Anmeldeseite","Via a Proxy":"Per Proxy","TLS, through the tunnel":"TLS, durch den Tunnel","Forward proxy, and CONNECT for HTTPS":"Forward-Proxy, und CONNECT für HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Ein Forward-Proxy holt Webseiten in deinem Auftrag. Firmen und Schulen nutzen einen, um Seiten zu filtern, Kopien beliebter Seiten vorzuhalten und zu protokollieren, was hinausgeht; die Websites, die du besuchst, sehen den Proxy, nicht dich. Unverschlüsseltes HTTP läuft offen durch ihn hindurch. Für HTTPS bittet der Browser den Proxy um einen Tunnel, und die verschlüsselte Verbindung läuft ungelesen hindurch.","Common ports":"Übliche Ports","http:// pages":"http://-Seiten","Fetched by the proxy":"Vom Proxy geholt","https:// pages":"https://-Seiten","Tunnelled with CONNECT":"Per CONNECT getunnelt","Used for":"Genutzt für","Filtering, caching, logging":"Filtern, Cachen, Protokollieren","Two ways through":"Zwei Wege hindurch","Fetched for you, or tunnelled":"Für dich geholt, oder getunnelt","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Bei der unverschlüsselten Seite hat der Proxy die Arbeit gemacht: Er hat die Anfrage gelesen, die Seite über seine eigene Verbindung geholt und hätte sie behalten, ändern oder verweigern können. Bei HTTPS hat er nur einen Tunnel geöffnet und verschlüsselte Bytes kopiert, ohne mehr zu wissen als den Namen der Website. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Server sees":"Server sieht","The proxy (192.0.2.80)":"Den Proxy (192.0.2.80)","Plain HTTP":"Unverschlüsseltes HTTP","The proxy reads it all":"Der Proxy liest alles","Name and sizes only":"Nur Name und Größen","DNS for the site":"DNS für die Website","Done by the proxy":"Macht der Proxy","Proxy Settings":"Proxy-Einstellungen","The browser sends everything there":"Der Browser schickt alles dorthin","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"Der Browser ist so eingestellt, dass er alles über einen Proxy unter 192.0.2.80, Port 8080, schickt, wie es viele Firmen und Schulen verlangen. Du öffnest http://www.example.com. Der Browser schlägt www.example.com nicht selbst nach: Er verbindet sich mit dem Proxy und überlässt ihm den Rest.","Left to the proxy":"Dem Proxy überlassen","To the Proxy":"Zum Proxy","TCP to port 8080":"TCP zu Port 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"Der Laptop öffnet eine gewöhnliche TCP-Verbindung, nicht zur Website, sondern zu Port 8080 des Proxys.","192.0.2.80, port 8080":"192.0.2.80, Port 8080","Not to":"Nicht zu","The Whole URL":"Die ganze URL","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"An einen Proxy geschickt, trägt die Anfragezeile die ganze Adresse, nicht nur den Pfad: GET http://www.example.com/ HTTP/1.1. So weiß der Proxy, wohin. Chrome fügt Proxy-Connection: keep-alive hinzu, einen Header, den nur Proxys lesen.","Request line":"Anfragezeile","To a server":"An einen Server","Readable by":"Lesbar für","The proxy (plain HTTP)":"Den Proxy (unverschlüsseltes HTTP)","to the proxy":"an den Proxy","Proxy Fetches It":"Der Proxy holt sie","Its own connection to the server":"Seine eigene Verbindung zum Server","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"Der Proxy schlägt www.example.com selbst nach (nicht gezeigt) und öffnet seine eigene Verbindung zum Server. Seine Anfrage ist die gewöhnliche, GET /, mit eigenen Headern: Via nennt den Proxy, und X-Forwarded-For gibt die Adresse an, von der die Anfrage kam (die öffentliche Adresse des Heimrouters, da der Laptop hinter NAT sitzt).","The proxy’s own":"Die eigene des Proxys","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Weitergeleitet für","Page Passed On":"Seite weitergereicht","The page, passed on":"Die Seite, weitergereicht","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"Der Server antwortet dem Proxy, und der Proxy reicht die Seite mit einem eigenen Via-Header an den Laptop weiter. Er könnte eine Kopie behalten und sie der nächsten Person geben, die danach fragt, ohne den Server zu bemühen (X-Cache: MISS heißt, dass er noch keine hatte), und er kann Websites abweisen, die nicht erlaubt sind.","The proxy, not the laptop":"Der Proxy, nicht der Laptop",Cache:"Cache","MISS (first request)":"MISS (erste Anfrage)","Proxy can":"Proxy kann","Cache, filter, log, change":"Cachen, filtern, protokollieren, ändern","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Jetzt öffnest du https://www.example.com. Ein Proxy kann eine HTTPS-Seite nicht für dich abrufen, ohne die Verschlüsselung zu brechen, also bittet der Browser stattdessen um einen Tunnel: CONNECT www.example.com:443. Der Proxy öffnet eine TCP-Verbindung zu Port 443 und antwortet 200 Connection established.","Proxy opens":"Proxy öffnet","TCP to port 443":"TCP zu Port 443","200 Connection established":"200 Connection established","Connection established":"Verbindung hergestellt","In the Tunnel":"Im Tunnel","The proxy copies, unread":"Der Proxy kopiert, ungelesen","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"Ab jetzt kopiert der Proxy Bytes in beide Richtungen, ohne sie zu lesen. Das TLS-Client-Hello des Browsers geht auf der Verbindung des Laptops hinein und kommt Byte für Byte gleich auf der Verbindung des Proxys zum Server wieder heraus. TLS läuft von Ende zu Ende, also erfährt der Proxy den Namen der Website und die Größen, nie die Seiten. (Manche Firmenproxys öffnen HTTPS doch, mit einer Zertifizierungsstelle, die auf jedem Firmenlaptop installiert ist; dann sehen sie alles.)","Proxy sees":"Proxy sieht","Site name, sizes, timing":"Website-Name, Größen, Timing","Hidden from it":"Vor ihm verborgen","Pages, passwords, cookies":"Seiten, Passwörter, Cookies","TLS, laptop to server":"TLS, Laptop bis Server","the same bytes":"dieselben Bytes","COPIES BYTES, CAN’T READ THEM":"KOPIERT BYTES, KANN SIE NICHT LESEN","Any Connection":"Jede Verbindung","From the proxy":"Vom Proxy","SOCKS Proxy":"SOCKS-Proxy","Socket Secure, version 5":"Socket Secure, Version 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS ist ein Allzweck-Proxy. Wo ein HTTP-Proxy Webanfragen versteht, öffnet ein SOCKS-Proxy einfach in deinem Auftrag eine Verbindung und kopiert die Bytes, egal welches Protokoll: Web, E-Mail, Spiele, SSH. Apps nutzen ihn, um ein Netz über ein einziges Gateway zu erreichen oder ihre eigene Adresse zu verbergen; ssh -D und Tor bieten beide einen an.","Session (Layer 5)":"Sitzung (Schicht 5)","Any TCP, and UDP":"Jedes TCP, und UDP",Logins:"Anmeldung","None, or user and password":"Keine, oder Benutzer und Passwort","Offered by":"Angeboten von","ssh -D, Tor, proxy servers":"ssh -D, Tor, Proxyserver","Tunnel open":"Tunnel offen","A few bytes, then just copying":"Ein paar Bytes, dann nur Kopieren","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Vier winzige Nachrichten sagten dem Proxy, wohin er sich verbinden soll; danach kopierte er nur noch Bytes. Die Website sah die Adresse des Proxys, und weil der Laptop einen Namen statt einer Adresse schickte, fand sogar die DNS-Abfrage beim Proxy statt. Drücke NOCHMAL, um es dir noch einmal anzusehen.","4 messages, 37 bytes":"4 Nachrichten, 37 Bytes","DNS lookup":"DNS-Abfrage","At the proxy":"Beim Proxy","Only the TLS inside":"Nur das TLS darin","TCP to port 1080":"TCP zu Port 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Eine App, die einen SOCKS-Proxy nutzen soll (ein Browser, ein Spiele-Launcher oder ein mit ssh -D gebauter Tunnel), öffnet eine TCP-Verbindung zu ihm, Port 1080. SOCKS ist egal, was darin reist: Er kann jede TCP-Verbindung tragen.","Any TCP connection":"Jede TCP-Verbindung","Wants to reach":"Will erreichen","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Version 5, und wie man sich anmeldet","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"Der Laptop schickt drei Bytes: Version 5, eine angebotene Anmeldemethode und diese Methode, 0: keine Anmeldung. Der Proxy antwortet mit zwei: Version 5, Methode 0. Hätte er Methode 2 gewählt, würde die App als Nächstes Benutzername und Passwort schicken, im Klartext.","Laptop sends":"Laptop schickt","05 01 00 (3 bytes)":"05 01 00 (3 Bytes)","Proxy answers":"Proxy antwortet","05 00 (2 bytes)":"05 00 (2 Bytes)","None needed here":"Hier keine nötig",GREETING:"BEGRÜSSUNG","no login, please":"bitte ohne Anmeldung",METHOD:"METHODE","no login needed":"keine Anmeldung nötig","Where To?":"Wohin?","Connect to www.example.com:443":"Verbinde mit www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"Der Laptop bittet den Proxy, sich mit www.example.com, Port 443, zu verbinden. Er gibt den Namen statt einer Adresse an, also macht der Proxy die DNS-Abfrage, und der Laptop braucht keine. Der Proxy öffnet seine eigene TCP-Verbindung zum Server und antwortet dann: erfolgreich, dazu Adresse und Port, von denen aus er verbunden ist.","www.example.com (a name)":"www.example.com (ein Name)","Succeeded, from 192.0.2.80:40220":"Erfolgreich, von 192.0.2.80:40220",SUCCEEDED:"ERFOLGREICH","from 192.0.2.80:40220":"von 192.0.2.80:40220","Copied both ways, unread":"In beide Richtungen kopiert, ungelesen","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Jetzt kopiert der Proxy nur noch. Die App startet TLS mit dem Server: Ihr Client Hello geht auf der Verbindung des Laptops hinein und kommt unverändert auf der des Proxys heraus, und die Antwort des Servers kommt auf demselben Weg zurück. Der Server sieht immer nur die Adresse des Proxys; der Proxy sieht nur verschlüsselte Bytes.","The proxy’s address":"Die Adresse des Proxys","Encrypted bytes":"Verschlüsselte Bytes","Same bytes":"Dieselben Bytes","On both connections":"Auf beiden Verbindungen",unchanged:"unverändert","+ encrypted handshake":"+ verschlüsselter Handshake","Version 5, 1 method: no login":"Version 5, 1 Methode: keine Anmeldung","Version 5, method chosen: no login":"Version 5, gewählte Methode: keine Anmeldung","Succeeded, bound to 192.0.2.80:40220":"Erfolgreich, gebunden an 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · Begrüßung","Methods offered":"Angebotene Methoden","0 (no login)":"0 (keine Anmeldung)","SOCKS5 · method chosen":"SOCKS5 · gewählte Methode","Method chosen":"Gewählte Methode","SOCKS5 · connect request":"SOCKS5 · Verbindungsanfrage","Open a TCP connection on my behalf.":"Öffne in meinem Auftrag eine TCP-Verbindung.","Address type":"Adresstyp","3 (domain name)":"3 (Domainname)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"Der Proxy schlägt den Namen selbst nach, also braucht der Laptop keine eigene DNS-Abfrage.","SOCKS5 · reply":"SOCKS5 · Antwort","0 (succeeded)":"0 (erfolgreich)","The address the proxy connects from.":"Die Adresse, von der aus sich der Proxy verbindet.",Offloading:"Offloading","Reverse Proxy":"Reverse Proxy","TLS (SSL) offloading":"TLS-(SSL-)Offloading","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Ein Reverse Proxy steht vor den Servern einer Website: Besucher verbinden sich mit ihm, und er reicht ihre Anfragen an einen App-Server dahinter weiter. Er kann die Last auf viele Server verteilen, Kopien von Seiten vorhalten und Angriffe abwehren. Oft übernimmt er auch die TLS-Arbeit und entschlüsselt HTTPS am Rand, sodass die Server dahinter unverschlüsseltes HTTP sprechen. Das ist SSL- (oder TLS-)Offloading.","Visitors reach":"Besucher erreichen","The proxy, never the app":"Den Proxy, nie die App","TLS ends":"TLS endet","At the proxy (offloading)":"Am Proxy (Offloading)","Plain HTTP (or TLS again)":"Unverschlüsseltes HTTP (oder wieder TLS)",Adds:"Fügt hinzu","For example":"Zum Beispiel","nginx, HAProxy, cloud LBs":"nginx, HAProxy, Cloud-Load-Balancer","Served from the edge":"Vom Rand ausgeliefert","Encrypted outside, plain inside":"Außen verschlüsselt, innen offen","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"Der Laptop sah eine einzige HTTPS-Website. Dahinter entschlüsselte der Reverse Proxy die Anfrage, fragte über das private Netz einen App-Server per unverschlüsseltem HTTP und verschlüsselte die Antwort für den Rückweg. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Laptop ↔ proxy only":"Nur Laptop ↔ Proxy","App learns visitor":"App erfährt Besucher","From X-Forwarded-For":"Aus X-Forwarded-For","Certificate kept":"Zertifikat liegt","On the proxy":"Auf dem Proxy","The Front Door":"Die Haustür","The proxy holds the certificate":"Der Proxy hat das Zertifikat","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"Der Laptop öffnet https://www.example.com. Die Adresse, die DNS für den Namen liefert, gehört dem Reverse Proxy, der das Zertifikat der Website hat und den TLS-Handshake macht. Nichts verrät dem Laptop, dass dahinter ein weiterer Server steht.","Laptop connects to":"Laptop verbindet sich mit","On the reverse proxy":"Auf dem Reverse Proxy","Also called":"Auch genannt","Load balancer, edge":"Load Balancer, Edge","TLS Ends Here":"Hier endet TLS","Offloading: the proxy does the TLS work":"Offloading: Der Proxy macht die TLS-Arbeit","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"Die Anfrage kommt verschlüsselt an, und der Reverse Proxy entschlüsselt sie. Das ist das Offloading: Die TLS-Arbeit wird hier einmal erledigt statt auf jedem App-Server. Jetzt kann der Proxy URL, Header und Cookies lesen und danach einen Server auswählen.","At the reverse proxy":"Am Reverse Proxy","Proxy can read":"Proxy kann lesen","URL, headers, cookies":"URL, Header, Cookies","Then picks":"Wählt dann","An app server":"Einen App-Server","TLS ENDS HERE":"HIER ENDET TLS","In the Clear":"Im Klartext","Passed on to the app server":"Weitergereicht an den App-Server","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"Der Proxy reicht die Anfrage über das private Netz des Rechenzentrums weiter, als unverschlüsseltes HTTP an Port 8080. Er fügt X-Forwarded-For hinzu, die Adresse des Besuchers, und X-Forwarded-Proto: https, wie der Besucher hereinkam; sonst sähe die App nur den Proxy. Wer dieses private Netz beobachten kann, könnte alles lesen.","The App Answers":"Die App antwortet","In plain HTTP too":"Ebenfalls unverschlüsselt","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"Der App-Server baut die Seite und antwortet dem Proxy in unverschlüsseltem HTTP: Mit TLS oder Zertifikaten hat er nie zu tun.","text/html, 12,500 bytes":"text/html, 12,500 Bytes","readable inside":"innen lesbar","Encrypted Again":"Wieder verschlüsselt","An ordinary HTTPS answer":"Eine gewöhnliche HTTPS-Antwort","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"Der Reverse Proxy verschlüsselt die Antwort in der TLS-Sitzung, die er mit dem Laptop hält, und schickt sie weiter. Von außen ist es eine gewöhnliche HTTPS-Website.","Laptop sees":"Laptop sieht","One HTTPS server":"Einen HTTPS-Server","App servers":"App-Server","Never handle TLS":"Haben nie mit TLS zu tun",Certificates:"Zertifikate","Renewed in one place":"An einer Stelle erneuert","Three Options":"Drei Möglichkeiten","Offload, re-encrypt or pass through":"Offloaden, neu verschlüsseln oder durchreichen","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Offloading, wie hier, ist einfach und schnell, lässt den Verkehr im Inneren aber lesbar. Beim Neuverschlüsseln öffnet der Proxy eine zweite TLS-Verbindung zum App-Server, sodass auch innen alles verschlüsselt bleibt. Beim Durchreichen leitet er die TLS-Bytes weiter, ohne sie zu öffnen: Das Zertifikat liegt auf den App-Servern, und der Proxy kann einen Server nur nach Adresse und dem Namen im Client Hello wählen, nicht nach URL.",Offload:"Offloading","Plain HTTP inside":"Innen unverschlüsseltes HTTP","Re-encrypt":"Neu verschlüsseln","TLS inside as well":"Auch innen TLS","Pass through":"Durchreichen","Proxy can’t read it":"Proxy kann es nicht lesen","PLAIN HTTP INSIDE":"INNEN UNVERSCHLÜSSELTES HTTP","A Modern VPN":"Ein modernes VPN","WireGuard (encrypted)":"WireGuard (verschlüsselt)","TCP beyond the VPN":"TCP hinter dem VPN",Keepalive:"Keepalive","VPN Server":"VPN-Server","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"Ein VPN trägt deinen Verkehr in einem verschlüsselten Tunnel zu einem VPN-Server, der ihn ins Internet weiterschickt. Im WLAN eines Cafés sehen andere nur verschlüsselte Pakete zum VPN-Server; Websites sehen die Adresse des VPN-Servers statt deiner. WireGuard ist ein modernes VPN: wenig Code, ein fester Satz moderner Algorithmen und ein Handshake aus zwei Nachrichten.","UDP (51820 by default)":"UDP (standardmäßig 51820)","2 messages, 1 round trip":"2 Nachrichten, 1 Roundtrip",Crypto:"Kryptografie",Identity:"Identität","Public keys, like SSH":"Öffentliche Schlüssel, wie bei SSH","The WireGuard whitepaper":"Das WireGuard-Whitepaper","Tunnel up":"Tunnel steht","Encrypted to the VPN, plain beyond it":"Bis zum VPN verschlüsselt, dahinter offen","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Zwei Handshake-Nachrichten erzeugten die Schlüssel. Danach steckte jedes Paket, das der Laptop schickte, vollständig versiegelt in einem UDP-Paket zum VPN-Server, und die Website sah nur die Adresse des VPN-Servers. Hinter dem VPN-Server ist der Verkehr nicht besser geschützt als ohne VPN, deshalb bleibt HTTPS wichtig. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Others nearby see":"Andere in der Nähe sehen","UDP to 192.0.2.51":"UDP an 192.0.2.51","Websites see":"Websites sehen","The VPN server":"Den VPN-Server","Beyond the VPN":"Hinter dem VPN","Only HTTPS protects":"Nur HTTPS schützt",Overhead:"Overhead","60 bytes + padding":"60 Bytes + Auffüllung","Set Up Once":"Einmal eingerichtet","Keys, not passwords":"Schlüssel statt Passwörter","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"Der Laptop führt die WireGuard-App mit einer kurzen Konfiguration aus: sein eigener privater Schlüssel, der öffentliche Schlüssel und die Adresse des Servers (192.0.2.51, UDP-Port 51820) und AllowedIPs = 0.0.0.0/0, was heißt, dass alles durch den Tunnel geht. Im Tunnel hat der Laptop die Adresse 10.8.0.2.","Inside address":"Adresse im Tunnel","Through the tunnel":"Durch den Tunnel","Everything (0.0.0.0/0)":"Alles (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"TUNNELADRESSE 10.8.0.2","Two messages, one round trip":"Zwei Nachrichten, ein Roundtrip","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Wenn der Laptop zum ersten Mal etwas zu senden hat, startet er einen Handshake: 148 Bytes mit einem frischen öffentlichen Schlüssel, seinem eigenen langfristigen Schlüssel (verschlüsselt, damit nur der Server erfährt, wer anruft) und der Uhrzeit (verschlüsselt, damit eine Aufzeichnung nicht wiederholt werden kann). Der Server antwortet nur Schlüsseln, die er kennt, hier mit 92 Bytes. Ein Roundtrip, und beide Seiten haben neue Sitzungsschlüssel.",Initiation:"Initiation","Server answers":"Server antwortet","Only keys it knows":"Nur bekannten Schlüsseln",INITIATION:"INITIATION","fresh key + identity":"frischer Schlüssel + Identität",RESPONSE:"ANTWORT","keys agreed":"Schlüssel vereinbart","Into the Tunnel":"In den Tunnel","A packet inside a packet":"Ein Paket in einem Paket","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Du öffnest https://www.example.com; die Adresse wurde ebenfalls durch den Tunnel nachgeschlagen (nicht gezeigt). Das erste Paket der Verbindung, ein TCP-SYN von 10.8.0.2 an den Webserver, wird vollständig verschlüsselt und in einem UDP-Paket an den VPN-Server geschickt. Im WLAN des Cafés ist nur das äußere Paket zu sehen: vom Laptop an 192.0.2.51, Port 51820.",Outside:"Außen","UDP to 192.0.2.51:51820":"UDP an 192.0.2.51:51820","inside: TCP SYN to :443":"innen: TCP-SYN an :443","Out to the Web":"Hinaus ins Web","Decrypted, then sent on":"Entschlüsselt, dann weitergeschickt","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"Der VPN-Server entschlüsselt das Paket, tauscht 10.8.0.2 gegen seine eigene öffentliche Adresse (NAT) und schickt das SYN weiter, einen Hop älter (TTL 127). Das SYN bietet ein maximales Segment von 1380 Bytes an, nicht 1460: Der Tunnel fügt jedem Paket 60 Bytes hinzu. Der Webserver sieht einen Besucher unter 192.0.2.51 und antwortet dorthin.","Website sees":"Website sieht","192.0.2.51 (the VPN)":"192.0.2.51 (das VPN)","Hidden from the site":"Vor der Website verborgen","127 (one hop, the VPN)":"127 (ein Hop, das VPN)","from 192.0.2.51":"von 192.0.2.51","The Way Back":"Der Rückweg","Sealed again, for the laptop":"Wieder versiegelt, für den Laptop","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"Die Antwort nimmt denselben Weg zurück. Der VPN-Server versiegelt das SYN-ACK in einem WireGuard-Paket für den Laptop, der es öffnet und an Windows übergibt, als käme es direkt vom Webserver.",Counter:"Zähler","Each side counts its own":"Jede Seite zählt selbst",Replays:"Wiederholungen","Thrown away":"Werden verworfen","inside: TCP SYN-ACK":"innen: TCP-SYN-ACK","Keeping It Open":"Offen halten","A keepalive, and new keys":"Ein Keepalive und neue Schlüssel","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Wenn nichts zu senden ist, wird ein WireGuard-Tunnel still. Weil der Laptop hinter NAT steht, ist er so eingestellt, dass er alle 25 Sekunden ein leeres Paket schickt (PersistentKeepalive), ein Keepalive von 32 Bytes, damit der Router die Verbindung nicht vergisst. Alle zwei Minuten erzeugt ein neuer Handshake frische Schlüssel, und wechselt der Laptop in ein anderes Netz, läuft der Tunnel einfach von der neuen Adresse aus weiter.","Every 25 s, 32 bytes":"Alle 25 s, 32 Bytes","New keys":"Neue Schlüssel","Every 2 minutes":"Alle 2 Minuten","New network":"Neues Netz","The tunnel carries on":"Der Tunnel läuft weiter",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"leer, 32 Bytes","Message type":"Nachrichtentyp","Sender index":"Absenderindex","A number this side picked for the session; the other side puts it in every packet it sends back.":"Eine Zahl, die diese Seite für die Sitzung gewählt hat; die andere Seite setzt sie in jedes Paket, das sie zurückschickt.","Ephemeral key":"Ephemerer Schlüssel","A new public key, made just for this handshake.":"Ein neuer öffentlicher Schlüssel, nur für diesen Handshake erzeugt.","Encrypted static key":"Verschlüsselter statischer Schlüssel","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"Der langfristige öffentliche Schlüssel des Laptops (32 Bytes) und ein 16-Byte-Tag, verschlüsselt: Nur der Server erfährt, wer anruft.","Encrypted timestamp":"Verschlüsselter Zeitstempel","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"Die Uhrzeit (12 Bytes) und ein Tag, verschlüsselt. Eine alte Initiation, die erneut geschickt wird, wird abgewiesen.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Mit dem öffentlichen Schlüssel des Servers berechnet: Ohne ihn antwortet der Server gar nicht.","Used only when the server is busy and asks for a cookie first.":"Nur genutzt, wenn der Server ausgelastet ist und zuerst ein Cookie verlangt.","Receiver index":"Empfängerindex","The other side’s index: which session this packet belongs to.":"Der Index der anderen Seite: zu welcher Sitzung dieses Paket gehört.","The server’s new public key for this handshake.":"Der neue öffentliche Schlüssel des Servers für diesen Handshake.","Encrypted nothing":"Verschlüsseltes Nichts","Only a tag: it proves the server holds its private key.":"Nur ein Tag: Es beweist, dass der Server seinen privaten Schlüssel besitzt.","Counts up with every packet; one seen before is thrown away.":"Zählt mit jedem Paket hoch; ein schon gesehenes wird verworfen.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"Das ganze innere Paket, auf ein Vielfaches von 16 Bytes aufgefüllt, dann ein 16-Byte-Tag.","then 12 bytes of padding, and the tag":"dann 12 Bytes Auffüllung und das Tag","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"Der Laptop schickte es mit 128; der VPN-Server zog beim Weiterleiten 1 ab.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Nichts als das 16-Byte-Tag: ein leeres Paket, das den Tunnel offen hält.","ESP (encrypted)":"ESP (verschlüsselt)","TCP beyond the gateway":"TCP hinter dem Gateway","VPN Gateway":"VPN-Gateway","IP Security":"IP-Sicherheit","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec schützt die IP-Pakete selbst. IKEv2 richtet alles ein: Die beiden Seiten einigen sich auf Algorithmen, erzeugen Schlüssel und weisen mit Zertifikaten oder anderen Nachweisen nach, wer sie sind. Dann trägt ESP jedes Paket verschlüsselt in einem anderen. IPsec verbindet Büros miteinander und holt Laptops ins Firmennetz, und es ist in die meisten Betriebssysteme und Firewalls eingebaut.","Behind NAT":"Hinter NAT","ESP (IP protocol 50)":"ESP (IP-Protokoll 50)","Certificates, EAP, keys":"Zertifikate, EAP, Schlüssel","IKE to set up, ESP to carry":"IKE zum Einrichten, ESP zum Tragen","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Vier IKE-Nachrichten einigten sich auf Algorithmen, erkannten das NAT, wiesen beide Identitäten nach und richteten den Tunnel ein. Danach reiste jedes Paket vollständig in ESP, verschlüsselt und geprüft, und in UDP verpackt, um durch den Heimrouter zu kommen. Drücke NOCHMAL, um es dir noch einmal anzusehen.","IKE messages":"IKE-Nachrichten","4 (2 exchanges)":"4 (2 Austausche)","NAT traversal":"NAT-Traversal","One SPI each way":"Ein SPI pro Richtung","Agree on algorithms, swap keys":"Algorithmen vereinbaren, Schlüssel tauschen","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"Der VPN-Client beginnt mit IKE auf UDP-Port 500. Seine erste Nachricht schlägt die Algorithmen vor (AES-GCM mit 256-Bit-Schlüsseln, SHA-256, Curve25519) und trägt einen öffentlichen Schlüssel und eine zufällige Nonce; das Gateway wählt den Vorschlag und schickt seinen eigenen Schlüssel und seine Nonce. Beide teilen jetzt ein Geheimnis, aber keiner hat schon bewiesen, wer er ist.",Proposed:"Vorgeschlagen","After this":"Danach","Shared keys, no identities":"Gemeinsame Schlüssel, keine Identitäten","proposal, key, nonce":"Vorschlag, Schlüssel, Nonce","NAT detection":"NAT-Erkennung","chosen proposal, key, nonce":"gewählter Vorschlag, Schlüssel, Nonce","A NAT in the Way":"Ein NAT im Weg","So everything moves to port 4500":"Also zieht alles auf Port 4500 um","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Beide Nachrichten enthielten auch Hashes der Adresse und des Ports, von denen jede Seite gesendet hat. Am Gateway passen sie nicht zu dem, was ankam: Der Heimrouter hat die Adresse des Laptops unterwegs umgeschrieben (NAT). ESP hat keine Portnummern, also kann ein NAT es nicht durchlassen; beide Seiten wechseln auf UDP-Port 4500 und verpacken ESP ab jetzt in UDP.","Hashes of":"Hashes von","Address and port sent from":"Adresse und Port des Absenders",Mismatch:"Passt nicht","The router rewrote them":"Der Router hat sie umgeschrieben",Fix:"Lösung","Everything over UDP 4500":"Alles über UDP 4500","NAT DETECTED":"NAT ERKANNT","Prove who you are, encrypted":"Beweisen, wer man ist, verschlüsselt","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Jetzt verschlüsselt schickt jede Seite ihre Identität, ihr Zertifikat und eine Signatur über alles bisher Gesagte, sodass jeder in der Mitte auffliegen würde. Der Laptop bittet um eine Adresse im Netz und bekommt 10.8.0.2. Derselbe Austausch richtet auch den ESP-Tunnel selbst ein, mit eigenen Schlüsseln und einem SPI pro Richtung.","UDP 4500 (NAT traversal)":"UDP 4500 (NAT-Traversal)","Identity, by certificate":"Identität, per Zertifikat","Laptop gets":"Laptop bekommt","10.8.0.2, and a DNS server":"10.8.0.2 und einen DNS-Server","identity, certificate":"Identität, Zertifikat",signature:"Signatur","address 10.8.0.2":"Adresse 10.8.0.2","The whole packet, encrypted":"Das ganze Paket, verschlüsselt","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Du öffnest https://www.example.com, nachgeschlagen durch den Tunnel beim DNS-Server, den das Gateway mitgeteilt hat (nicht gezeigt). Das SYN von 10.8.0.2 wird vollständig in ein ESP-Paket verschlüsselt: ein SPI, der den Tunnel benennt, eine Sequenznummer, dann das verschlüsselte Paket und ein Prüfwert, alles in UDP-Port 4500. Seine UDP-Prüfsumme ist null: ESP prüft seinen Inhalt selbst.","Names the tunnel":"Benennt den Tunnel","The whole IP packet":"Das ganze IP-Paket","62 bytes + padding":"62 Bytes + Auffüllung","Out and Back":"Hin und zurück","Through the gateway and home again":"Durchs Gateway und wieder heim","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"Das Gateway entschlüsselt das Paket und schickt das SYN von seiner eigenen Adresse aus weiter, einen Hop älter. Die Antwort kommt zum Gateway zurück und läuft als weiteres ESP-Paket durch den Tunnel zurück, mit dem SPI für die Richtung des Laptops und eigenen Sequenznummern.","192.0.2.51 (the gateway)":"192.0.2.51 (das Gateway)","Each direction":"Jede Richtung","Its own SPI and keys":"Eigener SPI und eigene Schlüssel","Which VPN?":"Welches VPN?","IPsec or WireGuard":"IPsec oder WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec ist älter und sehr flexibel: Es handelt seine Algorithmen aus, akzeptiert viele Arten von Nachweisen und ist in Windows, macOS, iOS, Android und die meisten Firewalls eingebaut. Damit ist es der übliche Weg, sich mit einem Firmennetz zu verbinden oder zwei Büros zu koppeln. WireGuard kann weniger, mit viel weniger Code und einem festen Satz von Algorithmen.","Built into":"Eingebaut in","Also links":"Verbindet auch","Office to office":"Büro mit Büro",Negotiates:"Handelt aus","Its algorithms (WireGuard: no)":"Seine Algorithmen (WireGuard: nein)","Initiator SPI":"Initiator-SPI","Picked by the laptop: which IKE session this is.":"Vom Laptop gewählt: welche IKE-Sitzung das ist.","Responder SPI":"Responder-SPI","0 (not known yet)":"0 (noch unbekannt)","Next payload":"Nächste Nutzdaten","Exchange type":"Austauschtyp","0x08 (initiator)":"0x08 (Initiator)","Message ID":"Nachrichten-ID","Each request and its response share a number; the next exchange counts up.":"Jede Anfrage und ihre Antwort teilen eine Nummer; der nächste Austausch zählt hoch.","SA payload":"SA-Nutzdaten","Next payload, length":"Nächste Nutzdaten, Länge",Proposal:"Vorschlag","What the laptop offers; a real client often offers several.":"Was der Laptop anbietet; ein echter Client bietet oft mehrere an.","KE payload":"KE-Nutzdaten","DH group":"DH-Gruppe","This side’s public key. From the two, both work out the same secret.":"Der öffentliche Schlüssel dieser Seite. Aus beiden berechnen beide dasselbe Geheimnis.","Nonce payload":"Nonce-Nutzdaten","Notify payload":"Notify-Nutzdaten",Notify:"Notify",Hash:"Hash","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Ein Hash der SPIs und der Adresse und des Ports, von denen diese Seite gesendet hat. Passt das Angekommene nicht dazu, hat ein NAT es unterwegs verändert.","The same for the address and port it sent to.":"Dasselbe für Adresse und Port, an die sie gesendet hat.","0x20 (response)":"0x20 (Antwort)","The one the server chose from the laptop’s offer.":"Der, den der Server aus dem Angebot des Laptops gewählt hat.","Non-ESP marker":"Nicht-ESP-Markierung","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Vier Nullbytes: eine IKE-Nachricht, kein ESP-Paket (sie teilen sich Port 4500).","Encrypted payload":"Verschlüsselte Nutzdaten","Encrypted payloads":"Verschlüsselte Nutzdaten","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Alles Übrige in dieser Nachricht, verschlüsselt mit den Schlüsseln aus IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: wer der Laptop ist, bewiesen","CP: asks for an inside address and DNS":"CP: bittet um eine innere Adresse und DNS","SA: what to use for ESP (AES-GCM)":"SA: was für ESP genutzt wird (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: welcher Verkehr in den Tunnel geht","Integrity check":"Integritätsprüfung","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: wer das Gateway ist, bewiesen","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: innere Adresse 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP mit AES-GCM, und die SPIs","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: alles (0.0.0.0/0)","0 (not used)":"0 (nicht genutzt)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP prüft seinen Inhalt selbst, deshalb lässt ESP in UDP dieses Feld auf null.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"Zu welchem Tunnel (Security Association) das gehört; die empfangende Seite hat ihn während IKE_AUTH gewählt.","Different for every packet.":"Für jedes Paket anders.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"Das ganze innere Paket, dann Auffüllung, Padding-Länge und nächster Header (4: ein IPv4-Paket).","then padding, pad length and next header (4)":"dann Auffüllung, Padding-Länge und nächster Header (4)","Shows any change to the packet.":"Zeigt jede Änderung am Paket.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"Der Laptop schickte es mit 128; das Gateway zog beim Weiterleiten 1 ab.","HTTP/3 over QUIC":"HTTP/3 über QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC ist ein neueres Transportprotokoll, das über UDP läuft und TLS 1.3 eingebaut hat. Seine ersten Pakete erledigen den Transport- und den Verschlüsselungs-Handshake zusammen, sodass eine Seitenanfrage nach einem einzigen Roundtrip losgehen kann. Es trägt viele Streams gleichzeitig, sodass ein verlorenes Paket den Rest nicht aufhält, und es übersteht einen Netzwechsel. HTTP/3 ist HTTP über QUIC.","Runs over":"Läuft über","UDP, port 443":"UDP, Port 443","TLS 1.3, always":"TLS 1.3, immer","1 round trip (0 when returning)":"1 Roundtrip (0 bei Wiederkehr)",Streams:"Streams","Many, independent":"Viele, unabhängig","One round trip, then the request":"Ein Roundtrip, dann die Anfrage","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC fasste den Transport- und den TLS-Handshake in einem Roundtrip zusammen, sodass die Anfrage 36 ms nach dem ersten Paket losging; über TCP und TLS hätte sie doppelt so lange gewartet. Alles nach den ersten Paketen war verschlüsselt, sogar der größte Teil jedes Paket-Headers. Drücke NOCHMAL, um es dir noch einmal anzusehen.","1 before the request (TCP + TLS: 2)":"1 vor der Anfrage (TCP + TLS: 2)","Lost packet":"Verlorenes Paket","Holds up one stream only":"Hält nur einen Stream auf","Choosing HTTP/3":"HTTP/3 wählen","An earlier visit said it can":"Ein früherer Besuch hat es verraten",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'Bei einem früheren Besuch antwortete der Server mit Alt-Svc: h3=":443", das heißt, er spricht auch HTTP/3 auf UDP-Port 443 (DNS kann dasselbe in einem HTTPS-Eintrag sagen). Also überspringt der Browser diesmal TCP und spricht QUIC.',"Learned from":"Erfahren aus","Alt-Svc header, or DNS":"Alt-Svc-Header oder DNS","QUIC over UDP 443":"QUIC über UDP 443","TLS 1.3, built in":"TLS 1.3, eingebaut","Initial Packets":"Initial-Pakete","The Client Hello, straight away":"Das Client Hello, sofort","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Es gibt keinen separaten TCP-Handshake: Schon die allerersten Pakete tragen das TLS-Client-Hello. Mit seinem Post-Quanten-Schlüsselanteil ist es 1,880 Bytes groß, zu groß für ein Paket, also füllt es zwei Initial-Pakete. Jedes Datagramm wird auf mindestens 1,200 Bytes aufgefüllt; ein Server darf nur das Dreifache dessen zurückschicken, was er empfangen hat, damit eine gefälschte Absenderadresse ihn nicht zum Verstärker macht.","2 × 1,250 bytes":"2 × 1,250 Bytes","The TLS Client Hello":"Das TLS-Client-Hello","Readable?":"Lesbar?","Yes (Initial keys are public)":"Ja (Initial-Schlüssel sind öffentlich)","Client Hello, part 1":"Client Hello, Teil 1","Client Hello, part 2":"Client Hello, Teil 2",padding:"Auffüllung","Then the certificate, encrypted":"Dann das Zertifikat, verschlüsselt","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"Der Server antwortet mit seinem Server Hello in einem Initial-Paket. Beide Seiten können nun Handshake-Schlüssel berechnen, also kommt der Rest (das Zertifikat, seine Signatur und Finished) in Handshake-Paketen, die nur der Laptop lesen kann. Vier Datagramme, weit unter dem Dreifachen dessen, was der Laptop geschickt hat.","Certificate, signature, Finished":"Zertifikat, Signatur, Finished","Server limit":"Server-Grenze","3× the bytes received":"3× die empfangenen Bytes","certificate, Finished":"Zertifikat, Finished","The request, one round trip in":"Die Anfrage, nach einem Roundtrip","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"Der Laptop prüft das Zertifikat und schickt sein Finished und im selben Moment seine erste HTTP/3-Anfrage in einem 1-RTT-Paket: einen HEADERS-Frame auf Stream 0, die Header mit QPACK komprimiert. Einen Roundtrip nach dem ersten Paket ist die Anfrage unterwegs; TCP und TLS zusammen bräuchten zwei.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS auf Stream 0",Headers:"Header","Compressed (QPACK)":"Komprimiert (QPACK)","HTTP/3, stream 0":"HTTP/3, Stream 0","The Response":"Die Antwort","On its own stream":"Auf ihrem eigenen Stream","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"Der Server bestätigt, dass der Handshake vorbei ist (HANDSHAKE_DONE), und antwortet auf Stream 0: Header, dann die Seite. Jede Anfrage bekommt ihren eigenen Stream, sodass ein verlorenes Paket nur den Stream aufhält, zu dem es gehörte. Über TCP blockiert ein fehlendes Segment alles dahinter.","Frames on QUIC streams":"Frames auf QUIC-Streams","Holds up one stream":"Hält einen Stream auf","All but a few header bits":"Alles außer ein paar Header-Bits","the page":"die Seite","New Network":"Neues Netz","Known by ID, not by address":"Erkannt an der ID, nicht an der Adresse","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Eine QUIC-Verbindung wird an ihren Verbindungs-IDs erkannt, nicht an Adressen und Ports. Wechselt der Laptop vom WLAN zum Hotspot eines Handys, ändert sich seine Adresse, aber die Verbindung läuft weiter: Der Server prüft den neuen Pfad und macht weiter. Und beim nächsten Besuch kann der Browser seine Anfrage schon in den allerersten Paketen schicken (0-RTT).","Known by":"Erkannt an","Connection ID":"Verbindungs-ID","New address":"Neue Adresse","The connection carries on":"Die Verbindung läuft weiter","Next visit":"Nächster Besuch","0-RTT: request at once":"0-RTT: Anfrage sofort","SAME CONNECTION ON ANY NETWORK":"DIESELBE VERBINDUNG IN JEDEM NETZ","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, Teil 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, Teil 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (Zertifikat, Teil 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (Zertifikat, Teil 2)","Initial packet":"Initial-Paket","Header type":"Header-Typ","long header, Initial":"langer Header, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"Die oberen Bits sagen, welche Art Paket das ist; die letzten sind getarnt (Header-Schutz).","Destination connection ID":"Ziel-Verbindungs-ID","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"Zu welcher Verbindung es gehört. Jede Seite wählt ihre eigene ID; die andere schreibt sie hierher.","Source connection ID":"Quell-Verbindungs-ID","Token length":"Token-Länge","No token: the server hasn’t asked this client to prove its address first.":"Kein Token: Der Server hat diesen Client nicht gebeten, zuerst seine Adresse nachzuweisen.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Die Paketnummer und die Nutzdaten. Was danach folgt, ist ein weiteres Paket im selben Datagramm.","Packet number":"Paketnummer","Hidden by header protection, so nobody on the way can read or change it.":"Durch den Header-Schutz verborgen, damit niemand unterwegs sie lesen oder ändern kann.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Mit Schlüsseln verschlüsselt, die jeder aus der Verbindungs-ID berechnen kann – das verhindert Unfälle, nicht Lauscher: Das Client Hello darin ist unterwegs lesbar.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, Bytes 1–1,203 von 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, X25519MLKEM768-Schlüsselanteil","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, Bytes 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, bis 1,250 Bytes","ACK: packets 0–1 arrived":"ACK: Pakete 0–1 angekommen","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, mit seiner Hälfte des Schlüssels (1,120 Bytes)","Handshake packet":"Handshake-Paket","long header, Handshake":"langer Header, Handshake","Encrypted with keys from the key exchange so far.":"Mit Schlüsseln aus dem bisherigen Schlüsselaustausch verschlüsselt.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (Anfang)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (Fortsetzung)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: das Initial des Servers ist angekommen","ACK: the Handshake packets arrived":"ACK: die Handshake-Pakete sind angekommen","1-RTT packet":"1-RTT-Paket","short header":"kurzer Header","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Nur die ID des Empfängers und keine Länge: Er weiß, wie lang seine eigenen IDs sind. Sie bleibt gleich, wenn der Laptop das Netz wechselt.","Encrypted with the session keys.":"Mit den Sitzungsschlüsseln verschlüsselt.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (der Steuer-Stream)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (QPACK-komprimiert)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: der Handshake ist vorbei","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, dann DATA: die Seite (1,000 Bytes)","ACK: the response arrived":"ACK: die Antwort ist angekommen","Address Setup":"Adresse einrichten","No IPv6 address":"Keine IPv6-Adresse","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC und Nachbarermittlung","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"IPv6-Adressen sind 128 Bit lang, genug, damit jedes Gerät seine eigene hat. Meist kann sich ein Gerät ohne DHCP-Server selbst einrichten: Es bildet eine Link-Local-Adresse, fragt nach einem Router und baut seine globale Adresse aus dem Präfix, das der Router ankündigt (SLAAC). Die Nachbarermittlung, ein Teil von ICMPv6, findet MAC-Adressen und erledigt, was ARP bei IPv4 tut.","128 bits":"128 Bit",Addresses:"Adressen","SLAAC: no server needed":"SLAAC: kein Server nötig","Replaces ARP":"Ersetzt ARP","Neighbour discovery":"Nachbarermittlung",Optional:"Optional","Two addresses, no DHCP":"Zwei Adressen, kein DHCP","Made by the laptop itself":"Vom Laptop selbst gebildet","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"Der Laptop bildete eine Link-Local- und eine globale Adresse, prüfte, dass niemand sonst eine davon hatte, und erfuhr Router, MTU und DNS-Server aus einer einzigen Ankündigung. Als Pakete für ihn ankamen, fand die Nachbarermittlung seine MAC-Adresse. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Link-local":"Link-Local",Global:"Global","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + eigene ID","Router, DNS":"Router, DNS","From one advertisement":"Aus einer Ankündigung","6, all ICMPv6":"6, alle ICMPv6","Link-Local First":"Zuerst Link-Local","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Jede IPv6-Schnittstelle bekommt eine Link-Local-Adresse, die nur im eigenen Netz nutzbar ist. Der Laptop bildet eine aus fe80:: und einer zufällig aussehenden 64-Bit-Schnittstellen-ID. Zuerst prüft er, dass niemand sie schon hat: ein Neighbor Solicitation, das nach dieser Adresse fragt, gesendet von ::, weil er die Adresse noch nicht benutzen darf. Niemand antwortet, also gehört sie dem Laptop.",Check:"Prüfung","Duplicate address detection":"Erkennung doppelter Adressen","None: the address is free":"Keine: Die Adresse ist frei","IS IT TAKEN?":"SCHON VERGEBEN?","from ::":"von ::","target fe80::8d2e:4f61:a9b0:7c13":"Ziel fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"KEINE ANTWORT: ADRESSE IST FREI","Any Routers?":"Gibt es Router?","A Router Solicitation":"Ein Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Link-Local-Adressen erreichen das Internet nicht. Der Laptop schickt ein Router Solicitation an ff02::2, die Adresse, auf die jeder Router im Netz hört, mit seiner eigenen MAC-Adresse dabei.","ff02::2 (all routers)":"ff02::2 (alle Router)",Includes:"Enthält","ROUTERS?":"ROUTER?","Router Answers":"Der Router antwortet","Prefix, MTU and DNS in one message":"Präfix, MTU und DNS in einer Nachricht","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"Der Router antwortet an ff02::1, jedes Gerät im Netz, mit einem Router Advertisement: Nimm mich 30 Minuten lang als Weg nach draußen, hier ist meine MAC-Adresse, die MTU ist 1500, das Präfix des Netzes ist 2001:db8:1234:5678::/64 und du darfst darin deine eigene Adresse bilden, und frag 2001:4860:4860::8888 nach DNS. Router schicken solche Ankündigungen auch von sich aus alle paar Minuten.",Prefix:"Präfix","Make your own":"Eigene bilden","Yes (flag A)":"Ja (Flag A)",ADVERTISEMENT:"ANKÜNDIGUNG","prefix 2001:db8:1234:5678::/64":"Präfix 2001:db8:1234:5678::/64","A Global Address":"Eine globale Adresse","Prefix + interface ID":"Präfix + Schnittstellen-ID","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"Der Laptop setzt das Präfix und seine Schnittstellen-ID zu einer globalen Adresse zusammen, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, und prüft sie auf dieselbe Weise. Windows bildet außerdem eine temporäre Adresse mit einer zufälligen ID, die sich täglich ändert, für ausgehende Verbindungen, damit Websites ein Gerät nicht an seiner Adresse verfolgen können.","Also made":"Außerdem gebildet","A temporary address":"Eine temporäre Adresse","target the global address":"Ziel ist die globale Adresse","Neighbour Lookup":"Nachbar nachschlagen","Who has this address? (ARP’s job)":"Wer hat diese Adresse? (die Aufgabe von ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Eine Antwort aus dem Internet kommt beim Router für die globale Adresse des Laptops an. Um sie zuzustellen, braucht der Router die zugehörige MAC-Adresse: Er schickt ein Neighbor Solicitation an die Solicited-Node-Gruppe dieser Adresse, sodass nur Geräte, deren Adresse gleich endet, überhaupt hinschauen. Der Laptop antwortet mit einem Neighbor Advertisement mit seiner MAC-Adresse.","Asked to":"Gefragt bei","Instead of":"Statt","ARP broadcasts to everyone":"ARP-Broadcast an alle","WHO HAS?":"WER HAT?","the global address":"die globale Adresse","Ready, No DHCP":"Fertig, ohne DHCP","And no NAT either":"Und auch ohne NAT","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"Der Laptop ist mit seiner eigenen globalen Adresse im Internet, und kein NAT ändert sie unterwegs: Die Adresse, die eine Website sieht, ist die des Laptops. Die Firewall des Heimrouters weist trotzdem Verbindungen ab, die niemand drinnen angefordert hat. Netze, die Adressen zentral vergeben wollen, können stattdessen DHCPv6 nutzen.","Not needed":"Nicht nötig",Incoming:"Eingehend","Blocked by the firewall":"Von der Firewall blockiert","Optional (flags M, O)":"Optional (Flags M, O)","ONLINE OVER IPv6":"ONLINE ÜBER IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Eine Multicast-MAC-Adresse: 33:33, dann die letzten vier Bytes der IPv6-Adresse.","Version, class, flow":"Version, Klasse, Flow","IPv6, ordinary traffic, no flow label.":"IPv6, gewöhnlicher Verkehr, kein Flow-Label.","Payload length":"Nutzdatenlänge","What follows this 40-byte header.":"Was auf diesen 40-Byte-Header folgt.","Next header":"Nächster Header","Hop limit":"Hop-Limit","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"Nachbarermittlung muss mit 255 ankommen, als Beweis, dass kein Router sie weitergeleitet hat: Sie kam aus diesem Netz.","Unspecified: the laptop has no address it may use yet.":"Unspezifiziert: Der Laptop hat noch keine Adresse, die er benutzen darf.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Solicited-Node-Multicast: Nur Geräte, deren Adresse auf dieselben 24 Bit endet, hören zu.","Covers the message and both IPv6 addresses.":"Deckt die Nachricht und beide IPv6-Adressen ab.",Target:"Ziel","The address the laptop wants to use. If anyone answers, it’s taken.":"Die Adresse, die der Laptop benutzen will. Antwortet jemand, ist sie vergeben.","A link-local address: usable only on this network.":"Eine Link-Local-Adresse: nur in diesem Netz nutzbar.","Every router on this network.":"Jeder Router in diesem Netz.","Source link-layer address":"Link-Layer-Adresse der Quelle","The sender’s MAC address, so nobody has to ask for it.":"Die MAC-Adresse des Absenders, damit niemand danach fragen muss.","Every device on this network.":"Jedes Gerät in diesem Netz.","The hop limit devices here should put on their packets.":"Das Hop-Limit, das Geräte hier in ihre Pakete schreiben sollen.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: Adressen von DHCPv6 beziehen. O: andere Einstellungen von DHCPv6 beziehen. Beide aus: Diese Ankündigung enthält alles.","Router lifetime":"Router-Lebensdauer","How long the laptop may use this router as its way out.":"Wie lange der Laptop diesen Router als Weg nach draußen nutzen darf.","Reachable time":"Erreichbarkeitszeit","0 (not set)":"0 (nicht gesetzt)","Retransmit timer":"Wiederholungs-Timer","The largest packet this network carries.":"Das größte Paket, das dieses Netz transportiert.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, gültig 86,400 s, bevorzugt 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Flags L und A: Adressen in diesem Präfix liegen in diesem Netz, und Geräte dürfen ihre eigene bilden (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, für 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Rekursiver DNS-Server: welcher Resolver gefragt wird, sodass auch dafür kein DHCP nötig ist.","Whose MAC address is wanted.":"Wessen MAC-Adresse gesucht wird.","The device this frame is for.":"Das Gerät, für das dieser Frame bestimmt ist.","0x60000000: solicited, override":"0x60000000: angefordert, überschreiben","Solicited: this answers a question. Override: replace any older entry for this address.":"Angefordert: Das beantwortet eine Frage. Überschreiben: Ältere Einträge für diese Adresse ersetzen.","Target link-layer address":"Link-Layer-Adresse des Ziels","The answer: the MAC address that goes with the target.":"Die Antwort: die MAC-Adresse, die zum Ziel gehört.","Setting the Clock":"Die Uhr stellen","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Computeruhren driften um Sekunden pro Woche, und vieles hängt von ihnen ab: Zertifikate haben Daten, Anmeldungen und Zahlungen laufen ab, Logs verschiedener Rechner müssen zusammenpassen. NTP stellt eine Uhr nach einem Zeitserver im Internet. Eine kleine Anfrage und ihre Antwort tragen vier Zeitstempel – genug, um zu berechnen, wie weit die Uhr danebenliegt und wie lange das Netz gebraucht hat.",Accuracy:"Genauigkeit","A few milliseconds online":"Wenige Millisekunden übers Internet","Clock set":"Uhr gestellt","Four timestamps, one answer":"Vier Zeitstempel, eine Antwort","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Eine Anfrage und eine Antwort ergaben vier Zeitstempel. Daraus berechnete der Laptop, dass seine Uhr 0.25 s nachging und das Netz hin und zurück 24 ms brauchte, und begann, seine Uhr sanft anzugleichen. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Offset:"Abweichung","250.0 ms (slow)":"250.0 ms (nach)","Stratum 2":"Stratum 2","Next check":"Nächste Prüfung","Minutes to days later":"Minuten bis Tage später","Clocks Drift":"Uhren driften","The laptop’s clock is a little slow":"Die Uhr des Laptops geht etwas nach","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Ein Computer misst die Zeit mit einem Quarzkristall, der etwas zu schnell oder zu langsam läuft, also driften Uhren um Sekunden pro Woche auseinander. Die Uhr dieses Laptops geht eine Viertelsekunde nach. Windows stellt sie nach time.windows.com, dessen Adresse es schon per DNS nachgeschlagen hat.","Laptop clock":"Laptop-Uhr","0.25 s slow":"0.25 s nach","Time server":"Zeitserver","Why it matters":"Warum es zählt","Certificates, logins, logs":"Zertifikate, Anmeldungen, Logs","CLOCK 0.250 s SLOW":"UHR GEHT 0.250 s NACH","Ask for the Time":"Nach der Zeit fragen","T1: when the request leaves":"T1: wann die Anfrage losgeht","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"Der Laptop schickt eine 48-Byte-Anfrage an Port 123. Er trägt die Zeit seiner eigenen Uhr ein, zu der die Anfrage losgeht: T1, 09:40:59.750. Alles andere bleibt leer.","T1 (laptop)":"T1 (Laptop)",Mode:"Modus","3 (client)":"3 (Client)","The Answer":"Die Antwort","T2 and T3 from the server, T4 on arrival":"T2 und T3 vom Server, T4 bei Ankunft","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"Der Server kopiert T1 zurück und fügt T2 hinzu, wann die Anfrage ankam, und T3, wann seine Antwort losgeht, beide nach seiner eigenen genauen Uhr. Wenn die Antwort ankommt, notiert der Laptop T4 nach seiner eigenen Uhr. Der Server hat Stratum 2: Er stellt seine Uhr nach einem Stratum-1-Server, der einen GPS-Empfänger oder eine Atomuhr hat.","T4 (laptop)":"T4 (Laptop)",Stratum:"Stratum","The Offset":"Die Abweichung","Four times, two answers":"Vier Zeiten, zwei Antworten","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"Die Zeit im Netz, hin und zurück, ist (T4 − T1) − (T3 − T2) = 24.0 ms. Die Abweichung setzt voraus, dass der Weg in jede Richtung gleich lange dauert: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. Die Uhr des Laptops geht eine Viertelsekunde nach. Ein ungleicher Weg (in eine Richtung langsamer als in die andere) würde das Ergebnis um bis zur Hälfte des Unterschieds verfälschen.",Assumes:"Setzt voraus","Equal time each way":"Gleiche Zeit in jede Richtung","OFFSET +250.0 ms":"ABWEICHUNG +250.0 ms","Ease It In":"Sanft angleichen","No jumps backwards":"Keine Sprünge zurück","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Ein kleiner Fehler wird nicht mit einem Sprung behoben: Die Uhr läuft etwas schneller, bis sie aufgeholt hat, damit die Zeit für laufende Programme nie stehen bleibt oder rückwärts läuft. Nur ein großer Fehler wird sofort gestellt. Je ruhiger eine Uhr läuft, desto seltener fragt ein NTP-Client, von alle 64 Sekunden bis etwa alle 17 Minuten; Windows fragt time.windows.com von sich aus viel seltener, alle paar Stunden oder seltener.","Small offsets":"Kleine Abweichungen","Eased in gradually":"Sanft angeglichen","Large offsets":"Große Abweichungen","Set at once":"Sofort gestellt","Asks again":"Fragt erneut","Less often as it settles":"Seltener, je ruhiger sie läuft","CLOCK IN STEP":"UHR GEHT RICHTIG","Leap, version, mode":"Leap, Version, Modus","Mode 3: a client asking for the time.":"Modus 3: ein Client, der nach der Zeit fragt.",Poll:"Abfrageintervall","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"Wie oft der Client fragen will (2 hoch 6 Sekunden). Es wächst, je ruhiger die Uhr läuft.",Precision:"Präzision","How finely this clock can be read.":"Wie fein diese Uhr ablesbar ist.","Root delay":"Root Delay","Root dispersion":"Root Dispersion","Reference ID":"Referenz-ID","Reference time":"Referenzzeit","Origin time":"Ursprungszeit","Receive time":"Empfangszeit","Transmit time":"Sendezeit","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: wann die Anfrage losging, nach der eigenen (falschen) Uhr des Laptops.","Mode 4: an answer from a server.":"Modus 4: eine Antwort von einem Server.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"Zwei Stufen von einer Referenzuhr entfernt: Er folgt einem Stratum-1-Server, der ein eigenes GPS oder eine Atomuhr hat.","Round-trip time from this server to the reference clock.":"Umlaufzeit von diesem Server zur Referenzuhr.","How far off this server could be, at most.":"Wie weit dieser Server höchstens danebenliegen könnte.","192.0.2.123 (its own time source)":"192.0.2.123 (seine eigene Zeitquelle)","When this server last set its own clock.":"Wann dieser Server seine eigene Uhr zuletzt gestellt hat.","T1, copied from the request: the client can match the answer to its question.":"T1, aus der Anfrage kopiert: Der Client kann die Antwort seiner Frage zuordnen.","T2: when the request arrived, by the server’s clock.":"T2: wann die Anfrage ankam, nach der Uhr des Servers.","T3: when this answer left.":"T3: wann diese Antwort losging.",Private:"Privat","Plain DNS":"Unverschlüsseltes DNS","DNS inside HTTPS":"DNS in HTTPS","DNS queries inside HTTPS":"DNS-Anfragen in HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"Gewöhnliches DNS reist im Klartext: Jeder im selben WLAN und dein Internetanbieter kann jeden Namen lesen, den du nachschlägst, und sogar die Antworten ändern. DNS over HTTPS (DoH) schickt dieselben DNS-Nachrichten in einer verschlüsselten HTTPS-Verbindung zum Resolver, sodass sie unterwegs wie beliebiger Webverkehr aussehen. Browser und Betriebssysteme können es einschalten.","Ordinary DNS messages":"Gewöhnliche DNS-Nachrichten",Hides:"Verbirgt","Which names you look up":"Welche Namen du nachschlägst",Similar:"Ähnlich","DNS over TLS (port 853)":"DNS over TLS (Port 853)","Looked up in private":"Privat nachgeschlagen","Same question, sealed":"Dieselbe Frage, versiegelt","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"Die unverschlüsselte Abfrage konnte jeder auf dem Weg lesen. Über HTTPS steckte dieselbe DNS-Nachricht versiegelt in TLS, lesbar nur für den Resolver. Der Resolver sieht weiterhin jede Frage, also wandert das Vertrauen zu ihm, und die Website, die du danach besuchst, ist an ihrer Adresse weiterhin erkennbar. Drücke NOCHMAL, um es dir noch einmal anzusehen.","On the way":"Unterwegs","Only “HTTPS to dns.google”":"Nur „HTTPS zu dns.google“","The resolver":"Der Resolver","Still sees every name":"Sieht weiterhin jeden Namen","The site’s address you then visit":"Die Adresse der Website, die du danach besuchst","Can’t be changed on the way":"Unterwegs nicht veränderbar","Readable by anyone on the way":"Für jeden auf dem Weg lesbar","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"Das ist die Abfrage aus den anderen Lektionen: ein UDP-Paket an Port 53, das nach www.example.com fragt, und die Antwort. Keines davon ist verschlüsselt, also können alle im WLAN des Cafés und der Internetanbieter sehen, welche Namen der Laptop nachschlägt, und sogar mit einer falschen Adresse antworten.","UDP port 53":"UDP-Port 53","Can be changed":"Veränderbar","Yes, on the way":"Ja, unterwegs",readable:"lesbar","ANYONE HERE CAN READ IT":"JEDER HIER KANN ES LESEN","An HTTPS Link":"Eine HTTPS-Verbindung","TCP and TLS to dns.google":"TCP und TLS zu dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Mit DNS over HTTPS öffnet der Browser stattdessen eine HTTPS-Verbindung zum Resolver: TCP zu Port 443 und ein TLS-Handshake für dns.google. Er hält diese Verbindung offen und schickt jede Abfrage darüber.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, wie jede Website","Kept open":"Bleibt offen","For every lookup":"Für jede Abfrage","Sealed Question":"Versiegelte Frage","A DNS message in an HTTP request":"Eine DNS-Nachricht in einer HTTP-Anfrage","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"Die Frage ist dieselbe DNS-Nachricht wie zuvor. Sie geht in einer HTTP/2-Anfrage, GET /dns-query?dns= gefolgt von der Nachricht in base64url, und bittet um eine Antwort vom Typ application/dns-message. In TLS kann niemand unterwegs sie lesen.",Format:"Format","application/dns-message":"application/dns-message","Encrypted (TLS)":"Verschlüsselt (TLS)","DoH QUERY":"DoH-ANFRAGE","inside: GET /dns-query?dns=…":"innen: GET /dns-query?dns=…","Sealed Answer":"Versiegelte Antwort","The DNS answer in an HTTP response":"Die DNS-Antwort in einer HTTP-Antwort","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"Der Resolver antwortet 200 mit einem Body vom Typ application/dns-message: dieselbe DNS-Antwort wie bei der unverschlüsselten Abfrage, A 203.0.113.10. Weil sie über TLS von dns.google kommt, konnte niemand unterwegs sie verändern.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"Die DNS-Antwort (49 Bytes)",Tampering:"Manipulation","Impossible on the way":"Unterwegs unmöglich","DoH ANSWER":"DoH-ANTWORT","inside: A 203.0.113.10":"innen: A 203.0.113.10","What Still Shows":"Was noch sichtbar ist","Hidden on the way, not from the resolver":"Unterwegs verborgen, nicht vor dem Resolver","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"Unterwegs sehen die Abfragen jetzt aus wie beliebiger HTTPS-Verkehr zu dns.google. Aber der Resolver selbst liest jede Frage, also vertraust du ihm statt dem Betreiber deines Netzes. Und die Website, die du danach besuchst, ist weiterhin an ihrer IP-Adresse erkennbar, und an ihrem Namen im TLS-Client-Hello, sofern sie kein Encrypted Client Hello unterstützt. DNS over TLS erledigt dieselbe Aufgabe auf Port 853.","Sees every name":"Sieht jeden Namen","Then visible":"Danach sichtbar","The site’s IP, maybe its name":"Die IP der Website, vielleicht ihr Name",Alternative:"Alternative","TRUST MOVES TO THE RESOLVER":"DAS VERTRAUEN WANDERT ZUM RESOLVER","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: DNS-Anfrage)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: DNS-Antwort)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: die Verbindungseinleitung und Einstellungen, dann die Anfrage","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: Einstellungen, die Antwort-Header, dann die DNS-Antwort","Signed Answers":"Signierte Antworten","Question and answer":"Frage und Antwort","To the name servers":"Zu den Nameservern","Signed answers":"Signierte Antworten","DNS Security Extensions":"DNS Security Extensions","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Gewöhnliche DNS-Antworten lassen sich fälschen: Wer zuerst antwortet oder in der Mitte sitzt, kann eine falsche Adresse schicken. DNSSEC lässt einen Resolver prüfen, ob eine Antwort wirklich vom Eigentümer der Domain stammt. Jede Gruppe von Einträgen ist signiert; den Schlüssel jeder Zone bestätigt ihre Elternzone, bis hinauf zur Root, deren Schlüssel in die Resolver eingebaut ist. DNSSEC beweist, dass Antworten echt sind; es verbirgt sie nicht.","Adds records":"Fügt Einträge hinzu","Checked by":"Geprüft von","Trust anchor":"Vertrauensanker","The root’s key (built in)":"Der Schlüssel der Root (eingebaut)","Hides queries":"Verbirgt Anfragen","No (that’s DoH)":"Nein (das macht DoH)","Answer checked":"Antwort geprüft","A chain of signatures to the root":"Eine Kette von Signaturen bis zur Root","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"Der Resolver folgte einer Kette: Die Adresse war mit dem Schlüssel von example.com signiert, dieser Schlüssel mit seinem Key-Signing-Key, den .com mit einem signierten DS-Eintrag bestätigt hat, und den Schlüssel von .com bestätigt die Root, deren Schlüssel im Resolver eingebaut ist. Eine gefälschte Antwort hätte die Kette unterbrochen. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Signatures checked":"Geprüfte Signaturen","3 here (plus cached ones)":"3 hier (plus zwischengespeicherte)","The AD flag":"Das AD-Flag","Forged answer":"Gefälschte Antwort","Fails the check":"Fällt bei der Prüfung durch","Ask as Usual":"Fragen wie immer","The laptop’s question doesn’t change":"Die Frage des Laptops ändert sich nicht","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"Der Laptop fragt seinen Resolver wie immer nach www.example.com. Geprüft wird beim Resolver, der die Nameserver mit gesetztem DNSSEC-OK-Flag fragt: Schickt die Signaturen mit.","Checking done by":"Geprüft von","The resolver (8.8.8.8)":"Dem Resolver (8.8.8.8)","Resolver sets":"Resolver setzt","Signed Answer":"Signierte Antwort","An RRSIG comes with the A record":"Ein RRSIG kommt mit dem A-Eintrag","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"Der Resolver kennt den Nameserver von example.com schon aus früheren Abfragen. Dieser Server schickt die Adresse mit einem RRSIG-Eintrag: einer Signatur über den A-Eintrag, erstellt mit dem privaten Schlüssel der Zone. Das RRSIG sagt, welcher Schlüssel signiert hat (Schlüssel 47362, der Zone-Signing-Key) und wann die Signatur abläuft. Um sie zu prüfen, braucht der Resolver diesen Schlüssel.","RRSIG by key 47362":"RRSIG von Schlüssel 47362",Valid:"Gültig","31 Oct to 21 Nov 2026":"31. Okt. bis 21. Nov. 2026","signed by key 47362":"signiert von Schlüssel 47362","The Zone’s Keys":"Die Schlüssel der Zone","DNSKEY records, signed too":"DNSKEY-Einträge, ebenfalls signiert","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"Der Resolver fragt nach den Schlüsseln von example.com. Es sind zwei: der Zone-Signing-Key (Flags 256), der den A-Eintrag signiert hat, und der Key-Signing-Key (Flags 257), der nur die Schlüsselgruppe signiert. Damit prüft der Resolver beide Signaturen. Aber wer sagt, dass diese Schlüssel zu example.com gehören?","47362, zone-signing (256)":"47362, Zone-Signing (256)","61845, key-signing (257)":"61845, Key-Signing (257)","Keys signed by":"Schlüssel signiert von","The key-signing key":"Dem Key-Signing-Key","two keys":"zwei Schlüssel","signed by key 61845":"signiert von Schlüssel 61845","Vouched by .com":"Bestätigt von .com","The parent’s DS record":"Der DS-Eintrag der Elternzone","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"Das beantwortet die Elternzone. Die .com-Server halten einen DS-Eintrag für example.com: einen Hash seines Key-Signing-Keys, signiert mit dem eigenen Schlüssel von .com. Passt der Hash zu Schlüssel 61845, gehören die Schlüssel zu example.com, soweit es .com betrifft.","Hash of key 61845":"Hash von Schlüssel 61845","Signed by":"Signiert von",".com (key 19718)":".com (Schlüssel 19718)",Matches:"Passt zu","hash of key 61845":"Hash von Schlüssel 61845","signed by .com":"signiert von .com","Up to the Root":"Bis zur Root","Where the chain ends":"Wo die Kette endet","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Darüber geht es genauso weiter: Die Schlüssel von .com bestätigt ein DS-Eintrag in der Root-Zone, signiert mit dem Schlüssel der Root, und dieser Schlüssel ist in jeden validierenden Resolver eingebaut: der Vertrauensanker. Der Resolver hatte diese Glieder zwischengespeichert, also ist die Kette vollständig: Root → .com → example.com → die Adresse.",".com’s key":"Schlüssel von .com","Vouched for by the root":"Von der Root bestätigt","Root’s key":"Schlüssel der Root","Built in (trust anchor)":"Eingebaut (Vertrauensanker)","Root → .com → example.com":"Root → .com → example.com","CHAIN OF TRUST CHECKED":"VERTRAUENSKETTE GEPRÜFT","A Checked Answer":"Eine geprüfte Antwort","With the AD flag":"Mit dem AD-Flag","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"Der Resolver antwortet dem Laptop mit der Adresse und dem AD-Flag: authentifizierte Daten. Wäre eine Signatur gescheitert, hätte der Laptop einen Fehler (SERVFAIL) statt einer gefälschten Adresse bekommen. DNSSEC verbirgt weder Frage noch Antwort; dafür gibt es DNS over HTTPS.",Flag:"Flag","AD (authenticated data)":"AD (authentifizierte Daten)","Bad signature":"Ungültige Signatur","SERVFAIL, no address":"SERVFAIL, keine Adresse","AD: checked":"AD: geprüft","UDP size 1232, DNSSEC OK = 1":"UDP-Größe 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Sagt, wie groß eine UDP-Antwort sein darf, und DNSSEC OK: Schickt die Signaturen mit.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, signiert von example.com-Schlüssel 47362, gültig 2026-10-31 bis 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Eine Signatur über die Einträge darüber, erstellt mit dem privaten Schlüssel der Zone.","example.com, type DNSKEY, class IN":"example.com, Typ DNSKEY, Klasse IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (Zone-Signing-Key 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"Einer der öffentlichen Schlüssel der Zone; wer eine Signatur prüft, braucht ihn.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (Key-Signing-Key 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, signiert von example.com-Schlüssel 61845, gültig 2026-10-31 bis 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, Typ DS, Klasse IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS Schlüssel 61845, SHA-256-Digest (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Ein Hash des Key-Signing-Keys der Kindzone, aufbewahrt und signiert von der Elternzone.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, signiert von com-Schlüssel 19718, gültig 2026-10-31 bis 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: Antwort, RD (Rekursion gewünscht), RA (Rekursion verfügbar), AD (authentifizierte Daten)","Wi-Fi Logins":"WLAN-Anmeldung","EAP over Wi-Fi":"EAP über WLAN","RADIUS Server":"RADIUS-Server","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS und 802.1X (Enterprise-WLAN)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"Zu Hause teilen sich alle ein WLAN-Passwort. Büros, Universitäten und eduroam nutzen stattdessen WPA2- oder WPA3-Enterprise: Jede Person oder jedes Gerät meldet sich mit eigenem Konto oder Zertifikat an, geprüft von einem RADIUS-Server. Der Access Point kennt keine Passwörter. Er reicht die Anmeldung, eine Folge von EAP-Nachrichten, zwischen Laptop und Server weiter und lässt den Laptop erst hinein, wenn der Server Ja sagt.","EAP (here EAP-TLS)":"EAP (hier EAP-TLS)",Keys:"Schlüssel","Different for every login":"Bei jeder Anmeldung andere","Let in":"Eingelassen","Its own login, its own keys":"Eigene Anmeldung, eigene Schlüssel","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"Der Laptop hat mit seinem Zertifikat bewiesen, wer er ist. Der RADIUS-Server hat es geprüft und dem Access Point gesagt, ihn hereinzulassen, ins VLAN 20, mit einem Schlüssel nur für diese Anmeldung. Der Access Point hat nie ein Passwort gesehen: Er hat nur die Nachrichten weitergereicht. Drücke NOCHMAL, um es dir noch einmal anzusehen.","EAP-TLS (certificates)":"EAP-TLS (Zertifikate)","17, then the 4-way handshake":"17, dann der 4-Wege-Handshake","20 (staff)":"20 (Personal)","A user leaves":"Jemand geht","Disable one account":"Ein Konto sperren","Who Are You?":"Wer bist du?","The access point asks for an identity":"Der Access Point fragt nach einer Identität","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"Der Laptop ist „Office“ beigetreten, einem WPA2-Enterprise-Netz, aber bis er angemeldet ist, lässt der Access Point nur Anmeldenachrichten durch. Er fragt mit einer EAP-Identity-Anfrage, wer der Laptop ist, und der Laptop antwortet alex@example.org. Der Access Point kennt keine Konten: Er reicht die Antwort an den RADIUS-Server weiter.","Before login":"Vor der Anmeldung","Only EAP gets through":"Nur EAP kommt durch","IDENTITY?":"IDENTITÄT?","EAP Identity request":"EAP-Identity-Anfrage",IDENTITY:"IDENTITÄT","Ask RADIUS":"RADIUS fragen","The login goes to the server":"Die Anmeldung geht zum Server","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"Der Access Point kopiert die EAP-Nachricht in einen RADIUS-Access-Request und schickt ihn auf UDP-Port 1812 an den RADIUS-Server, mit der MAC-Adresse des Laptops und dem Namen des Netzes. Ein Geheimnis, das nur die beiden teilen, schützt jedes Paket. Der Server antwortet mit einer Access-Challenge: der nächsten Nachricht für den Laptop, nämlich „EAP-TLS starten“.","RADIUS server, UDP 1812":"RADIUS-Server, UDP 1812","A shared secret":"Ein gemeinsames Geheimnis","from the access point":"vom Access Point","EAP-TLS start":"EAP-TLS-Start","TLS START":"TLS-START","TLS Inside EAP":"TLS in EAP","The server proves who it is":"Der Server beweist, wer er ist","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"Laptop und Server führen jetzt einen TLS-1.3-Handshake in EAP aus; der Access Point verpackt jede Nachricht um, EAPOL über Funk und RADIUS übers Kabel. Der Server schickt sein Zertifikat und verlangt das des Laptops. Der Laptop prüft, dass es von der firmeneigenen Zertifizierungsstelle für radius.example.org ausgestellt wurde. Diese Prüfung verhindert, dass ein gefälschter Access Point die Anmeldung abfängt.","TLS 1.3, inside EAP":"TLS 1.3, in EAP","Its certificate":"Sein Zertifikat","Laptop checks":"Laptop prüft","Issuer and name":"Aussteller und Name","TLS inside EAP":"TLS in EAP","certificate (encrypted)":"Zertifikat (verschlüsselt)","Laptop’s Proof":"Der Nachweis des Laptops","Its own certificate":"Sein eigenes Zertifikat","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"Der Laptop antwortet mit seinem eigenen Zertifikat, das die Firma für diesen Benutzer ausgestellt hat, und einer Signatur mit seinem privaten Schlüssel; der Schlüssel verlässt den Laptop nie. Ein Passwort ist nicht im Spiel. Der Server prüft Zertifikat und Signatur und schlägt das Konto nach. Viele Netze, darunter eduroam, nutzen stattdessen ein Passwort, das im TLS-Tunnel geschickt wird (PEAP oder EAP-TTLS).","Its certificate, a signature":"Sein Zertifikat, eine Signatur","None with EAP-TLS":"Keins bei EAP-TLS","Or instead":"Oder stattdessen","PEAP: a password in TLS":"PEAP: ein Passwort in TLS",CERTIFICATE:"ZERTIFIKAT","laptop’s certificate":"Zertifikat des Laptops","Handshake Done":"Handshake fertig","Nothing more to send":"Nichts mehr zu senden","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Mit TLS 1.3 schickt der Server dann eine winzige verschlüsselte Nachricht, ein einziges Nullbyte, um zu sagen, dass der Handshake vorbei ist, und der Laptop antwortet mit einer leeren EAP-Nachricht. Beide Enden haben jetzt dieselben 64 Bytes Schlüsselmaterial, berechnet während des Handshakes. Niemand unterwegs hat es gesehen, nicht einmal der Access Point.","Server sends":"Server schickt","One encrypted 0 byte":"Ein verschlüsseltes Nullbyte","An empty EAP-TLS reply":"Eine leere EAP-TLS-Antwort","Both hold":"Beide haben","64 bytes of key material":"64 Bytes Schlüsselmaterial","handshake over":"Handshake vorbei","one encrypted byte":"ein verschlüsseltes Byte",EMPTY:"LEER","nothing more":"nichts weiter","empty EAP-TLS":"leeres EAP-TLS","And a key for the access point":"Und ein Schlüssel für den Access Point","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"Der Server antwortet mit Access-Accept. Darin stecken EAP Success für den Laptop; die ersten 32 Bytes des Schlüsselmaterials für den Access Point, verschlüsselt mit dem gemeinsamen Geheimnis (MS-MPPE-Recv-Key); und VLAN 20, damit dieser Benutzer im Personalnetz landet. Derselbe Access Point könnte einen anderen Benutzer in ein anderes VLAN stecken.","AP gets":"AP bekommt","The key (MS-MPPE-Recv-Key)":"Den Schlüssel (MS-MPPE-Recv-Key)","key, VLAN 20":"Schlüssel, VLAN 20","4-Way Handshake":"4-Wege-Handshake","As at home, from a different key":"Wie zu Hause, aus einem anderen Schlüssel","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Access Point und Laptop haben jetzt denselben 32-Byte-Schlüssel, den PMK. Was folgt, ist der 4-Wege-Handshake aus der WLAN-Lektion; nur die Herkunft des PMK ist anders. Zu Hause stammt er aus dem gemeinsamen Passwort, hier aus genau dieser Anmeldung, also bekommt jeder Benutzer andere Schlüssel.","PMK from":"PMK aus","This login":"Dieser Anmeldung","At home":"Zu Hause","From the shared password":"Aus dem gemeinsamen Passwort","Encrypted data (CCMP)":"Verschlüsselte Daten (CCMP)","group key, MIC":"Gruppenschlüssel, MIC","Why Enterprise":"Warum Enterprise","One account per person":"Ein Konto pro Person","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Wenn jemand geht, wird sein Konto gesperrt, und niemand sonst muss ein Passwort ändern. Jede Anmeldung bekommt eigene Schlüssel, also können Benutzer den Verkehr der anderen nicht lesen, und der RADIUS-Server protokolliert, wer sich wann verbunden hat. eduroam funktioniert genauso: Die Anmeldung eines Gasts als user@their-university wird von RADIUS-Server zu RADIUS-Server weitergereicht, bis sie seine eigene Universität erreicht.","Different for every user":"Für jeden Benutzer andere",eduroam:"eduroam","Login passed home":"Anmeldung geht nach Hause","ONE ACCOUNT PER PERSON":"EIN KONTO PRO PERSON","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, Zertifikat","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, verschlüsselter Handshake","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: verschlüsselter Handshake","Access-Request id=83: encrypted handshake":"Access-Request id=83: verschlüsselter Handshake","0 (EAP packet)":"0 (EAP-Paket)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Trägt eine EAP-Nachricht. Der Access Point kopiert sie für den Server in ein RADIUS-Paket und zurück.","A response carries the same number as the request it answers.":"Eine Antwort trägt dieselbe Nummer wie die Anfrage, auf die sie antwortet.","Who are you?":"Wer bist du?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Wer sich anmeldet. Der Realm nach dem @ sagt dem RADIUS-Server (oder den Servern, die Anfragen weiterreichen), wo das Konto liegt.","Seen on the office network":"Im Büronetz gesehen","The server. It is on the same network, so the frame goes straight to it, not through the router.":"Der Server. Er ist im selben Netz, also geht der Frame direkt zu ihm, nicht über den Router.","The access point’s wired port.":"Der kabelgebundene Port des Access Points.","Should this device be let in?":"Soll dieses Gerät hinein?","A reply carries the number of the request it answers.":"Eine Antwort trägt die Nummer der Anfrage, auf die sie antwortet.",Authenticator:"Authenticator","Random, new in every request.":"Zufällig, in jeder Anfrage neu.",Attributes:"Attribute","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"Ein HMAC-MD5 über das ganze Paket, mit dem gemeinsamen Geheimnis als Schlüssel. Jedes Paket mit EAP muss eins haben; seit dem Blast-RADIUS-Angriff von 2024 kommt es zuerst.","The identity the laptop gave.":"Die Identität, die der Laptop angegeben hat.","The access point asking.":"Der fragende Access Point.","The access point’s MAC address and the network’s name.":"Die MAC-Adresse des Access Points und der Name des Netzes.","The laptop’s MAC address.":"Die MAC-Adresse des Laptops.","Keep each EAP message small enough for one frame.":"Jede EAP-Nachricht klein genug für einen Frame halten.","The EAP packet, passed on unchanged.":"Das EAP-Paket, unverändert weitergereicht.","The server’s network card.":"Die Netzwerkkarte des Servers.","Not yet: here is the next message for the device.":"Noch nicht: Hier ist die nächste Nachricht für das Gerät.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Ein Hash über diese Antwort, den Authenticator der Anfrage und das gemeinsame Geheimnis: Nur der echte Server kann ihn erzeugt haben.","A TLS handshake, carried inside EAP.":"Ein TLS-Handshake, in EAP getragen.","0x20 (start)":"0x20 (Start)","Start: the server is ready for the laptop’s Client Hello.":"Start: Der Server ist bereit für das Client Hello des Laptops.","The server’s bookmark for this login: the access point sends it back with the next request.":"Das Lesezeichen des Servers für diese Anmeldung: Der Access Point schickt es mit der nächsten Anfrage zurück.","0x80 (length included)":"0x80 (mit Länge)","TLS length":"TLS-Länge","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"Längere TLS-Nachrichten werden in Stücke von etwa 1,000 Bytes geteilt, jedes einzeln bestätigt.","TLS records":"TLS-Records","The same TLS records as over TCP, only carried in EAP.":"Dieselben TLS-Records wie über TCP, nur in EAP getragen.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, der Schlüsselanteil des Laptops","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Das EAP-Paket (1,008 Bytes), aufgeteilt auf 4 Attribute von bis zu 253 Bytes.","EAP-Message, continued":"EAP-Message, Fortsetzung","TLS records, continued":"TLS-Records, Fortsetzung","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, der Schlüsselanteil des Servers","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Verschlüsselt: Zertifikat für radius.example.org, eine Anforderung des Laptop-Zertifikats, Signatur, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Verschlüsselt: das Zertifikat des Laptops (für alex@example.org), seine Signatur, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Das EAP-Paket (822 Bytes), aufgeteilt auf 4 Attribute von bis zu 253 Bytes.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Verschlüsselt: ein Nullbyte, die „Commitment Message“: keine weiteren Handshake-Nachrichten","0x00 (no data)":"0x00 (keine Daten)","Nothing to send: an empty answer that keeps the conversation going.":"Nichts zu senden: eine leere Antwort, die das Gespräch am Laufen hält.","Yes: let it in.":"Ja: hereinlassen.","Put this device on VLAN 20, the staff network.":"Dieses Gerät ins VLAN 20 stecken, das Personalnetz.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"Die ersten 32 Bytes des Schlüsselmaterials, das beide Enden des TLS-Handshakes berechnet haben. Der Access Point nutzt sie als PMK, den Ausgangsschlüssel für den 4-Wege-Handshake.","Salt, encrypted key":"Salt, verschlüsselter Schlüssel","Encrypted with the shared secret, so only the access point can read the key.":"Mit dem gemeinsamen Geheimnis verschlüsselt, damit nur der Access Point den Schlüssel lesen kann.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"Die nächsten 32 Bytes des Schlüsselmaterials. WLAN braucht sie nicht.","The RADIUS server accepted the login.":"Der RADIUS-Server hat die Anmeldung akzeptiert.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (Anmeldungen, die ein RADIUS-Server prüft)","Shared Folders":"Freigegebene Ordner",Responses:"Antworten","nas (File Server)":"nas (Dateiserver)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"Mit SMB teilt Windows Dateien und Drucker: \\\\server\\share im Datei-Explorer, ein verbundenes Netzlaufwerk, ein NAS zu Hause. macOS und Linux sprechen es auch. Über eine einzige TCP-Verbindung zu Port 445 einigt sich der Client auf eine Version, meldet sich an und verbindet sich mit einer Freigabe; dann öffnet, liest, schreibt und schließt er Dateien mit nummerierten Anfragen.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM oder Kerberos",Protection:"Schutz","Signing, optional encryption":"Signatur, optionale Verschlüsselung","File read":"Datei gelesen","Seven requests, one connection":"Sieben Anfragen, eine Verbindung","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Über eine einzige TCP-Verbindung einigte sich der Laptop auf SMB 3.1.1, meldete sich per NTLM an, ohne sein Passwort zu schicken, verband sich mit der Freigabe und las eine 240-KB-Datei mit einer einzigen Anfrage. Jede Nachricht nach der Anmeldung war signiert. Drücke NOCHMAL, um es dir noch einmal anzusehen.","7 on one connection":"7 über eine Verbindung","NTLMv2, no password sent":"NTLMv2, kein Passwort gesendet","240 KB in 169 segments":"240 KB in 169 Segmenten",Signed:"Signiert","Every message after login":"Jede Nachricht nach der Anmeldung","Port 445":"Port 445","A TCP connection to the NAS":"Eine TCP-Verbindung zum NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"Der Laptop öffnet \\\\nas\\Documents, einen freigegebenen Ordner auf dem NAS. Er findet die Adresse von nas per lokaler Namensauflösung und öffnet eine TCP-Verbindung zu Port 445. Die Pakete laufen über den Heimrouter zum NAS und verlassen das Heimnetz nie.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Bleibt","On the home network":"Im Heimnetz",Negotiate:"Aushandeln","Agree on a version":"Auf eine Version einigen","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"Der Laptop listet jede SMB-Version auf, die er spricht, von 2.0.2 bis 3.1.1, und sagt, dass er Signaturen verlangt. Das NAS wählt 3.1.1, die neueste. Beide Seiten führen einen SHA-512-Hash über alles, was ab hier bis zum Ende der Anmeldung ausgetauscht wird. Er fließt in die Schlüssel ein, sodass die Anmeldung scheitern würde, wenn jemand diese Nachrichten unterwegs veränderte, etwa um eine ältere Version zu erzwingen.",Chosen:"Gewählt","Tamper check":"Manipulationsschutz","SHA-512 of the exchange":"SHA-512 des Austauschs","signing required":"Signatur erforderlich","NTLM Challenge":"NTLM-Challenge","The NAS sends a random number":"Das NAS schickt eine Zufallszahl","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"Ein NAS zu Hause hat keine Domäne, also gibt es kein Kerberos: Der Laptop meldet sich per NTLM an. Sein erstes SESSION_SETUP sagt, dass er sich anmelden will, und das NAS antwortet „weitere Verarbeitung nötig“ mit einer Challenge aus 8 Zufallsbytes. Außerdem gibt es dieser Anmeldung eine Session-ID.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (in einer Domäne: Kerberos)",Challenge:"Challenge","More processing required":"Weitere Verarbeitung nötig","NTLM: let me log in":"NTLM: Lass mich rein","a session ID":"eine Session-ID","NTLM Response":"NTLM-Antwort","Proof, not the password":"Ein Nachweis, nicht das Passwort","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"Der Laptop antwortet mit dem Benutzernamen alex und einer NTLMv2-Antwort: einem HMAC über die Challenge und ein paar andere Werte, mit einem Hash des Passworts als Schlüssel. Das NAS hat denselben Hash und berechnet denselben Wert. Das Passwort selbst geht nie über das Netz, und beide Seiten haben jetzt einen Sitzungsschlüssel, mit dem sie Nachrichten signieren.",User:"Benutzer",alex:"alex",Sends:"Schickt","An HMAC of the challenge":"Einen HMAC über die Challenge","Never sent":"Nie gesendet","user alex":"Benutzer alex","NTLMv2 response":"NTLMv2-Antwort","LOGGED IN":"ANGEMELDET",signed:"signiert","Connect a Share":"Eine Freigabe verbinden","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT fragt nach der Freigabe mit ihrem vollen Namen, \\\\nas\\Documents. Die Antwort gibt ihr eine Tree-ID und sagt, was dieser Benutzer dort darf. Ab jetzt ist jede Nachricht signiert: Jede trägt ein Tag über die ganze Nachricht, erstellt mit einem Schlüssel aus der Anmeldung, also würde eine veränderte oder gefälschte Nachricht auffallen.",Share:"Freigabe","Every message":"Jede Nachricht","Signed (AES-GMAC)":"Signiert (AES-GMAC)","tree ID 0x2a51":"Tree-ID 0x2a51","Open the File":"Die Datei öffnen","With CREATE":"Mit CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB öffnet Dateien mit CREATE, das auch neue anlegen kann. Dieses öffnet report.pdf zum Lesen und scheitert, wenn sie nicht existiert. Die Antwort nennt Größe und Daten der Datei und eine Datei-ID, die das Lesen und das Schließen benutzen.",Handle:"Handle","A 16-byte file ID":"Eine 16-Byte-Datei-ID","open to read":"zum Lesen öffnen","file ID":"Datei-ID","Read It":"Lesen","The whole file in one request":"Die ganze Datei in einer Anfrage","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Ein einziges READ fordert die ganze Datei an, 245,760 Bytes ab Offset 0. Es kostet 4 Credits, einen pro 64 KB. Die Antwort besteht aus 80 Bytes Headern und dann der Datei, in 169 TCP-Segmenten. Eine größere Datei wird mit mehreren Anfragen gelesen, viele gleichzeitig unterwegs, soweit die Credits reichen.","245,760 bytes from 0":"245,760 Bytes ab 0",Credits:"Credits","4 (one per 64 KB)":"4 (einer pro 64 KB)","Arrives in":"Kommt an in","from offset 0":"ab Offset 0","Close the File":"Die Datei schließen","And keep 445 at home":"Und Port 445 zu Hause lassen","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE gibt die Datei-ID zurück; die Verbindung bleibt für die nächste Datei offen. SMB 3 kann auch jede Nachricht mit AES-GCM verschlüsseln, für eine Freigabe oder einen ganzen Server. Hier schützt nur die Signatur die Nachrichten, also könnte jeder im Netz die Datei mitlesen. Port 445 sollte nie aus dem Internet erreichbar sein: Der Wurm WannaCry (2017) verbreitete sich über eine Lücke im alten SMB1.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, optional","Switched off: old, unsafe":"Abgeschaltet: alt, unsicher","Never open to the internet":"Nie zum Internet offen",done:"fertig","KEEP PORT 445 OFF THE INTERNET":"PORT 445 NICHT INS INTERNET","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Auf Port 445 beginnt jede SMB-Nachricht mit ihrer Länge, ein Überbleibsel von NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 oder 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'SMB1-Nachrichten begannen mit 0xFF "SMB". SMB1 ist in Windows heute abgeschaltet.',"Header size":"Header-Größe","Credit charge":"Credit-Kosten","Channel sequence":"Kanalsequenz","Credits asked for":"Angeforderte Credits","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"Credits begrenzen, wie viele Anfragen der Laptop gleichzeitig offen haben darf. Der Server teilt sie zu.","Next command":"Nächster Befehl","0 (none chained)":"0 (keiner verkettet)","Counts up with each request; the response carries the same number.":"Zählt mit jeder Anfrage hoch; die Antwort trägt dieselbe Nummer.","0 (no share yet)":"0 (noch keine Freigabe)","Session ID":"Session-ID","0 (not logged in yet)":"0 (noch nicht angemeldet)","zeros (not signed)":"Nullen (nicht signiert)","Structure size":"Strukturgröße","Dialect count":"Anzahl Dialekte","Security mode":"Sicherheitsmodus","0x0002 (signing required)":"0x0002 (Signatur erforderlich)","Recent versions of Windows 11 require signing by default.":"Neuere Versionen von Windows 11 verlangen standardmäßig Signaturen.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, Leases, große Lese- und Schreibvorgänge, Multichannel, persistente Handles, Verzeichnis-Leases, Verschlüsselung.","Client GUID":"Client-GUID","A random ID for this computer.":"Eine zufällige ID für diesen Computer.","Negotiate contexts":"Negotiate-Kontexte","at offset 112, 4 of them":"bei Offset 112, 4 Stück",Dialects:"Dialekte","Every version the laptop speaks. The server picks the newest it also knows.":"Jede Version, die der Laptop spricht. Der Server wählt die neueste, die er auch kennt.",Contexts:"Kontexte","SMB 3.1.1 extras, each in its own small block.":"Extras von SMB 3.1.1, jedes in einem eigenen kleinen Block.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Integrität vor der Authentifizierung: SHA-512 und ein zufälliges 32-Byte-Salt","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Verschlüsselung: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Signatur: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"Der Name des Servers: nas","Credits granted":"Gewährte Credits","0x00000001 (response)":"0x00000001 (Antwort)","0x0001 (signing enabled)":"0x0001 (Signatur aktiviert)",Dialect:"Dialekt","The newest version both sides speak.":"Die neueste Version, die beide Seiten sprechen.","Context count":"Anzahl Kontexte","Server GUID":"Server-GUID","Leases, large reads and writes.":"Leases, große Lese- und Schreibvorgänge.","Largest read, write":"Größtes Lesen, Schreiben","8 MB each":"je 8 MB","The most data one request may carry: transactions, reads and writes.":"Die meisten Daten, die eine Anfrage tragen darf: Transaktionen, Lese- und Schreibvorgänge.","System time":"Systemzeit","7 Nov 2026, 09:41:00":"7. Nov. 2026, 09:41:00","Security buffer":"Sicherheitspuffer","Context offset":"Kontext-Offset","Security blob":"Sicherheits-Blob","GSS-API and SPNEGO wrapping, around NTLMSSP.":"GSS-API- und SPNEGO-Verpackung um NTLMSSP.","The login methods the server accepts: NTLMSSP":"Die Anmeldeverfahren, die der Server akzeptiert: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Integrität vor der Authentifizierung: SHA-512 und das eigene Salt des Servers","Encryption: AES-128-GCM":"Verschlüsselung: AES-128-GCM","Signing: AES-GMAC":"Signatur: AES-GMAC","0x02 (signing required)":"0x02 (Signatur erforderlich)","Previous session":"Vorherige Sitzung","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: die NTLM-Optionen, die der Laptop unterstützt","Not an error: the login needs another round.":"Kein Fehler: Die Anmeldung braucht eine weitere Runde.","The server’s number for this login, from now on in every message.":"Die Nummer des Servers für diese Anmeldung, ab jetzt in jeder Nachricht.","Session flags":"Sitzungs-Flags","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: eine zufällige 8-Byte-Challenge","The NAS’s names and its clock":"Die Namen des NAS und seine Uhrzeit","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: Benutzer alex, Computer ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"NTLMv2-Antwort: ein HMAC über die Challenge, mit einem Hash des Passworts als Schlüssel","A key for signing, encrypted":"Ein Signaturschlüssel, verschlüsselt","0x00000009 (response, signed)":"0x00000009 (Antwort, signiert)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC über die ganze Nachricht, mit einem Schlüssel aus der Anmeldung: Eine veränderte oder gefälschte Nachricht würde auffallen.","The login is complete.":"Die Anmeldung ist abgeschlossen.","0x00000008 (signed)":"0x00000008 (signiert)","Server and share name, in UTF-16.":"Server- und Freigabename, in UTF-16.","The number for this share; later requests carry it.":"Die Nummer dieser Freigabe; spätere Anfragen tragen sie.","Share type":"Freigabetyp","1 (disk)":"1 (Laufwerk)","Share flags":"Freigabe-Flags","Encryption not required for this share; signing still protects every message.":"Für diese Freigabe ist keine Verschlüsselung nötig; die Signatur schützt trotzdem jede Nachricht.","0x001f01ff (full control)":"0x001f01ff (Vollzugriff)","What this user may do in the share.":"Was dieser Benutzer in der Freigabe darf.","Oplock, impersonation":"Oplock, Identitätswechsel","none, 2 (impersonation)":"keins, 2 (Identitätswechsel)","Desired access":"Gewünschter Zugriff","0x00120089 (read)":"0x00120089 (lesen)","Read the data, its attributes and its permissions.":"Die Daten, ihre Attribute und ihre Berechtigungen lesen.","File attributes":"Dateiattribute","Share access":"Freigabezugriff","0x00000001 (read)":"0x00000001 (lesen)","Others may read the file while it is open, but not change it.":"Andere dürfen die Datei lesen, solange sie offen ist, aber nicht ändern.",Disposition:"Disposition","1 (open, fail if missing)":"1 (öffnen, scheitern, wenn sie fehlt)","0x00000040 (a file, not a folder)":"0x00000040 (eine Datei, kein Ordner)",Name:"Name","Create contexts":"Create-Kontexte","File name":"Dateiname","Relative to the share.":"Relativ zur Freigabe.","Oplock, flags":"Oplock, Flags","none, 0":"keins, 0",Action:"Aktion","1 (opened)":"1 (geöffnet)",Times:"Zeiten","created, accessed, written, changed":"erstellt, gelesen, geschrieben, geändert","Windows FILETIME: 100-nanosecond steps since 1601.":"Windows-FILETIME: 100-Nanosekunden-Schritte seit 1601.","Allocation size":"Belegte Größe","File size":"Dateigröße","0x00000020 (archive)":"0x00000020 (Archiv)","File ID":"Datei-ID","The handle for the open file: reads and the close name it.":"Das Handle der offenen Datei: Lesevorgänge und das Schließen nennen es.","A big read costs one credit per 64 KB.":"Ein großes Lesen kostet einen Credit pro 64 KB.","Padding, flags":"Padding, Flags","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Wo der Server die Daten in seiner Antwort ablegen soll: 80 Bytes weit, direkt nach den Headern.","The whole file in one request.":"Die ganze Datei in einer Anfrage.","Minimum, channel, remaining":"Minimum, Kanal, Rest","Channel info":"Kanalinfo","Data offset":"Daten-Offset","Data length":"Datenlänge","Remaining, flags":"Rest, Flags","The file itself; its contents are not part of the lesson.":"Die Datei selbst; ihr Inhalt gehört nicht zur Lektion.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"Der Laptop hat nicht nach den Dateidetails gefragt, also ist der Rest null.","Times, sizes, attributes":"Zeiten, Größen, Attribute","Talking to a PLC":"Mit der SPS reden",Switch:"Switch","Plant network":"Anlagennetz","Modbus/TCP, for industrial control":"Modbus/TCP, für die Industriesteuerung","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus ist eines der ältesten und verbreitetsten Protokolle der Industriesteuerung (OT, Operational Technology): SPSen, Sensoren, Antriebe und Zähler in Fabriken, Wasserwerken und Gebäuden sprechen es. Ein Client liest und schreibt nummerierte Register und Coils auf einem Gerät. Modbus/TCP trägt dieselben kleinen Nachrichten über TCP-Port 502, ohne Anmeldung und ohne Verschlüsselung.","1979, by Modicon":"1979, von Modicon","16-bit registers, on/off coils":"16-Bit-Register, Ein/Aus-Coils","None built in":"Keine eingebaut","Modbus.org specifications":"Spezifikationen von Modbus.org","Pump running":"Pumpe läuft","Simple, and wide open":"Einfach, und weit offen","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"Der Laptop las vier Register, änderte einen Sollwert und startete eine Pumpe, jeweils mit einer 12-Byte-Anfrage und einer kurzen Antwort. Keine Nachricht trug ein Passwort, und keine war verschlüsselt: Modbus vertraut jedem, der es erreichen kann, also muss das Netz darum herum den Schutz übernehmen. Drücke NOCHMAL, um es dir noch einmal anzusehen.","4 requests, 4 answers":"4 Anfragen, 4 Antworten",Biggest:"Größte","17 bytes (the read answer)":"17 Bytes (die Leseantwort)","Protect with":"Schutz durch","Separate networks":"Getrennte Netze","Port 502":"Port 502","A TCP connection to the PLC":"Eine TCP-Verbindung zur SPS","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"Eine SPS (speicherprogrammierbare Steuerung) steuert eine kleine Pumpstation: Sie liest die Sensoren und schaltet die Pumpen. Der Laptop eines Ingenieurs im Anlagennetz spricht mit ihr per Modbus/TCP, also öffnet er eine TCP-Verbindung zu Port 502. In Modbus-Begriffen ist der Laptop der Client und die SPS der Server.",Roles:"Rollen","Client asks, server answers":"Client fragt, Server antwortet","Read Registers":"Register lesen","Function 3: four numbers":"Funktion 3: vier Zahlen","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"Der Laptop fragt mit Funktionscode 3 nach 4 Holding-Registern ab Adresse 0. Die SPS antwortet mit 8 Bytes: vier 16-Bit-Zahlen. Was sie bedeuten (der Füllstand des Tanks in Zentimetern, die Temperatur in Zehntelgrad), steht nur in der Dokumentation der SPS; die Nachricht trägt keine Namen und keine Einheiten. Ein HMI-Bildschirm schickt solche Leseanfragen etwa jede Sekunde.",Function:"Funktion","4 registers from 0":"4 Register ab 0","function 3":"Funktion 3","registers 0–3":"Register 0–3",VALUES:"WERTE","Write a Setpoint":"Einen Sollwert schreiben","Function 6: one register":"Funktion 6: ein Register","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"Der Ingenieur hebt den Füllstand-Sollwert des Tanks von 4.50 m auf 5.00 m: Funktion 6, einzelnes Register schreiben, Register 3, Wert 500. Die SPS antwortet, indem sie die Anfrage wiederholt, was „erledigt“ bedeutet. Ab jetzt hält ihr Programm den Tank voller.","Register 3":"Register 3","The request, repeated":"Die Anfrage, wiederholt",WRITE:"SCHREIBEN","register 3 = 500":"Register 3 = 500","Start a Pump":"Eine Pumpe starten","Function 5: a coil":"Funktion 5: eine Coil","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"Coils sind einzelne Ein/Aus-Ausgänge. Funktion 5 schreibt eine: Coil 0, Pumpe 2, Wert 0xFF00, also ein. Die SPS schaltet die Pumpe ein und gibt die Anfrage zurück. In einer echten Anlage entscheidet das meist das Programm der SPS selbst, mit Sicherheitsverriegelungen.","Coil 0":"Coil 0","Pump 2: on":"Pumpe 2: ein","0xFF00 (off: 0x0000)":"0xFF00 (aus: 0x0000)","COIL ON":"COIL EIN","coil 0: pump 2":"Coil 0: Pumpe 2","pump 2 on":"Pumpe 2 ein","PUMP 2 RUNNING":"PUMPE 2 LÄUFT","An Exception":"Eine Ausnahme","No such register":"Kein solches Register","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Eine Anfrage nach Registern, die es nicht gibt, hier 100 und 101, bekommt eine Ausnahme: den Funktionscode mit gesetztem höchstem Bit (3 + 128 = 131) und Ausnahmecode 2, unzulässige Datenadresse. Andere Codes sagen, dass die Funktion nicht unterstützt wird oder das Gerät beschäftigt ist.",Exception:"Ausnahme",Means:"Bedeutet","No register there":"Dort ist kein Register","registers 100–101":"Register 100–101",EXCEPTION:"AUSNAHME","code 2: no such register":"Code 2: kein solches Register","No Security":"Keine Sicherheit","Anyone who can reach it":"Jeder, der es erreichen kann","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Nichts in diesen Nachrichten sagt, wer sie geschickt hat: Modbus von 1979 hat weder Anmeldung noch Verschlüsselung, also kann jedes Gerät, das Port 502 erreicht, die Werte lesen und die Pumpe starten. Anlagen schützen es mit getrennten Netzen, Firewalls zwischen Büro und Anlage, Listen, wer mit welcher SPS sprechen darf, und Überwachung. Modbus/TCP Security verpackt dieselben Nachrichten in TLS, auf Port 802.","Separate networks, TLS":"Getrennte Netze, TLS","NO LOGIN, NO ENCRYPTION":"KEINE ANMELDUNG, KEINE VERSCHLÜSSELUNG","Seen on the plant network":"Im Anlagennetz gesehen","Picked by the client; the answer carries the same number.":"Vom Client gewählt; die Antwort trägt dieselbe Nummer.","Protocol ID":"Protokoll-ID","The unit ID and everything after it.":"Die Unit-ID und alles danach.","Unit ID":"Unit-ID","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Welches Gerät. Wichtig, wenn ein Gateway Anfragen an Geräte an einer seriellen Leitung weiterreicht.","Function code":"Funktionscode","Starting address":"Startadresse","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus zählt ab 0, auch wenn Handbücher dasselbe Register oft ab 40001 nummerieren.",Quantity:"Anzahl","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, Antwort","The same number as the request.":"Dieselbe Nummer wie die Anfrage.","Byte count":"Byteanzahl","Register 0":"Register 0","412 (tank level, 4.12 m)":"412 (Füllstand, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"Einfache 16-Bit-Zahlen. Was jede bedeutet, steht in der Dokumentation der SPS, nicht in der Nachricht.","Register 1":"Register 1","183 (temperature, 18.3 °C)":"183 (Temperatur, 18.3 °C)","Register 2":"Register 2","1450 (pump speed, 1,450 rpm)":"1450 (Pumpendrehzahl, 1,450 U/min)","450 (level setpoint, 4.50 m)":"450 (Füllstand-Sollwert, 4.50 m)","Register address":"Registeradresse","3 (level setpoint)":"3 (Füllstand-Sollwert)",Value:"Wert","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, Antwort","The answer repeats the request: done.":"Die Antwort wiederholt die Anfrage: erledigt.","Coil address":"Coil-Adresse","0 (pump 2)":"0 (Pumpe 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Eine Coil ist ein einzelner Ein/Aus-Ausgang. 0xFF00 schaltet sie ein.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, Antwort","Modbus/TCP · exception":"Modbus/TCP · Ausnahme","131 (3 + 128: an exception)":"131 (3 + 128: eine Ausnahme)","The top bit set: the request failed.":"Das höchste Bit gesetzt: Die Anfrage ist gescheitert.","Exception code":"Ausnahmecode","There is no register at that address.":"An dieser Adresse gibt es kein Register.","Internet Routes":"Wege im Internet",Routes:"Routen","The laptop’s packets":"Die Pakete des Laptops","Border Gateway Protocol":"Border Gateway Protocol","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Das Internet ist ein Netz aus Netzen: Zehntausende davon, betrieben von Internetanbietern, Clouds, Universitäten und Firmen, jedes mit seiner eigenen AS-Nummer. Mit BGP sagen sich ihre Grenzrouter gegenseitig, welche Adressen sie erreichen können. Jeder Router reicht weiter, was er erfährt, und fügt seine eigene Nummer hinzu, sodass jedes Netz seine eigene Karte der Wege zu jeder Adresse im Internet aufbaut.",Between:"Zwischen","Networks (ASes)":"Netzen (AS)",Table:"Tabelle","About a million IPv4 routes":"Rund eine Million IPv4-Routen","Path choice":"Wegwahl","Policy, then shortest":"Richtlinie, dann der kürzeste","Route learned":"Route gelernt","Announced, passed on, used":"Angekündigt, weitergereicht, benutzt","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"Das Hosting-Netz kündigte seine Adressen an, das Transitnetz reichte sie mit seiner eigenen Nummer weiter, und der Router des Anbieters benutzte diesen Weg für die Pakete des Laptops. Als die Route zurückgezogen wurde, verbreitete sich die Nachricht auf dieselbe Weise. Es gibt keine zentrale Karte: Jedes Netz baut seine eigene aus dem, was seine Nachbarn sagen. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Map:"Karte","Each network makes its own":"Jedes Netz baut seine eigene","RPKI and filters":"RPKI und Filter","Many Networks":"Viele Netze","Each with its own number":"Jedes mit eigener Nummer","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Das Internet besteht aus über 75,000 getrennten Netzen, sogenannten autonomen Systemen (AS): Internetanbieter, Clouds, Universitäten, große Firmen, jedes mit einer Nummer. Hier sind es drei: der Anbieter des Laptops (AS 64500), ein Transitnetz, das den Verkehr anderer trägt (AS 64510), und das Hosting-Netz von www.example.com (AS 64511). Mit BGP sagen sich ihre Router, wo jede Adresse zu erreichen ist.",Networks:"Netze","More than 75,000 ASes":"Über 75,000 AS",Here:"Hier","3 ASes, a router each":"3 AS, je ein Router",Numbers:"Nummern","TCP to port 179":"TCP zu Port 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"BGP-Router finden sich nicht von selbst: Ingenieure an beiden Enden richten sie gegenseitig als Nachbarn ein. Der Router des Anbieters öffnet eine TCP-Verbindung zum Transitrouter auf Port 179. Sie sind direkt verbunden, also gehen ihre Pakete mit einer TTL von 1 hinaus: Sie können nicht einmal einen weiteren Router passieren, also funktioniert die Sitzung nur zwischen direkten Nachbarn.",Neighbours:"Nachbarn","Set up by hand":"Von Hand eingerichtet","1: the next router only":"1: nur der nächste Router","OPEN, then KEEPALIVE":"OPEN, dann KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Jeder Router schickt ein OPEN: seine AS-Nummer, eine Hold Time von 180 Sekunden, seine Router-ID und was er unterstützt, etwa 4-Byte-AS-Nummern. Jeder antwortet mit einem KEEPALIVE, und die Sitzung steht. Ab jetzt geht alle 60 Sekunden ein KEEPALIVE, wenn sonst nichts zu senden ist; nach 180 stillen Sekunden würde die Sitzung abgebrochen.","AS, hold time, ID":"AS, Hold Time, ID","KEEPALIVE: established":"KEEPALIVE: hergestellt","Hold time":"Hold Time","hold 180 s":"Hold 180 s","SESSION ESTABLISHED":"SITZUNG HERGESTELLT","Announce a Route":"Eine Route ankündigen","The hosting network: “I have these”":"Das Hosting-Netz: „Die hier habe ich“","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"Der Router des Hosting-Netzes kündigt 203.0.113.0/24 an, die 256 Adressen, zu denen www.example.com gehört, und zwar dem Transitnetz, das es dafür bezahlt, seinen Verkehr zu tragen. Das UPDATE sagt, wie man hinkommt: AS_PATH 64511, bisher nur das eigene Netz, und NEXT_HOP, seine eigene Adresse auf der Verbindung zwischen beiden.","path 64511":"Pfad 64511","Passed On":"Weitergereicht","Each network adds its number":"Jedes Netz fügt seine Nummer hinzu","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"Der Transitrouter nimmt die Route an und reicht sie an seine anderen Nachbarn weiter, darunter den Anbieter, mit seiner eigenen Nummer vorn: AS_PATH 64510 64511, und sich selbst als nächsten Hop. Der Router des Anbieters erfährt vom selben Präfix vielleicht von mehreren Nachbarn. Er wählt einen zuerst nach seiner eigenen Richtlinie (etwa Routen über zahlende Kunden vor anderen), dann nach dem kürzesten AS-Pfad.","Best path":"Bester Pfad","path 64510 64511":"Pfad 64510 64511","ROUTE TO 203.0.113.0/24":"ROUTE ZU 203.0.113.0/24","Follow the Route":"Der Route folgen","Packets go where BGP said":"Pakete gehen, wohin BGP es sagt","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Wenn sich der Laptop mit www.example.com verbindet (dessen Adresse wie üblich per DNS gefunden wurde), erreichen seine Pakete den Anbieter, dessen Router jetzt alles für 203.0.113.0/24 an den Transitrouter schickt, und der Transitrouter reicht es an das Hosting-Netz weiter. Die Antwort kommt auf der Route zurück, die das Hosting-Netz zum Anbieter des Laptops gewählt hat: Im Internet ist der Rückweg oft ein anderer als der Hinweg.","Way back":"Rückweg","Chosen separately":"Getrennt gewählt","the way back":"der Rückweg",Withdrawn:"Zurückgezogen","Routes can be taken back":"Routen lassen sich zurücknehmen","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Später nimmt das Hosting-Netz das Präfix zurück, wie es das auch bei einem Leitungsausfall täte: ein UPDATE, das es unter zurückgezogenen Routen aufführt. Der Transitrouter reicht es weiter, und binnen Sekunden bis Minuten vergessen Netze überall den Weg. Eine Sitzung, die länger als ihre Hold Time still bleibt, verliert alle ihre Routen auf einmal. 2021 zog Facebook die Routen zu seinen eigenen DNS-Servern zurück und verschwand für sechs Stunden aus dem Internet.","Spreads in":"Verbreitet sich in","Seconds to minutes":"Sekunden bis Minuten","Session lost":"Sitzung verloren","All its routes go":"Alle ihre Routen sind weg",WITHDRAW:"RÜCKZUG","Trust Problems":"Vertrauensprobleme","BGP believes its neighbours":"BGP glaubt seinen Nachbarn","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Ein Router übernimmt, was seine Nachbarn ankündigen. Ein Netz, das fremde Adressen ankündigt, aus Versehen oder absichtlich, zieht deren Verkehr zu sich: 2008 legte ein pakistanischer Anbieter auf diese Weise YouTube weltweit lahm. Mit RPKI signiert der Inhaber eines Präfixes, welches AS es ankündigen darf, und prüfende Router verwerfen jedes andere. Filter für das, was jeder Nachbar ankündigen darf, erledigen den Rest.",Risk:"Risiko","Hijacks and leaks":"Hijacks und Leaks","Signed: who may announce":"Signiert: wer ankündigen darf",Also:"Außerdem","Filters per neighbour":"Filter pro Nachbar","CHECK WHO MAY ANNOUNCE":"PRÜFEN, WER ANKÜNDIGEN DARF","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: zurückgezogen 203.0.113.0/24",Marker:"Marker","16 bytes of 0xFF":"16 Bytes 0xFF","All ones: where a message starts.":"Lauter Einsen: Hier beginnt eine Nachricht.","The first message on a session: who this router is and what it supports.":"Die erste Nachricht einer Sitzung: wer dieser Router ist und was er unterstützt.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"Das Netz dieses Routers. (Eine 4-Byte-AS-Nummer steht in der Fähigkeit unten, hier mit 23456.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Kommt so lange gar nichts an, wird die Sitzung abgebrochen. Beide Seiten nehmen das niedrigere Angebot.","BGP identifier":"BGP-Kennung","The router’s ID, usually one of its addresses.":"Die ID des Routers, meist eine seiner Adressen.","Optional parameters":"Optionale Parameter","parameter 2, 14 bytes":"Parameter 2, 14 Bytes","What this router can do beyond the basics.":"Was dieser Router über das Grundlegende hinaus kann.",Multiprotocol:"Multiprotokoll","Which kinds of routes it will exchange on this session.":"Welche Arten von Routen er in dieser Sitzung austauscht.","Route refresh":"Route Refresh","It can ask the other side to send all its routes again.":"Er kann die andere Seite bitten, alle ihre Routen noch einmal zu schicken.","4-byte AS numbers":"4-Byte-AS-Nummern","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"Die 2-Byte-AS-Nummern wurden knapp, also sind neuere 4 Bytes lang.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Nur der Header: „noch da“. Wird geschickt, wenn es sonst nichts zu sagen gibt, nach jedem Drittel der Hold Time.","Routes: paths to new addresses, and ones taken back.":"Routen: Wege zu neuen Adressen und zurückgenommene.","Withdrawn routes":"Zurückgezogene Routen","Path attributes":"Pfadattribute","0 (IGP: from inside the network that announced it)":"0 (IGP: aus dem Inneren des ankündigenden Netzes)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Jedes Netz, das die Route durchlaufen hat, das jüngste zuerst. Bei sonst gleichen Bedingungen gewinnt der kürzere Pfad; ein Router, der hier seine eigene Nummer findet, verwirft die Route, also können Routen keine Schleifen bilden.","Send packets for these addresses to this router.":"Pakete für diese Adressen an diesen Router schicken.",Reachable:"Erreichbar","The addresses this route leads to: a prefix, here 256 addresses.":"Die Adressen, zu denen diese Route führt: ein Präfix, hier 256 Adressen.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (Rückzug)","These addresses can no longer be reached through this router.":"Diese Adressen sind über diesen Router nicht mehr erreichbar.","A Video Call":"Ein Videoanruf",Signalling:"Signalisierung","STUN and ICE":"STUN und ICE",Media:"Medien","STUN Server":"STUN-Server","Sam’s Router":"Router von Sam","Sam’s Laptop":"Laptop von Sam","Web Real-Time Communication":"Echtzeitkommunikation im Web","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"Mit WebRTC können sich zwei Browser anrufen, wobei Audio, Video und Daten direkt zwischen ihnen fließen, nicht über einen Server. Ein Server stellt sie nur einander vor: Sie tauschen Beschreibungen dessen aus, was sie senden können und wo sie erreichbar sind (Signalisierung), finden mit ICE und STUN einen Weg durch beide Heimrouter, verschlüsseln mit DTLS und schicken die Medien über UDP als SRTP.","Media over":"Medien über","Always on":"Immer an","Works in":"Läuft in","Every major browser":"Allen großen Browsern","W3C; RFC 8825 and others":"W3C; RFC 8825 und weitere","On the call":"Im Anruf","Introduced by a server, then direct":"Von einem Server vorgestellt, dann direkt","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"Der Signalisierungsserver reichte Angebot und Antwort zwischen den beiden Browsern weiter, ein STUN-Server nannte dem Laptop seine öffentliche Adresse, und eine ICE-Prüfung fand einen Weg durch beide Heimrouter. Nach einem DTLS-Handshake gingen verschlüsseltes Audio und Video direkt von einem Laptop zum anderen. Drücke NOCHMAL, um es dir noch einmal anzusehen.","Via call.example.com":"Über call.example.com","Media path":"Medienweg","Direct, through 2 NATs":"Direkt, durch 2 NATs","DTLS, then SRTP":"DTLS, dann SRTP","If blocked":"Wenn blockiert","A TURN relay":"Ein TURN-Relay","Join the Call":"Dem Anruf beitreten","Through a signalling server":"Über einen Signalisierungsserver","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"Der Laptop öffnet eine Anrufseite auf call.example.com, und die Seite hält einen WebSocket zum Server offen, in TLS. Er tritt Raum 42 bei, wo Sam schon wartet. Der Server reicht Nachrichten zwischen den beiden Browsern weiter. WebRTC sagt nicht, wie: Jede App erledigt diese Signalisierung auf ihre eigene Weise.","The app’s own server":"Der eigene Server der App","A WebSocket in TLS":"Ein WebSocket in TLS",Room:"Raum","42, with Sam":"42, mit Sam",JOIN:"BEITRETEN","room 42":"Raum 42","SAM IS HERE":"SAM IST DA","peer: Sam":"Gegenüber: Sam","Public Address?":"Öffentliche Adresse?","Ask a STUN server":"Einen STUN-Server fragen","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Hinter seinem Heimrouter kennt der Laptop nur seine private Adresse, 192.168.1.10, die niemand im Internet erreichen kann. Also fragt er mit einer kleinen UDP-Anfrage einen STUN-Server, der in den Einstellungen der Anrufseite steht. Die Antwort sagt, woher die Anfrage zu kommen schien, 198.51.100.7 Port 61022: die öffentliche Adresse des Routers und der Port, den sein NAT für dieses Gespräch geöffnet hat.",Public:"Öffentlich","what is my address?":"Wie lautet meine Adresse?","YOUR ADDRESS":"DEINE ADRESSE","The Offer":"Das Angebot","An SDP description, via the server":"Eine SDP-Beschreibung, über den Server","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"Der Browser schreibt ein Angebot in SDP: die Medien, die er senden will (Opus-Audio; Video in VP8, H.264 und anderen), den Fingerabdruck seines DTLS-Zertifikats, seinen ICE-Benutzernamen und sein ICE-Passwort und seine Kandidaten, die Adressen, unter denen er erreichbar sein könnte. Seine private Adresse versteckt sich hinter einem zufälligen .local-Namen. Der Signalisierungsserver reicht das Angebot an Sam weiter.","SDP, in a JSON message":"SDP, in einer JSON-Nachricht",Candidates:"Kandidaten",".local name, 198.51.100.7":".local-Name, 198.51.100.7","About 4.7 KB":"Etwa 4.7 KB","SDP: audio, video":"SDP: Audio, Video",candidates:"Kandidaten","to Sam":"an Sam","Sam’s browser replies":"Sams Browser antwortet","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Sam nimmt den Anruf an. Sams Browser antwortet mit eigenem SDP: den Codecs, die er aus dem Angebot gewählt hat, seinem Zertifikats-Fingerabdruck, seinem ICE-Benutzernamen und -Passwort und seinen Kandidaten, darunter seine öffentliche Adresse, 198.51.100.200 Port 49170, die er auf dieselbe Weise von einem STUN-Server erfahren hat. Außerdem sagt er, dass er den Verschlüsselungs-Handshake startet. Jetzt weiß jeder Browser, wo der andere erreichbar sein könnte.",Codecs:"Codecs","Sam’s address":"Sams Adresse","Starts DTLS":"Startet DTLS","Sam’s browser":"Sams Browser","from Sam":"von Sam","Punch Through":"Durchstoßen","Checks straight to each other":"Prüfungen direkt zueinander","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Jetzt probieren die Browser Adresspaare mit STUN-Prüfungen aus, die direkt zueinander geschickt werden (ICE). Jede Prüfung öffnet auch einen Rückweg durch den Router des Absenders, also kommen Prüfungen durch beide NATs, sobald beide Seiten eine geschickt haben. Diese wird beantwortet: Der direkte Weg funktioniert. Der Laptop wiederholt die Prüfung dann mit USE-CANDIDATE und wählt dieses Paar für den Anruf.",Checks:"Prüfungen","STUN, peer to peer":"STUN, direkt zwischen den Peers","The ICE password":"Das ICE-Passwort","A direct path":"Ein direkter Weg",CHECK:"PRÜFUNG","IT WORKS":"KLAPPT","direct path":"direkter Weg","THROUGH BOTH ROUTERS":"DURCH BEIDE ROUTER","DTLS Handshake":"DTLS-Handshake","Keys for the media":"Schlüssel für die Medien","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Über denselben Weg führen die Browser einen DTLS-Handshake aus: TLS für UDP. Ihre Zertifikate sind selbst signiert, also prüft jeder das des anderen anhand des Fingerabdrucks im SDP, der über den Signalisierungsserver in TLS kam. Der Handshake vereinbart auch die Schlüssel für SRTP, das Audio und Video verschlüsselt. WebRTC schickt Medien nie unverschlüsselt.","1.2, TLS over UDP":"1.2, TLS über UDP","Checked by fingerprint":"Per Fingerabdruck geprüft",Gives:"Liefert","The SRTP keys":"Die SRTP-Schlüssel",certificate:"Zertifikat","Media Flows":"Medien fließen","Audio and video, direct":"Audio und Video, direkt","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"Audio geht alle 20 ms in einem SRTP-Paket, Video als Bilder, die auf mehrere Pakete verteilt sind. Jedes Paket hat einen lesbaren RTP-Header (Sequenznummer, Zeitstempel, Stream-ID) und verschlüsselte Medien. Nichts davon läuft über call.example.com. Beide Browser beobachten Verzögerung und Verluste und passen die Videoqualität daran an, und ein Datenkanal für Chat oder Dateien kann denselben Weg nutzen.","Opus, a packet per 20 ms":"Opus, ein Paket alle 20 ms",Video:"Video","VP8, adapts to the network":"VP8, passt sich dem Netz an","None of it":"Nichts davon",AUDIO:"AUDIO","Opus, every 20 ms":"Opus, alle 20 ms",VIDEO:"VIDEO","VP8, a frame in 3 packets":"VP8, ein Bild in 3 Paketen","Peer to Peer":"Peer-to-Peer","And when it can’t be":"Und wenn es nicht geht","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"Der Server hat den beiden Browsern geholfen, einander zu finden, und ist dann zur Seite getreten: Der Anruf läuft direkt zwischen den beiden Wohnungen. Wenn ein Netz keine direkten Pakete durchlässt (manche Firmen-Firewalls, manche Mobilfunknetze), weicht ICE auf einen TURN-Server aus, der die verschlüsselten Medien weiterleitet, ohne sie lesen zu können. Gruppenanrufe schicken die Medien meist ebenfalls über einen Server, eine sogenannte SFU.","Laptop to laptop":"Laptop zu Laptop",Fallback:"Ausweichlösung","TURN relay (encrypted)":"TURN-Relay (verschlüsselt)","Group calls":"Gruppenanrufe","Usually via an SFU":"Meist über eine SFU","NO SERVER IN THE MIDDLE":"KEIN SERVER DAZWISCHEN","A WebSocket text message":"Eine WebSocket-Textnachricht","The attributes; the 20-byte header isn’t counted.":"Die Attribute; der 20-Byte-Header zählt nicht mit.","Always this value: tells STUN apart from the other traffic on the same port.":"Immer dieser Wert: unterscheidet STUN vom übrigen Verkehr auf demselben Port.","Random; the response carries the same ID.":"Zufällig; die Antwort trägt dieselbe ID.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"Woher die Anfrage kam, wie der Server sie sah: die öffentliche Adresse des Heimrouters und der Port, den sein NAT für dieses Gespräch gewählt hat.","Their internet provider’s router, the next hop.":"Der Router von Sams Internetanbieter, der nächste Hop.","Their router’s internet-facing port.":"Der Port von Sams Router zum Internet hin.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"Die ICE-Benutzernamen aus Angebot und Antwort, der der Gegenseite zuerst: belegt, dass die Prüfung zu diesem Anruf gehört.","The priority a new candidate found by this check would get.":"Die Priorität, die ein neuer, durch diese Prüfung gefundener Kandidat bekäme.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Diese Seite, die anrufende, trifft die endgültige Wahl des Wegs. Die Zufallszahl entscheidet bei Gleichstand.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 der Nachricht, mit einem ICE-Passwort als Schlüssel, das über den Signalisierungsserver ausgetauscht wurde, damit kein Fremder eine Prüfung oder ihre Antwort fälschen kann.","A CRC-32 of the message: marks it clearly as STUN.":"Eine CRC-32 der Nachricht: kennzeichnet sie eindeutig als STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"Woher die Prüfung kam, wie der andere Laptop sie sah: öffentliche Adresse und Port des Heimrouters.",Epoch:"Epoche","Counts this side’s records, so repeats and stale ones can be spotted.":"Zählt die Records dieser Seite, damit Wiederholungen und veraltete erkannt werden.","Message length":"Nachrichtenlänge","Message sequence":"Nachrichtensequenz","Handshake messages are numbered, so they can be put back in order.":"Handshake-Nachrichten sind nummeriert, damit sie wieder in die richtige Reihenfolge gebracht werden können.",Fragment:"Fragment","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Cipher-Suites: ECDHE-ECDSA mit AES-GCM und weitere","use_srtp: the SRTP protection it supports":"use_srtp: der SRTP-Schutz, den er unterstützt","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Gewählt: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Ein selbst signiertes Zertifikat, das der Browser erzeugt hat; sein Fingerabdruck stand im Angebot","Its half of an X25519 key exchange, signed":"Seine Hälfte eines X25519-Schlüsselaustauschs, signiert","Asks Sam’s browser for its certificate too":"Bittet auch Sams Browser um sein Zertifikat","Sam’s self-signed certificate; its fingerprint was in the answer":"Sams selbst signiertes Zertifikat; sein Fingerabdruck stand in der Antwort","Its half of the X25519 key exchange":"Seine Hälfte des X25519-Schlüsselaustauschs","A signature that proves it holds the certificate’s key":"Eine Signatur, die belegt, dass er den Schlüssel des Zertifikats besitzt","From the next record on, this side encrypts.":"Ab dem nächsten Record verschlüsselt diese Seite.","Finished (encrypted)":"Finished (verschlüsselt)","Epoch 1: protected with the keys just agreed.":"Epoche 1: geschützt mit den gerade vereinbarten Schlüsseln.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Eine 8-Byte-Nonce, die Finished-Nachricht und ein 16-Byte-Tag (AES-128-GCM).","SRTP · audio":"SRTP · Audio","2, no padding, extension, no CSRCs":"2, keine Auffüllung, Erweiterung, keine CSRCs","X set: a header extension follows the fixed header.":"X gesetzt: Auf den festen Header folgt eine Header-Erweiterung.","One more for each packet, so a lost or late one shows.":"Eins mehr pro Paket, damit ein verlorenes oder verspätetes auffällt.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Audiotakt, 48,000 Ticks pro Sekunde: +960 pro 20 ms.","Which stream this is; announced in the SDP.":"Welcher Stream das ist; im SDP angekündigt.","Header extension":"Header-Erweiterung","0xbede, 2 words":"0xbede, 2 Wörter","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Ein-Byte-Elemente: eine ID (aus den a=extmap-Zeilen des SDP) und eine Länge.","Audio level":"Audiopegel","How loud this packet is, so a group call can show who is talking without decrypting.":"Wie laut dieses Paket ist, damit ein Gruppenanruf ohne Entschlüsseln zeigen kann, wer spricht.","Transport sequence":"Transportsequenz","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Nummeriert jedes Paket des Anrufs; der Empfänger meldet für die Staukontrolle, was wann ankam.","Encrypted media":"Verschlüsselte Medien","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms Opus-Audio, verschlüsselt mit Schlüsseln aus dem DTLS-Handshake (AES-128-GCM).","Authentication tag":"Authentifizierungs-Tag","Proves the packet came from the other side unchanged; the header is covered too.":"Belegt, dass das Paket unverändert von der Gegenseite kam; der Header ist mit abgedeckt.","SRTP · video":"SRTP · Video","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Videotakt, 90,000 Ticks pro Sekunde: +3,000 pro Bild bei 30 Bildern pro Sekunde.","Absolute send time":"Absolute Sendezeit","When the packet was sent, so the receiver can tell when the network is filling up.":"Wann das Paket gesendet wurde, damit der Empfänger merkt, wenn sich das Netz füllt.","1 byte":"1 Byte","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Teil eines VP8-Videobilds, verschlüsselt mit Schlüsseln aus dem DTLS-Handshake (AES-128-GCM).","Marker set: the last packet of a video frame.":"Marker gesetzt: das letzte Paket eines Videobilds.",PLC:"SPS","8 ports":"8 Ports","Frames and switches":"Frames und Switches","Broadband logins":"Breitband-Logins","The laptop sent it with 128; the router took 1 when it passed it on.":"Der Laptop hat es mit 128 gesendet; der Router hat beim Weiterleiten 1 abgezogen.","Frames & Switches":"Frames und Switches","To the NAS":"Zum NAS","To the internet":"Ins Internet","Ethernet and Switches":"Ethernet und Switches","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Ethernet trägt fast jedes kabelgebundene Netz, und WLAN-Access-Points geben ihren Verkehr an es weiter. Jede Netzwerkkarte hat eine 48-Bit-MAC-Adresse. Ein Frame sagt, für welche Karte er ist und welche Karte ihn gesendet hat, und ein Switch stellt ihn zu: Er lernt aus den Frames, die er sieht, hinter welchem Port jede Adresse liegt, und schickt jeden Frame nur dorthin, wo er hinmuss.","48-bit MAC":"48-Bit-MAC","14 bytes, plus a 4-byte FCS":"14 Byte, dazu 4 Byte FCS","Frame size":"Frame-Größe","64 to 1,518 bytes":"64 bis 1.518 Byte",Speeds:"Geschwindigkeiten",Switched:"Geswitcht","Learned, flooded, forwarded":"Gelernt, geflutet, weitergeleitet","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"Der Switch hat aus den gesendeten Frames gelernt, wo Laptop und NAS sind, nur den Broadcast geflutet und jeden anderen Frame nur über den nötigen Port geschickt. MAC-Adressen haben jeden Frame über genau eine Verbindung gebracht; am Router kam das Paket in einen neuen Frame. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Learned:"Gelernt","2 addresses, 2 ports":"2 Adressen, 2 Ports",Flooded:"Geflutet","Only the broadcast":"Nur der Broadcast",Frame:"Frame","14-byte header, 4-byte FCS":"14-Byte-Header, 4 Byte FCS","Forgets after":"Vergisst nach","5 minutes unused":"5 Minuten ohne Nutzung","Who Has the NAS?":"Wer hat das NAS?","A broadcast asks for a MAC address":"Ein Broadcast fragt nach einer MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"Der Laptop will das NAS unter 192.168.1.20 erreichen. Im lokalen Netz werden Frames per MAC-Adresse zugestellt, und der Laptop kennt die des NAS noch nicht. Also schickt er eine ARP-Anfrage an ff:ff:ff:ff:ff:ff, die Broadcast-Adresse, in Port 1 des Switches.","Looking for":"Sucht","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (alle)",Into:"Hinein über","Switch port 1":"Switch-Port 1","who has 192.168.1.20?":"Wer hat 192.168.1.20?","Learn, Then Flood":"Lernen, dann fluten","The switch notes where the laptop is":"Der Switch merkt sich, wo der Laptop ist","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Ein Switch liest die Absenderadresse jedes Frames und trägt sie in seine MAC-Tabelle ein: 00:00:5e:00:53:10 ist an Port 1. Ein Broadcast ist für alle, also schickt er über jeden anderen Port eine Kopie: an das NAS an Port 2 und an den Router an Port 8. Frames an unbekannte Adressen werden ebenfalls geflutet.","…:53:10 is on port 1":"…:53:10 ist an Port 1",Copies:"Kopien","Out of every other port":"Über jeden anderen Port","Unknown address":"Unbekannte Adresse","Flooded the same way":"Genauso geflutet","…:53:10 IS ON PORT 1":"…:53:10 IST AN PORT 1","copies out of ports 2 and 8":"Kopien über Port 2 und 8","Only the NAS Answers":"Nur das NAS antwortet","The reply goes to one port":"Die Antwort geht an einen Port","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Jedes Gerät liest die Anfrage, aber nur das NAS hat 192.168.1.20, also antwortet nur es, direkt an die MAC des Laptops; der Router ignoriert sie. Der Switch lernt, dass 00:00:5e:00:53:20 an Port 2 ist. Wo der Laptop ist, weiß er schon, also geht die Antwort nur über Port 1 hinaus.","To the laptop only":"Nur an den Laptop","…:53:20 is on port 2":"…:53:20 ist an Port 2","Out of":"Hinaus über","Port 1":"Port 1","…:53:20 IS ON PORT 2":"…:53:20 IST AN PORT 2","port 1 only":"nur Port 1","Port to Port":"Port zu Port","Frames go only where they must":"Frames gehen nur, wohin sie müssen","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"Der Laptop verbindet sich mit dem NAS. Jeder Frame beginnt mit der MAC des NAS, dann der eigenen, dann einem Typ: 0x0800, ein IPv4-Paket. Nach dem Paket hängt die Karte eine 4 Byte lange Prüfsumme an. Der Switch schlägt das Ziel nach und schickt jeden Frame nur über Port 2. Der Router sieht sie nie.","To, from, type: 14 bytes":"An, von, Typ: 14 Byte","4 bytes, added by the card":"4 Byte, von der Karte","Router sees":"Router sieht",Nothing:"Nichts","type 0x0800 (IPv4)":"Typ 0x0800 (IPv4)","out of port 2 only":"nur über Port 2","Off the Network":"Raus aus dem Netz","A frame for the router":"Ein Frame für den Router","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Als Nächstes öffnet der Laptop eine Website unter 203.0.113.10. Diese Adresse liegt nicht im lokalen Netz, also geht der Frame an den Router: Dessen MAC, bekannt aus einem früheren ARP, ist das Ziel, während das Paket darin weiterhin 203.0.113.10 nennt. Der Switch schickt ihn über Port 8.","Frame to":"Frame an","The router’s MAC":"Die MAC des Routers","Packet to":"Paket an","Port 8":"Port 8","IP packet to 203.0.113.10":"IP-Paket an 203.0.113.10","out of port 8":"über Port 8","A New Frame":"Ein neuer Frame","Every hop rewraps the packet":"Jeder Hop verpackt das Paket neu","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"Der Router nimmt das Paket aus dem Frame, senkt die TTL und setzt seine öffentliche Adresse ein (NAT). Dann steckt er das Paket in einen neuen Frame für die nächste Verbindung: seine MAC auf der Internetseite als Absender, der Router des Anbieters als Ziel. MAC-Adressen überqueren nie mehr als eine Verbindung.","The router’s internet port":"Internet-Port des Routers","The provider’s router":"Der Router des Anbieters","Still 203.0.113.10":"Weiter 203.0.113.10","NEW FRAME":"NEUER FRAME","from the router’s internet port":"vom Internet-Port des Routers","IP still to 203.0.113.10":"IP weiter an 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"Rein, Port 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Raus, Port 2 (geflutet) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Raus, Port 8 (geflutet) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"Rein, Port 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Raus nur über Port 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"Rein, Port 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Raus, Port 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"Rein, Port 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Raus, Port 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"Rein, Port 1 · 52344 → 443 [SYN] (Frame an den Router)","Out port 8 · 52344 → 443 [SYN]":"Raus, Port 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (neuer Frame, nach NAT)","Seen going into the switch, port 1":"Gesehen beim Eintritt in den Switch, Port 1","Seen leaving the switch, port 2":"Gesehen beim Verlassen des Switches, Port 2","Seen leaving the switch, port 8":"Gesehen beim Verlassen des Switches, Port 8","Seen going into the switch, port 2":"Gesehen beim Eintritt in den Switch, Port 2","Seen leaving the switch, port 1":"Gesehen beim Verlassen des Switches, Port 1","Broadband Logins":"Breitband-Logins",Discovery:"Discovery","PPP setup":"PPP-Aufbau","Home Router":"Heimrouter","Access Server":"Zugangsserver","Point-to-Point Protocol over Ethernet":"Point-to-Point Protocol über Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Viele DSL- und Glasfaseranbieter verlangen, dass sich der Heimrouter anmeldet, bevor er ins Internet darf. PPPoE regelt das: Der Router findet den Zugangsserver des Anbieters und öffnet eine Sitzung mit ihm, darin läuft PPP: Es einigt sich auf die Einstellungen der Verbindung, meldet sich mit Benutzername und Passwort des Anbieters an und erhält die öffentliche IP-Adresse. Danach trägt jedes Paket einen 8 Byte langen PPPoE-Header.","CHAP or PAP":"CHAP oder PAP","From IPCP":"Über IPCP","8 bytes (MTU 1,492)":"8 Byte (MTU 1.492)","Logged in":"Angemeldet","Found, agreed, checked, addressed":"Gefunden, geeinigt, geprüft, adressiert","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"Der Router hat den Zugangsserver des Anbieters gefunden, eine Sitzung bekommen, sich auf die Einstellungen der Verbindung geeinigt, sein Passwort bewiesen, ohne es zu senden, und seine öffentliche Adresse erhalten. Jedes Paket reist jetzt in dieser Sitzung, bis ein PADT sie beendet. Drücke NOCHMAL, um es dir noch einmal anzusehen.","17 to get online":"17 bis online","Public IP":"Öffentliche IP","8 bytes per packet":"8 Byte pro Paket","Anyone There?":"Jemand da?","The router looks for an access server":"Der Router sucht einen Zugangsserver","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"Der Heimrouter hängt an der Glasfaser- oder DSL-Leitung des Anbieters. Bevor er sich anmelden kann, muss er den Zugangsserver des Anbieters finden, also sendet er per Broadcast ein PADI: „PPPoE Active Discovery Initiation“. Ein Zugangsserver antwortet mit einem PADO, einem Angebot mit seinem Namen: bng-1.example.net.","PADI, to everyone":"PADI, an alle","PADO, from the server":"PADO, vom Server","Ethernet type":"Ethernet-Typ","0x8863 (discovery)":"0x8863 (Discovery)","is there an access server?":"gibt es einen Zugangsserver?","and a cookie":"und ein Cookie","Pick a Server":"Einen Server wählen","A session number for the line":"Eine Sitzungsnummer für die Leitung","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Haben mehrere Server geantwortet, wählt der Router einen aus und fragt ihn direkt mit einem PADR, wobei er das erhaltene Cookie zurückschickt. Der Server antwortet mit einem PADS mit einer Sitzungs-ID, 0x2f1c. Ab jetzt trägt jeder Frame zwischen den beiden diese Nummer.",Confirmed:"Bestätigt","this server, please":"diesen Server, bitte","with its cookie":"mit seinem Cookie","session ID 0x2f1c":"Sitzungs-ID 0x2f1c","SESSION 0x2F1C":"SITZUNG 0x2F1C","Link Settings":"Verbindungseinstellungen","LCP agrees on size and login":"LCP einigt sich auf Größe und Anmeldung","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"Jetzt läuft PPP in der Sitzung, zuerst LCP. Jede Seite fordert ihre Einstellungen an: Pakete von höchstens 1.492 Byte, weil die 8 Byte von PPPoE in die 1.500 von Ethernet passen müssen, und eine zufällige Magic Number, um Schleifen zu erkennen. Der Server verlangt außerdem eine CHAP-Anmeldung. Beide stimmen zu.","Largest packet":"Größtes Paket","1,492 bytes (MRU)":"1.492 Byte (MRU)","CHAP with MD5":"CHAP mit MD5","0x8864 (session)":"0x8864 (Sitzung)","LCP REQUEST":"LCP-ANFRAGE","magic number":"Magic Number","MRU 1492, log in with CHAP":"MRU 1492, Login per CHAP","LCP ACK":"LCP ACK","A password check without the password":"Passwortprüfung ohne Passwort","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"Der Server sendet eine zufällige Challenge. Der Router antwortet mit seinem Benutzernamen, alex@fibre.example, und einem MD5-Hash aus Challenge und Passwort, sodass das Passwort selbst nie über die Leitung geht. Der Server prüft die Antwort beim RADIUS-Server des Anbieters und meldet dann Success.",Username:"Benutzername","A hash, not the password":"Ein Hash, nicht das Passwort","The provider’s RADIUS":"Das RADIUS des Anbieters","MD5(id, password, challenge)":"MD5(ID, Passwort, Challenge)","CHECKED WITH RADIUS":"PER RADIUS GEPRÜFT","Get an Address":"Eine Adresse bekommen","IPCP hands out the public IP":"IPCP vergibt die öffentliche IP","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"Zuerst nennt der Server dem Router sein eigenes Ende, 198.51.100.1. Der Router fragt nach einer Adresse und DNS-Servern und bietet 0.0.0.0 an: „irgendeine“. Der Server lehnt ab und schlägt 198.51.100.7 und zwei DNS-Server vor. Der Router fragt mit diesen Werten erneut, und der Server stimmt zu.","Other end":"Anderes Ende","IPCP REQUEST":"IPCP-ANFRAGE","my end: 198.51.100.1":"mein Ende: 198.51.100.1","address? 0.0.0.0":"Adresse? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"nimm 198.51.100.7","198.51.100.7, please":"198.51.100.7, bitte",agreed:"einverstanden","Every packet in an 8-byte wrapper":"Jedes Paket in einer 8-Byte-Hülle","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"Der Laptop öffnet eine Website. Der Router setzt seine öffentliche Adresse ein (NAT) und schickt das Paket in der Sitzung: ein 6 Byte langer PPPoE-Header, dann 2 Byte, die „IPv4“ sagen. Außerdem senkt er die vom Laptop angebotene MSS von 1460 auf 1452, damit die Antworten in 1.492 Byte passen.",Wrapper:"Hülle","6 + 2 bytes":"6 + 2 Byte","1460 → 1452 (clamped)":"1460 → 1452 (gesenkt)","in session 0x2f1c":"in Sitzung 0x2f1c","MSS now 1452":"MSS jetzt 1452","Seen on the router’s line to the provider":"Gesehen auf der Leitung des Routers zum Anbieter","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 Byte","PADI, 2 tags":"PADI, 2 Tags","Broadcast: everything on the line receives it.":"Broadcast: Alles auf der Leitung empfängt es.","0x8863 (PPPoE discovery)":"0x8863 (PPPoE-Discovery)","Version, type":"Version, Typ","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: Gibt es da draußen einen Zugangsserver?","0 (none yet)":"0 (noch keine)","What follows this header.":"Was diesem Header folgt.","The service the router wants; empty means any.":"Der Dienst, den der Router will; leer heißt beliebig.","Type, length":"Typ, Länge","A value the router made up. Answers carry it back, so the router can match them to its request.":"Ein Wert, den sich der Router ausgedacht hat. Antworten bringen ihn zurück, damit der Router sie seiner Anfrage zuordnen kann.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 Byte","PADO, 4 tags":"PADO, 4 Tags","The access server’s port.":"Der Anschluss des Zugangsservers.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: Ein Zugangsserver antwortet.","The access server’s name.":"Der Name des Zugangsservers.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Ein Wert, den der Server wiedererkennt, wenn der Router ihn erneut anfragt, sodass ihn eine Flut gefälschter Anfragen nichts kostet.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 Byte","PADR, 3 tags":"PADR, 3 Tags","The access server that answered.":"Der Zugangsserver, der geantwortet hat.","Active Discovery Request: the router picks this server.":"Active Discovery Request: Der Router wählt diesen Server.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 Byte","PADS, 2 tags":"PADS, 2 Tags","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: Hier ist die Sitzungs-ID.","Given by the server in its PADS; every frame of the session carries it.":"Vom Server in seinem PADS vergeben; jeder Frame der Sitzung trägt sie.","PPPoE · 6 bytes":"PPPoE · 6 Byte","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 Byte","0x8864 (PPPoE session)":"0x8864 (PPPoE-Sitzung)","0x00 (Session)":"0x00 (Sitzung)","Session data: one PPP packet.":"Sitzungsdaten: ein PPP-Paket.","Link Control Protocol: the link’s settings.":"Link Control Protocol: die Einstellungen der Verbindung.","The settings this side wants.":"Die Einstellungen, die diese Seite will.","The answer carries the same number.":"Die Antwort trägt dieselbe Nummer.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Das größte Paket, das diese Seite annimmt: 1.500 Byte Ethernet minus die 8 von PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Zufällig. Käme die eigene Zahl zurück, liefe die Leitung in einer Schleife auf sich selbst zurück.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 Byte","How the server wants the router to log in.":"Wie sich der Router nach dem Wunsch des Servers anmelden soll.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 Byte","Every setting accepted, exactly as asked.":"Jede Einstellung angenommen, genau wie angefragt.","The number of the request this answers.":"Die Nummer der Anfrage, auf die dies antwortet.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 Byte","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 Byte","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: die Anmeldung.","A random value for the router to prove its password with.":"Ein Zufallswert, mit dem der Router sein Passwort beweist.","The response must carry the same number.":"Die Response muss dieselbe Nummer tragen.","Value size":"Wertgröße","Random, new for every login.":"Zufällig, bei jeder Anmeldung neu.","The server’s name.":"Der Name des Servers.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 Byte","The proof, and who is logging in.":"Der Beweis, und wer sich anmeldet.","The number of the challenge this answers.":"Die Nummer der Challenge, auf die dies antwortet.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 aus Kennung, Passwort und Challenge: Es beweist das Passwort, ohne es zu senden.","The username the provider gave.":"Der Benutzername vom Anbieter.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 Byte","The login worked.":"Die Anmeldung hat geklappt.","Text for people to read; any words will do.":"Text für Menschen zum Lesen; beliebige Worte gehen.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 Byte","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: die IP-Adresse und die DNS-Server.","The address of the server’s end of the link.":"Die Adresse des Server-Endes der Verbindung.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 Byte","Zero: “please give me an address”.":"Null: „Bitte gib mir eine Adresse.“","Zero: “which DNS server should I use?”":"Null: „Welchen DNS-Server soll ich nehmen?“","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 Byte","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 Byte","Not these values: here are ones that would be accepted.":"Nicht diese Werte: Hier sind welche, die angenommen würden.","The address for the router.":"Die Adresse für den Router.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 Byte","PPP · 2 bytes":"PPP · 2 Byte","An IPv4 packet follows.":"Ein IPv4-Paket folgt.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Vom Router von 1460 gesenkt, damit Pakete zurück in die 1.492 Byte passen, die PPPoE übrig lässt.","Internet phone calls":"Telefonieren übers Internet","IP camera streams":"Streams von IP-Kameras","Live streaming upload":"Livestreams hochladen","Multicast and TV channels":"Multicast und TV-Sender","IP Camera":"IP-Kamera","TV Box":"TV-Box",Camera:"Kamera","Internet Phone Calls":"Telefonieren übers Internet","Voice (RTP)":"Sprache (RTP)","SIP Server":"SIP-Server","Bob’s Router":"Router von Bob","Session Initiation Protocol":"Session Initiation Protocol","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP baut Telefonate übers Internet auf: Bürotelefone, Telefon-Apps und die Anbieter dahinter. Ein Telefon meldet sich beim SIP-Server seines Anbieters an. Um jemanden anzurufen, schickt es ein INVITE; das andere Telefon klingelt und nimmt ab, und beide einigen sich, wie die Sprache übertragen wird, die dann als RTP fließt. Die Nachrichten sind Klartext, ganz ähnlich wie HTTP.","UDP or TCP 5060":"UDP oder TCP 5060","Call setup":"Rufaufbau",Voice:"Sprache","RTP, described by SDP":"RTP, beschrieben per SDP","Codec here":"Codec hier","Call ended":"Aufgelegt","Signed in, rang, talked, hung up":"Angemeldet, geklingelt, gesprochen, aufgelegt","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"Alices Telefon hat sich mit einem Passwort angemeldet, das es nie gesendet hat, Bobs Telefon über den SIP-Server eingeladen, es klingeln gehört und per RTP gesprochen, bis Bob mit einem BYE auflegte. SIP hat das Gespräch nur auf- und abgebaut; die Sprache reiste in eigenen Paketen. Drücke NOCHMAL, um es dir noch einmal anzusehen.","50 packets a second each way":"50 Pakete pro Sekunde je Richtung",Through:"Über","The provider’s server":"Den Server des Anbieters","No (SIPS and SRTP add it)":"Nein (SIPS und SRTP ergänzen das)","Sign In":"Anmelden","The phone tells the server where it is":"Das Telefon sagt dem Server, wo es ist","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"Alices Telefon, eine App auf ihrem Laptop, registriert sich beim SIP-Server ihres Anbieters: alice@example.net ist hier erreichbar. Der Server antwortet 401 mit einer Challenge, also fragt das Telefon erneut, mit einem Hash aus Challenge und Passwort. 200 OK: für eine Stunde registriert.","Good for":"Gültig für","3600 s, then again":"3600 s, dann erneut","is here":"ist hier","with a challenge":"mit einer Challenge","again, with a hash":"erneut, mit einem Hash",registered:"registriert","Call Bob":"Bob anrufen","An INVITE, passed on by the server":"Ein INVITE, vom Server weitergereicht","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice ruft bob@example.net an. Ihr INVITE trägt SDP: G.711-Audio, an ihr Telefon zu senden. Der Server antwortet 100 Trying, findet heraus, wo sich Bobs Telefon registriert hat, und reicht das INVITE weiter, mit eigenem Via und Record-Route und seiner eigenen Adresse im SDP: Die Sprache läuft über ihn.","Offer (SDP)":"Angebot (SDP)","G.711, port 49170":"G.711, Port 49170","Stops Alice resending":"Alice sendet nicht erneut","call bob@example.net":"bob@example.net anrufen","SDP: G.711 audio":"SDP: G.711-Audio","passed on to Bob":"an Bob weitergereicht","voice via the server":"Sprache über den Server",Ringing:"Es klingelt","The answer retraces the route":"Die Antwort nimmt den Weg zurück","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"Bobs Telefon fängt an zu klingeln und meldet das: 180 Ringing. Antworten folgen den Via-Headern zurück, den Weg, den die Anfrage kam, also geht sie zum Server, der sein eigenes Via entfernt und sie an Alice weiterreicht. Ihr Telefon spielt das Freizeichen.","Route back":"Rückweg","The Via headers, in reverse":"Die Via-Header, rückwärts","Alice hears":"Alice hört","The ringing tone":"Das Freizeichen","Bob’s phone rings":"Bobs Telefon klingelt","to Alice":"an Alice",Answered:"Angenommen","200 OK, then ACK":"200 OK, dann ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob nimmt ab. Sein 200 OK trägt seine SDP-Antwort: G.711, an sein Telefon zu senden. Der Server setzt wieder seine eigene Adresse ein, bevor er sie an Alice weiterreicht. Ihr Telefon bestätigt mit einem ACK, das der Server an Bob weiterreicht. Das Gespräch steht.","Answer (SDP)":"Antwort (SDP)","G.711, port 49172":"G.711, Port 49172","Confirmed by":"Bestätigt mit","Voice goes to":"Sprache geht an","The server, ports 40000, 40002":"Den Server, Ports 40000, 40002","Bob answers":"Bob nimmt ab",answered:"angenommen",Talking:"Gespräch","Voice flows as RTP":"Die Sprache fließt als RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Jetzt die Sprache: Alle 20 ms schickt jedes Telefon ein RTP-Paket mit 160 Bytes G.711-Ton, einer Sequenznummer und einem Zeitstempel, über UDP. Sie gehen an den Server, der sie an das andere Telefon weiterreicht. SIP schweigt, solange sie sprechen.",Every:"Alle","20 ms, 160 bytes of sound":"20 ms, 160 Bytes Ton","Carried by":"Übertragen per","RTP over UDP":"RTP über UDP","SIP meanwhile":"SIP solange","Nothing to say":"Nichts zu sagen",VOICE:"SPRACHE","20 ms of Alice":"20 ms von Alice","20 ms of Bob":"20 ms von Bob","Hang Up":"Auflegen","BYE, and 200 OK":"BYE, dann 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob legt auf: Sein Telefon schickt BYE, über den Server, wie es die Record-Route verlangt, und Alices Telefon antwortet 200 OK. Beide hören auf, Sprache zu senden. Das Gespräch brauchte vier Arten von Anfragen; die Sprache selbst war nie Teil von SIP.","No more RTP":"Kein RTP mehr","Bob hangs up":"Bob legt auf","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: G.711 μ-law, der klassische Telefon-Codec)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Audiotakt mit 8000 pro Sekunde: +160 je 20 ms Ton.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 Bytes G.711-Audio (20 ms, ein Byte pro Abtastwert)","IP Camera Streams":"Streams von IP-Kameras","Video (RTP)":"Video (RTP)","Real Time Streaming Protocol":"Real Time Streaming Protocol","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"Mit RTSP holen sich Videoplayer, Rekorder und Sicherheits-Apps Live-Video von IP-Kameras. Es funktioniert wie eine Fernbedienung: Der Player fragt, was die Kamera anbietet, richtet einen Stream ein und sagt PLAY und später TEARDOWN, in Textnachrichten ganz ähnlich wie HTTP. Das Video selbst läuft nicht über RTSP: Es fließt getrennt als RTP, hier über UDP.",Controls:"Befehle",Watched:"Angesehen","Described, set up, played, stopped":"Beschrieben, eingerichtet, abgespielt, beendet","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC hat die Kamera gefragt, was sie hat, sich mit einem Hash seines Passworts angemeldet, eine Videospur eingerichtet und PLAY gedrückt. Das Video kam als RTP-Pakete an eigenen Ports, ein Keyframe in drei Teilen, bis TEARDOWN die Sitzung beendete. Drücke NOCHMAL, um es dir noch einmal anzusehen.","6 on one TCP connection":"6 über eine TCP-Verbindung","Key frame":"Keyframe","Split into 3 packets":"In 3 Paketen","1185d200, 60 s timeout":"1185d200, Timeout 60 s","What Can You Do?":"Was kannst du?","OPTIONS over a TCP connection":"OPTIONS über eine TCP-Verbindung","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC öffnet rtsp://192.168.1.64/stream1. Es verbindet sich über TCP-Port 554 mit der Kamera und beginnt mit OPTIONS: Welche Befehle unterstützt du? Die Kamera zählt sie auf. Wie bei HTTP ist jede Anfrage und Antwort Text; ein CSeq-Header nummeriert sie.","Numbered by":"Nummeriert per","what can you do?":"was kannst du?","Describe the Stream":"Den Stream beschreiben","SDP says what the video is":"SDP sagt, was das Video ist","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE fragt nach der Beschreibung des Streams. Die Kamera will zuerst eine Anmeldung: 401, mit einer Digest-Challenge. VLC fragt erneut mit einem Hash des Passworts, und die Antwort trägt SDP: eine H.264-Videospur, RTP-Payload-Typ 96, mit einem 90-kHz-Takt.","Digest: a hash":"Digest: ein Hash","H.264, payload type 96":"H.264, Payload-Typ 96",Track:"Spur","describe stream1":"beschreibe stream1","log in first":"erst anmelden","SDP: H.264 video":"SDP: H.264-Video","track 1":"Spur 1","Set Up":"Einrichten","Agree on ports for the video":"Ports für das Video vereinbaren","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP für trackID=1 sagt, wie sie geliefert wird: RTP über UDP, an die Ports 50000 (Video) und 50001 (RTCP-Berichte) des Laptops. Die Kamera stimmt zu, wählt eigene Ports, 6970 und 6971, und eröffnet eine Sitzung, 1185d200, die jede spätere Anfrage nennt.","Laptop ports":"Laptop-Ports","track 1, RTP over UDP":"Spur 1, RTP über UDP","to ports 50000-50001":"an Ports 50000-50001","session 1185d200":"Sitzung 1185d200","from ports 6970-6971":"von Ports 6970-6971",Play:"Abspielen","The remote control’s PLAY button":"Die PLAY-Taste der Fernbedienung","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY startet den Stream ab jetzt (npt=0.000-). Die Antwort sagt VLC, welche RTP-Sequenznummer und welcher Zeitstempel zuerst kommen, damit es das Video ausrichten kann. Ab hier läuft das Video gar nicht mehr über RTSP.",Range:"Bereich","From now":"Ab jetzt","First packet":"Erstes Paket","Video arrives":"Video kommt an","On the UDP ports":"An den UDP-Ports","play from now":"ab jetzt abspielen",playing:"läuft","Video Arrives":"Das Video kommt","A key frame in RTP packets":"Ein Keyframe in RTP-Paketen","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"Die Kamera schickt einen Keyframe, ein ganzes Bild, in drei RTP-Paketen: H.264-Fragmente, markiert als erstes, mittleres und letztes, mit dem Marker-Bit im letzten. Alle drei tragen denselben 90-kHz-Zeitstempel. Danach folgen kleinere Frames mit nur den Änderungen, 25 pro Sekunde.",Packets:"Pakete","3 for one key frame":"3 für einen Keyframe","Same for the whole frame":"Gleich fürs ganze Bild",Frames:"Bilder","25 a second":"25 pro Sekunde","a key frame in 3 packets":"ein Keyframe in 3 Paketen",Stop:"Stopp","TEARDOWN ends the session":"TEARDOWN beendet die Sitzung","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Wenn der Zuschauer den Stream schließt, schickt VLC TEARDOWN mit der Sitzungs-ID. Die Kamera hört auf, Video zu senden, und bestätigt. Wäre VLC einfach verschwunden, hätte die Kamera trotzdem aufgehört, sobald 60 Sekunden ohne ein Wort von ihm vergangen wären.",Ended:"Beendet",Otherwise:"Sonst","Timeout after 60 s":"Timeout nach 60 s","stop session 1185d200":"Sitzung 1185d200 beenden",stopped:"gestoppt","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"Die Kamera. Sie ist im selben Netz, also geht der Frame direkt zu ihr, nicht über den Router.","The camera’s network port.":"Der Netzwerkanschluss der Kamera.","RTP + video":"RTP + Video","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, wie die Beschreibung der Kamera sagte)","Marker clear: more of this frame follows.":"Marker nicht gesetzt: Von diesem Bild kommt noch mehr.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Videotakt mit 90.000 pro Sekunde; jedes Paket eines Bildes trägt denselben Wert.","Identifies this video stream.":"Kennzeichnet diesen Videostream.","FU indicator":"FU-Indikator","0x7c (fragment of a frame)":"0x7c (Fragment eines Bildes)","Fragmentation unit: one piece of a frame too big for one packet.":"Fragmentierungseinheit: ein Stück eines Bildes, das zu groß für ein Paket ist.","FU header":"FU-Header","0x85 (first piece of a key frame)":"0x85 (erstes Stück eines Keyframes)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Typ 5: ein Keyframe (IDR), ein ganzes Bild, mit dem der Decoder beginnen kann.","1398 bytes of the key frame":"1398 Bytes des Keyframes","0x05 (middle piece of a key frame)":"0x05 (mittleres Stück eines Keyframes)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, wie die Beschreibung der Kamera sagte)","Marker set: the last packet of a frame.":"Marker gesetzt: das letzte Paket eines Bildes.","0x45 (last piece of a key frame)":"0x45 (letztes Stück eines Keyframes)","900 bytes of the key frame":"900 Bytes des Keyframes","Multicast TV":"Multicast-TV","Joins and leaves":"Beitritte und Austritte","Channel 1":"Sender 1","TV channels":"TV-Sender","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Multicast schickt einen einzigen Stream an eine Gruppenadresse, und das Netz kopiert ihn nur dorthin, wo er gewünscht wird: So liefern Internetanbieter Live-TV-Sender aus. Mit IGMP sagt ein Gerät seinem Router, welche Gruppen es will. Switches hören mit (IGMP-Snooping), also erreicht jeder Stream nur die Ports, die ihn angefordert haben.","IP protocol 2":"IP-Protokoll 2",Groups:"Gruppen","Version here":"Version hier","Tuned In":"Eingeschaltet","Joined, copied, checked, left":"Beigetreten, kopiert, geprüft, verlassen","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"Die TV-Box und dann der Laptop sind Sender 1 mit IGMP-Berichten beigetreten. Der Router trat nur einmal für das ganze Zuhause bei, und der Switch hörte mit und kopierte den Sender nur an die Ports, die ihn wollten. Abfragen hielten ihn am Laufen, und als der Laptop ging, hielt die Antwort der TV-Box ihn an. Drücke NOCHMAL, um es dir noch einmal anzusehen.",Upstream:"Zum Anbieter","One stream for the home":"Ein Stream fürs ganze Zuhause","Copies to ports that joined":"Kopien an beigetretene Ports","Every 125 s":"Alle 125 s","Pick a Channel":"Einen Sender wählen","The TV box joins a group":"Die TV-Box tritt einer Gruppe bei","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"Der Zuschauer wählt Sender 1. Jeder Sender ist eine Multicast-Gruppe, hier 233.252.0.1, und die TV-Box schickt einen IGMP Membership Report an diese Adresse: Ich will diese Gruppe. Der Switch hört mit (IGMP-Snooping), merkt sich Port 2 und gibt den Bericht nur an den Router weiter.","Switch notes":"Switch merkt sich","Port 2 wants it":"Port 2 will ihn","233.252.0.1, please":"233.252.0.1, bitte","to the router port only":"nur an den Router-Port","Ask the Provider":"Beim Anbieter anfragen","The router joins for the home":"Der Router tritt fürs Zuhause bei","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"Der Router ist ein IGMP-Proxy: Er tritt der Gruppe auf seiner Internetseite mit einem eigenen Bericht bei, von seiner öffentlichen Adresse aus, und das Netz des Anbieters schickt Sender 1 über die Leitung. Egal wie viele Bildschirme zu Hause einschalten, der Router tritt nur einmal bei.","Router role":"Rolle des Routers","IGMP proxy":"IGMP-Proxy",Joins:"Tritt bei","Once for the whole home":"Einmal fürs ganze Zuhause","for the whole home":"fürs ganze Zuhause","The Channel Flows":"Der Sender läuft","Sent only where it was asked for":"Nur dorthin, wo er angefordert wurde","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"Der TV-Server des Anbieters schickt Sender 1 an 233.252.0.1: UDP-Datagramme mit je sieben 188-Byte-MPEG-TS-Paketen voller Video und Audio. Der Router lässt sie herein, und der Switch gibt sie nur an Port 2 aus: Nur die TV-Box ist beigetreten, also bekommt der Laptop keins.",Datagram:"Datagramm","UDP, 1,316 bytes of TV":"UDP, 1.316 Bytes TV",Holds:"Enthält","7 MPEG-TS packets":"7 MPEG-TS-Pakete","CHANNEL 1":"SENDER 1","MPEG-TS over UDP":"MPEG-TS über UDP","passed into the home":"ins Zuhause weitergegeben","port 2 only":"nur Port 2","A Second Screen":"Ein zweiter Bildschirm","The laptop tunes in too":"Der Laptop schaltet auch ein","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"Der Laptop öffnet Sender 1 in VLC und schickt seinen eigenen Bericht. Der Switch nimmt Port 1 dazu und macht jetzt zwei Kopien jedes Datagramms. Der Router bekommt den Sender schon, also fragt er beim Anbieter nichts an: Über die Leitung kommt weiter nur ein Stream.","Switch sends to":"Switch sendet an","Ports 1 and 2":"Ports 1 und 2","Still one stream":"Weiter ein Stream","Router asks":"Router fragt","Nothing new":"Nichts Neues","the same one stream":"derselbe eine Stream","copied to ports 1 and 2":"an Ports 1 und 2 kopiert","Still Watching?":"Schaust du noch?","The router checks regularly":"Der Router fragt regelmäßig nach","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Alle 125 Sekunden schickt der Router eine General Query an 224.0.0.1, alle Geräte: Welche Gruppen wollt ihr noch? Der Switch gibt sie an alle Ports weiter. Jedes Mitglied antwortet zu einem zufälligen Zeitpunkt innerhalb von 10 Sekunden, also halten Router und Switch den Sender am Laufen.","125 seconds":"125 Sekunden","224.0.0.1, all devices":"224.0.0.1, alle Geräte","Answer within":"Antwort binnen","10 seconds":"10 Sekunden",QUERY:"ABFRAGE","any groups wanted?":"welche Gruppen gewünscht?","to every port":"an alle Ports",REPORT:"BERICHT","still watching":"schaue noch",Leave:"Verlassen","The laptop stops watching":"Der Laptop hört auf zu schauen","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"Beim Schließen von VLC geht ein Leave Group an 224.0.0.2, alle Router. Andere schauen vielleicht noch, also fragt der Router nur nach dieser Gruppe und wartet 1 Sekunde. Die TV-Box antwortet, also bleibt der Sender; der Switch hört nur auf, ihn an Port 1 zu senden.","Leave sent to":"Austritt geht an","224.0.0.2, all routers":"224.0.0.2, alle Router","About that group alone":"Nur nach dieser Gruppe","Stays: the TV box answered":"Bleibt: Die TV-Box hat geantwortet",LEAVE:"AUSTRITT","done with 233.252.0.1":"fertig mit 233.252.0.1","anyone for 233.252.0.1?":"will jemand 233.252.0.1?","to the ports that joined":"an die beigetretenen Ports","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Multicast: 01:00:5e, dann die letzten 23 Bit der Gruppenadresse. Netzwerkkarten horchen auf die Gruppen, denen ihr System beigetreten ist.","The TV box’s network port.":"Der Netzwerkanschluss der TV-Box.","4, 24 bytes":"4, 24 Bytes","IPv4, with one 4-byte option.":"IPv4, mit einer 4-Byte-Option.","48 (network control), 0":"48 (Netzsteuerung), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Als Netzsteuerung markiert, also vor gewöhnlichem Verkehr gesendet.","Always 1: IGMP never goes past the first router.":"Immer 1: IGMP kommt nie über den ersten Router hinaus.","A multicast group address.":"Eine Multicast-Gruppenadresse.","Router Alert option":"Router-Alert-Option","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Bittet jeden Router unterwegs, hineinzuschauen, obwohl das Paket nicht an ihn adressiert ist.","This device wants the group’s traffic.":"Dieses Gerät will den Verkehr der Gruppe.","Max response time":"Maximale Antwortzeit","Only queries use it.":"Nur Abfragen nutzen sie.","Covers the IGMP message.":"Deckt die IGMP-Nachricht ab.","Group address":"Gruppenadresse","The multicast group: one TV channel.":"Die Multicast-Gruppe: ein TV-Sender.","Seen arriving on the router’s internet side":"Gesehen bei Ankunft auf der Internetseite des Routers","MPEG-TS · 7 packets":"MPEG-TS · 7 Pakete","The provider’s router, passing the channel on.":"Der Router des Anbieters, der den Sender weiterreicht.","Sync byte":"Sync-Byte","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Jedes Transport-Stream-Paket beginnt mit 0x47, damit der Empfänger findet, wo Pakete anfangen.","Flags, PID":"Flags, PID","0x0100 (PID 256: video)":"0x0100 (PID 256: Video)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"Zu welchem Stream das Paket gehört: das Video des Senders, sein Audio oder die Tabellen, die sie auflisten.","Payload, counter":"Nutzlast, Zähler","0x14 (payload only, counter 4)":"0x14 (nur Nutzlast, Zähler 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Zählt für jede PID von 0 bis 15, also fällt ein verlorenes Paket als Lücke auf.","184 bytes of the channel’s video":"184 Bytes vom Video des Senders","More packets":"Weitere Pakete","6 × 188 bytes: video and audio":"6 × 188 Bytes: Video und Audio","Six more transport stream packets, each with its own 4-byte header.":"Sechs weitere Transport-Stream-Pakete, jedes mit eigenem 4-Byte-Header.","Seen going into the switch, port 8":"Gesehen beim Eintritt in den Switch, Port 8","The router, passing the channel into the home.":"Der Router, der den Sender ins Zuhause weitergibt.","0x19 (payload only, counter 9)":"0x19 (nur Nutzlast, Zähler 9)","The router asks: which groups does anyone here still want?":"Der Router fragt: Welche Gruppen will hier noch jemand?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"Mitglieder antworten zu einem zufälligen Zeitpunkt innerhalb dieser Zeit, damit ihre Antworten nicht alle gleichzeitig eintreffen.","Zero in a general query: every group.":"Null in einer allgemeinen Abfrage: alle Gruppen.","This device no longer wants the group.":"Dieses Gerät will die Gruppe nicht mehr.","The router asks: does anyone still want this group?":"Der Router fragt: Will noch jemand diese Gruppe?","Live Streaming Upload":"Livestreams hochladen","RTMP handshake":"RTMP-Handshake","Video and audio":"Video und Audio","Ingest Server":"Ingest-Server","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"Mit RTMP schicken die meisten Streamer Live-Video an eine Plattform: OBS und andere Apps schieben es zu einem Ingest-Server, der daraus Streams für die Zuschauer macht. Für Flash gebaut, hat es Flash als Upload-Weg überlebt. Alles teilt sich eine TCP-Verbindung: Befehle, Audio und Video, in Chunks zerlegt.","H.264 video, AAC audio":"H.264-Video, AAC-Audio","Encoded in AMF0":"In AMF0 kodiert","Secure version":"Sichere Variante","RTMPS, over TLS":"RTMPS, über TLS","Adobe specification (2012)":"Adobe-Spezifikation (2012)",Live:"Live","Connected, published, streamed":"Verbunden, veröffentlicht, gestreamt","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS hat den Handshake mit dem Ingest-Server gemacht, sich mit dessen App live verbunden, Stream 1 bekommen und darauf mit dem Stream-Key veröffentlicht. Video und Audio flossen dann in Chunks über dieselbe TCP-Verbindung, bis der Streamer aufhörte. Drücke NOCHMAL, um es dir noch einmal anzusehen.","One TCP, port 1935":"Eine TCP, Port 1935",Stream:"Stream",Chunks:"Chunks","Up to 4,096 bytes":"Bis zu 4.096 Bytes","None: RTMPS adds TLS":"Keine: RTMPS ergänzt TLS","TCP, then RTMP’s own":"TCP, dann der von RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"Der Streamer klickt auf Stream starten. OBS verbindet sich über TCP-Port 1935 mit dem Ingest-Server, dann hat RTMP einen eigenen Handshake: Version 3 und 1.536 Zufallsbytes in jede Richtung, die jede Seite zurückschickt. Er zeigt, dass beide Enden RTMP sprechen; verschlüsselt wird nichts.","Each side":"Jede Seite","Sends 3,073 bytes":"Sendet 3.073 Bytes","version 3":"Version 3","1,536 random bytes":"1.536 Zufallsbytes","version 3, its own bytes":"Version 3, eigene Bytes","and C1 sent back":"und C1 zurück","S1 sent back":"S1 zurück",Connect:"Verbinden","To the server’s live app":"Zur App live des Servers","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS erhöht seine Chunk-Größe auf 4.096 Bytes und schickt connect für die App namens live, in AMF0, einem kompakten Binärformat aus Flash. Der Server legt sein eigenes Fenster, seine Bandbreite und Chunk-Größe fest und antwortet _result: NetConnection.Connect.Success.",App:"App",Encoding:"Kodierung","chunk size 4,096":"Chunk-Größe 4.096","window, bandwidth, chunks":"Fenster, Bandbreite, Chunks","Make a Stream":"Einen Stream anlegen","createStream returns stream 1":"createStream liefert Stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Jede Nachricht nennt einen Nachrichtenstream; 0 ist die Verbindung selbst. OBS gibt seinen Stream-Key frei und kündigt ihn an, dann fragt es per createStream nach einem Stream zum Senden, alle drei Befehle in einem Paket. Der Server antwortet mit Stream-ID 1.","3 in one packet":"3 in einem Paket",Gets:"Bekommt","Stream ID 1":"Stream-ID 1","stream ID 1":"Stream-ID 1",Publish:"Veröffentlichen","The stream key goes live":"Der Stream-Key geht live","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish nennt den Stream-Key, das Geheimnis, das sagt, wessen Kanal das ist. RTMP verschlüsselt nichts, also geht der Key im Klartext über die Leitung; Plattformen bevorzugen RTMPS, dasselbe über TLS. Der Server prüft den Key und antwortet NetStream.Publish.Start.","The stream key":"Den Stream-Key","None (RTMPS adds TLS)":"Keine (RTMPS ergänzt TLS)","on stream 1":"auf Stream 1","stream key, live":"Stream-Key, live","Video and Sound":"Bild und Ton","Metadata, settings, then frames":"Metadaten, Einstellungen, dann Bilder","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS beschreibt den Stream: 1920×1080 mit 30 Bildern pro Sekunde, H.264-Video, AAC-Audio. Es schickt die Einstellungen der Decoder, dann einen Keyframe, etwa 30 KB, in Chunks zu 4.096 Bytes zerlegt. Bilder folgen ohne Pause, über dieselbe TCP-Verbindung.","AAC, 48 kHz stereo":"AAC, 48 kHz Stereo","30 KB in 8 chunks":"30 KB in 8 Chunks",METADATA:"METADATEN","H.264 + AAC settings":"H.264- und AAC-Einstellungen","KEY FRAME":"KEYFRAME","8 chunks":"8 Chunks","Stop Streaming":"Stream beenden","FCUnpublish and deleteStream":"FCUnpublish und deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Wenn der Streamer auf Stream beenden klickt, schickt OBS FCUnpublish und deleteStream für Stream 1. Der Server antwortet NetStream.Unpublish.Success und beendet die Übertragung für die Zuschauer. Dann schließt OBS die TCP-Verbindung.","C0: version":"C0: Version","RTMP version 3, the only one in use.":"RTMP-Version 3, die einzige in Gebrauch.",Time:"Zeit","A timestamp; zero is allowed.":"Ein Zeitstempel; null ist erlaubt.",Zero:"Null","Random data":"Zufallsdaten","Random bytes the server must send back.":"Zufallsbytes, die der Server zurückschicken muss.","S0: version":"S0: Version","Random bytes the client must send back.":"Zufallsbytes, die der Client zurückschicken muss.","1,536 bytes: C1 back":"1.536 Bytes: C1 zurück","The timestamp from the block it echoes.":"Der Zeitstempel aus dem Block, den es zurückgibt.","Time read":"Gelesene Zeit","C1’s random bytes, sent back unchanged.":"Die Zufallsbytes von C1, unverändert zurückgeschickt.","1,536 bytes: S1 back":"1.536 Bytes: S1 zurück","S1’s random bytes, sent back unchanged.":"Die Zufallsbytes von S1, unverändert zurückgeschickt.","RTMP · 2 messages":"RTMP · 2 Nachrichten","First message":"Erste Nachricht","Chunk header":"Chunk-Header","type 0, chunk stream 2":"Typ 0, Chunk-Stream 2","A full header follows: this chunk starts a message.":"Ein voller Header folgt: Dieser Chunk beginnt eine Nachricht.","Message stream":"Nachrichtenstream","Stream 0: the connection itself. (This number alone is little-endian.)":"Stream 0: die Verbindung selbst. (Nur diese Zahl ist Little-Endian.)","Chunk size":"Chunk-Größe","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"Ab jetzt zerlegt diese Seite Nachrichten in Chunks bis zu dieser Größe (128, bis sie etwas anderes sagt).","Second message":"Zweite Nachricht","type 0, chunk stream 3":"Typ 0, Chunk-Stream 3","Matches a reply to its request.":"Ordnet eine Antwort ihrer Anfrage zu.","Command object":"Befehlsobjekt","object, 5 properties":"Objekt, 5 Eigenschaften","Which app on the server, and the address OBS was given.":"Welche App auf dem Server, und die Adresse, die OBS bekommen hat.","End of object":"Objektende","RTMP · 4 messages":"RTMP · 4 Nachrichten","The other side should hear back after every this many bytes it sends.":"Die andere Seite soll nach jeweils so vielen gesendeten Bytes eine Rückmeldung bekommen.","Bandwidth, limit":"Bandbreite, Grenze","5,000,000 bytes, dynamic":"5.000.000 Bytes, dynamisch","How much the sender may have unacknowledged at once.":"Wie viel der Sender auf einmal unbestätigt haben darf.","Third message":"Dritte Nachricht","Fourth message":"Vierte Nachricht",Properties:"Eigenschaften","object, 2 properties":"Objekt, 2 Eigenschaften",Information:"Information","object, 4 properties":"Objekt, 4 Eigenschaften","RTMP · 3 messages":"RTMP · 3 Nachrichten","Nothing: AMF0 null.":"Nichts: AMF0-null.","Stream key":"Stream-Key","Which channel this is. It works like a password, and here it travels unencrypted.":"Welcher Kanal das ist. Er wirkt wie ein Passwort und reist hier unverschlüsselt.","Stream ID":"Stream-ID","The new stream: video and audio will go on it.":"Der neue Stream: Video und Audio laufen darüber.","type 0, chunk stream 4":"Typ 0, Chunk-Stream 4","Stream 1, the one createStream made.":"Stream 1, den createStream angelegt hat.","Publishing type":"Veröffentlichungsart","Live: not recorded by this request.":"Live: Diese Anfrage nimmt nichts auf.","type 0, chunk stream 5":"Typ 0, Chunk-Stream 5","object, 3 properties":"Objekt, 3 Eigenschaften",Handler:"Handler",Event:"Ereignis",Metadata:"Metadaten","array of 14":"Array mit 14","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"Codec-IDs wie in Flash-Videodateien: 7 ist H.264, 10 ist AAC.","type 0, chunk stream 6":"Typ 0, Chunk-Stream 6","Frame, codec":"Bild, Codec","0x17 (key frame, H.264)":"0x17 (Keyframe, H.264)","AVC packet type":"AVC-Pakettyp","0 (decoder settings)":"0 (Decoder-Einstellungen)","The sequence header: the settings a decoder needs before the first frame.":"Der Sequence Header: die Einstellungen, die ein Decoder vor dem ersten Bild braucht.","Composition time":"Kompositionszeit","The H.264 profile, level and parameter sets.":"Profil, Level und Parametersätze von H.264.","AAC; the other bits are fixed for AAC.":"AAC; die übrigen Bits sind bei AAC fest.","AAC packet type":"AAC-Pakettyp","Sample rate and channels, for the decoder.":"Abtastrate und Kanäle, für den Decoder.","1 (video)":"1 (Video)","Compressed picture data.":"Komprimierte Bilddaten.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"Der Keyframe: ein ganzes Bild. Alle 4.096 Bytes setzt ein 1-Byte-Chunk-Header ihn fort."},r=n=>`${n} ${n==="1"?"Record":"Records"}`,l={strings:{...d,...o,...a},patterns:[[/^([\d,]+) bytes$/,"$1 Byte"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 Byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 Byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 Byte: report.pdf, Byte $2"],[/^(.+) h later$/,"$1 h später"],[/^(.+) min later$/,"$1 min später"],[/^(.+) s later$/,"$1 s später"],[/^(\S+) \(relative\)$/,"$1 (relativ)"],[/^(\d+) \(ephemeral\)$/,"$1 (kurzlebig)"],[/^(\d+) TCP segments$/,"$1 TCP-Segmente"],[/^(\d+) segments$/,"$1 Segmente"],[/^(.*), (\d+) segments$/,"$1, $2 Segmente"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(n,e,t,s)=>`TLS 1.3 · ${r(e)} · Byte ${t} von ${s}`],[/^TLS 1\.3 · (\d+) records?$/,(n,e)=>`TLS 1.3 · ${r(e)}`],[/^Ethernet padding · (\d+) bytes$/,"Ethernet-Padding · $1 Byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 Null-Bytes, bis zum Minimum von 300 Byte"],[/^(\d+) zero bytes$/,"$1 Null-Bytes"],[/^(\d+) random bytes$/,"$1 Zufallsbytes"],[/^Seen as it leaves (.+)$/,"Gesehen beim Verlassen von $1"],[/^Option (\d+)$/,"Option $1"],[/^value (\d+), echo (\d+)$/,"Wert $1, Echo $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 Byte, plus $1 Byte Optionen."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows beginnt bei $1. Hier absichtlich auf $2 gesetzt."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(n,e,t)=>t==="1"?`Begann bei ${e}; der Router auf dem Weg zog 1 ab.`:`Begann bei ${e}; jeder der ${t} Router auf dem Weg zog 1 ab.`],[/^all (\d+) bytes of it$/,"alle $1 Byte davon"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Das Paket, das dies ausgelöst hat, so wie das meldende Gerät es empfangen hat (TTL $1), damit der Absender weiß, um welches Paket es ging."],[/^Port (\d+), TLS from the start$/,"Port $1, TLS von Anfang an"],[/^(\d+), TLS from the start$/,"$1, TLS von Anfang an"],[/^type 79, (\d+) bytes$/,"Typ 79, $1 Byte"],[/^(\d+) of (\d+) bytes$/,"$1 von $2 Byte"],[/^(\d+) more bytes$/,"$1 weitere Byte"],[/^offset (\d+), (\d+) bytes$/,"Offset $1, $2 Byte"],[/^offset 0, (\d+) bytes \(all of it\)$/,"Offset 0, $1 Byte (alles)"],[/^record, (\d+) bytes$/,"Record, $1 Byte"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · Nachricht $1 von 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(n,e,t,s)=>`${e??""}${t}-${s==="request"?"Anfrage":"Antwort"}`],[/^(\d+) registers$/,"$1 Register"],[/^id 1: −(\d+) dBov, voice$/,"ID 1: −$1 dBov, Sprache"],[/^"(.*)" \(([\d,]+) bytes\)$/,'"$1" ($2 Byte)'],[/^(masked|not masked), (\d+) bytes?$/,(n,e,t)=>`${e==="masked"?"maskiert":"nicht maskiert"}, ${t} Byte`],[/^(\d+) \(disguised\)$/,"$1 (verschleiert)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$1 ($2), $3 Byte"],[/^0 \(none\), (\d+) bytes$/,"0 (keine), $1 Byte"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), Typ $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (Register $2)"],[/^yes, AS (\d+)$/,"ja, AS $1"],[/^id 2, (\d+) bytes$/,"ID 2, $1 Byte"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, wie im SDP vereinbart)"]],post:i};export{l as default};
